INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '16230537266', 'Bloco de notas adesivas Post-it coleção Oásis 3 blocos de 76x76mm 270 folhas 3M', 'Bloco de notas adesivas Post-it coleção oásis 76x76mm 270 folhas - 3M Nova coleção dos famosos blocos de notas adesivas Post-it em packs com mais variedades de cores. Suas ideias e sonhos só começam a tomar forma quando sua caneta encontra o papel. Porque quando você coloca suas ideias no papel, faz delas um pouco mais reais. Notas Post-it são as melhores parceiras neste ponto de conexão. É a transformação de seus pensamentos e os murais coloridos de Notas Post-it que iluminam as ideias de todos. Suas folhas são reposicionáveis, ou seja, possuem Super Adesivo Post-it, que permite que sejam retirados e recolocados, sem danificar papéis ou outras superfícies, sem deixar resíduos do adesivo e sem perder a eficiência na fixação. Sua embalagem é transparente e permite que você visualize a cor real do produto, além de protegê-lo, fazendo com que chegue sem nenhuma sujeira ou mancha em suas mãos. Tenha os blocos de notas adesivas Post-it sempre à mão em seu escritório ou em casa, dentro de seu caderno, da bolsa, próximo ao telefone, cabeceira da cama ou onde mais quiser. Detalhes: - Tamanho: 76 x 76 mm - Contém: 3 blocos adesivo com 90 folhas cada - Cores: Azul céu, verde limeade e verde limão - Ideal para anotar compromissos, tarefas, recados e tudo mais que você precisar.', 46.44, 46.44, NULL, 'Stationery > Notebooks & Papers > Memo & Sticky Notes', 'https://cf.shopee.com.br/file/sg-11134201-824ix-mf2yr2w8q5u557', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400736454%2F16230537266', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
