INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23593346743', 'Colageno Skin - Cranberry - Lata 300g - Sanavita', 'COLAGENO SKIN - CRAMBRERRY - LATA 300G O Colágeno Skin da Sanavita combina 9g de peptídeos ativos de colágeno de alta absorção a um complexo antioxidante que atende 100% das necessidades diárias de vitaminas A, C, E e o mineral zinco, todos com ação antioxidante. Sua fórmula precursora de colágeno é uma grande aliada da saúde e beleza da pele, nutrindo e mantendo-a protegida dos danos causados pela ação dos radicais livres. A vitamina C auxilia na formação do colágeno e juntamente com a vitamina E e o zinco são importantes antioxidantes. A vitamina A contribui para a manutenção da pele, e o zinco, além da pele, contribui para a manutenção do cabelo e das unhas. A Sanavita é referência em colágeno no Brasil e sua fórmula é pioneira no mercado, aprovada em estudo clínico com apenas 3 meses de uso.', 134.9, 78.9, NULL, 'Health > Food Supplement > Beauty Supplements', 'https://cf.shopee.com.br/file/sg-11134201-7rff1-m3p2haau9od957', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1308390046%2F23593346743', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
