INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209405699', 'Salsicha Hot Dog Seara', 'A Salsicha Hot Dog Seara é produzida com carnes de qualidade e tem um sabor temperado no ponto certo, perfeita para o seu cachorro-quente e lanches rápidos! Modo de Preparo: Em uma panela, ferva água, após fervura, coloque as salsichas e deixe cozinhar por 3 minutos. Ingredientes: Carne mecanicamente separada de frango, carne suína, carne de frango, água, proteína de soja, pele de frango, fécula de mandioca, sal, dextrose, pimenta-branca, cebola, pimenta-da-Jamaica, açúcar, aromas naturais e aromas idênticos aos naturais, estabilizantes, realçador de sabor glutamato monossódico, antioxidante eritorbato de sódio, corantes: carmim de cochonilha e urucum, conservante nitrito de sódio.', 11.49, 11.49, NULL, 'Food & Beverages > Others', 'https://cf.shopee.com.br/file/sg-11134201-81zwt-miyqaa6s92bm30', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554932%2F58209405699', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42331099407', 'Minhas Primeiras 1000 Palavras em Inglês', 'Um livro de nomeação totalmente ilustrado para apresentar uma ampla gama de vocabulário cotidiano a uma criança e , ao mesmo tempo, desenvolver habilidades de observação e percepção pela associação e memorização.', 17.15, 17.15, NULL, 'Books & Magazines > Books > Fantasy', 'https://cf.shopee.com.br/file/sg-11134201-823qo-mojwjcd2b47549', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F42331099407', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '56060972242', 'Bênção do Oficial Celestial - Livro 2 (Tian Guan CI Fu)', 'Um deus caído... Um fantasma ascendido. Para investigar o que acontecera com um oficial celestial, Xie Lian se infiltra na Cidade Fantasma junto de outros dois companheiros oficiais, onde reencontra o Rei Fantasma Hua Cheng. O fantasma não só o ensina pacientemente a jogar dados, como também lhe empresta sua própria sorte, além de presenteá-lo, sem pestanejar, com um arsenal inteiro de armas. Xie Lian, por sua vez, consegue encontrar o oficial celestial em apuros, mas, no processo, acaba incendiando a residência de Hua Cheng, bem como o arsenal! Dividido entre a culpa e a vergonha, Xie Lian se pergunta como ele, um deus falido, conseguiria compensar tantos danos. Porém, ao retornar ao Reino Celestial, Xie Lian enfrenta uma acusação séria: Ser o Preceptor Estatal de Yong An, responsável pelo massacre no Banquete Dourado… um passado que ele prefere não mencionar, mas do qual não pode escapar. Ao ouvir que Xie Lian havia admitido culpa e planejava se rebaixar novamente, Hua Cheng vai direto à Capital Celestial raptá-lo, determinado a descobrir a verdade por trás daquele derramamento de sangue. Tian Guan CI Fu', 80.91, 80.91, NULL, 'Books & Magazines > Books > Fantasy', 'https://cf.shopee.com.br/file/sg-11134201-823r8-mojsoe9gegp72e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F56060972242', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41076217591', 'Manopla Silicone Gts Soft Bike Hand Grip Super Macia Cor Laranja', 'Punho Silicone Soft GTS O Punho Silicone Soft GTS é ideal para ciclistas que buscam conforto e segurança na pegada durante as pedaladas. Feito em silicone macio, proporciona aderência firme e evita o desgaste das mãos, mesmo em longos trajetos. Seu design ergonômico e material resistente garantem durabilidade e melhor controle da bicicleta em diferentes condições. A cor verde oferece um visual moderno e diferenciado para a bike. Especificações técnicas Marca: GTS Material: silicone soft Tipo: punho para guidão Indicação: uso em bicicletas diversas', 14.9, 11.99, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/sg-11134201-821es-mgrwunttr2tl8c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F990966849%2F41076217591', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '25944905036', 'Cozy capybaras - Ciranda Cultural', 'Inspirado no fenômeno dos livros de colorir para relaxamento do TikTok,o livro COZY CAPYBARAS é perfeito para quem ama transformar momentos simples em uma verdadeira experiência calmante. Impressas em papel de alta gramatura, para garantir a melhor qualidade de pintura, as 48 páginas com 23 ilustrações exclusivas e uma página para você testar cores e texturas retratam momentos cotidianos e aconchegantes, permitindo que você explore sua criatividade ao máximo, seja colorindo com lápis de cor ou marcadores. Livre para todos os públicos, este livro é perfeito para aliviar o estresse e se desconectar da correria do dia a dia.', 25.65, 25.65, NULL, 'Books & Magazines > Books > Comics & Manga', 'https://cf.shopee.com.br/file/sg-11134201-7rffl-m9a8sak6gkaocf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F25944905036', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23198317140', 'Mochila Masculina Executiva Smart Urban para Notebook Preta', 'Mochila Masculina Executiva Smart Urban para Notebook Preta A Smart Urban é a mochila que leva tudo o que você precisa sem parecer muito grande. Perfeita para quem quer um visual mais minimalista e moderno, ela oferece funcionalidade, com poucos bolsos, servindo como um modelo mais elegante e ideal para ambientes formais. É perfeita para ir da faculdade ao trabalho! Tem acabamento emborrachado nos recortes dos bolsos frontais e conta com compartimento para notebook e tablet de até 16”. O modelo pode ser encontrado nas cores cinza, preto e verde. DIFERENCIAIS: • Material Resistente • Bolso frontal com organizador • Compartimento para notebook e tablet de até 16" • Abertura diferenciada para notebook • Alça carona, para fixar na mala • Alças ajustáveis Divisórias Internas: Compartimento para Notebook Está mochila notebook conta com porta notebook para você conseguir transportar seus equipamentos com mais segurança Carteira de Couro Feita de couro legítimo de alta qualidade, essa carteira é durável e resistente ao desgaste do dia a dia Cinto de Couro Feito de couro legítimo de alta qualidade, esse cinto é durável e resistente ao desgaste do dia a dia Mochila de Couro Feito de couro legítimo de alta qualidade, essa mochila é durável e resistente ao desgaste do dia a dia Pasta de Couro Feito de couro legítimo de alta qualidade, essa pasta é durável e resistente ao desgaste do dia a dia Bolso Frontal com Zíper A Mochila contém um bolso frontal espaçoso com zíper. Bolso Frontal com Zíper As Lancheiras termicas contém um bolso frontal espaçoso com zíper. Bolso Frontal com Zíper Especicações: Marca: Bagaggio Gênero: Unissex Dimensões: A: 42 x L: 30 x P: 14,5 Material: Poliéster Cor: Preto Marca: Bagaggio Rod