INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22298067029', 'Chinelo Mississipi Com Brilhos MC611', 'Produto marca Mississipi. Eleve sua autoestima e seus looks com o o Chinelo Mississipi com Brilhos da coleção Primavera/Verão 2024 que está disponível na cor ! Perfeito para mulheres que buscam estilo e praticidade no dia a dia, esse modelo combina o salto baixo, que é elegante e charmoso, com detalhes sofisticados, trazendo versatilidade e praticidade para seus dias! A palmilha de EVA proporciona conforto e maciez ao caminhar, assim como o salto bloco de 2 cm, que é elegante. Já as tiras finas envolvem seus pés com delicadeza, proporcionando um ajuste perfeito. o destaque fica por conta dos brilhos aplicados nas tiras, que adicionam um toque de elegância e sofisticação ao seu visual. Seja para um passeio no parque, um dia de compras ou um happy hour com as amigas, esse chinelo te acompanha em qualquer ocasião, garantindo um look moderno e cheio de estilo. Peso: 0,390 kg Altura do salto: 2,0 cm', 129.9, 129.9, NULL, 'Women Shoes > Flat Sandals & Flip Flops > Flip Flops', 'https://cf.shopee.com.br/file/sg-11134201-7rfi0-m30protaxlb82f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1082095796%2F22298067029', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '57706705383', 'Starter Pack Enaldinho Copa + Starter Pack Cards Enaldinho + Mítico - Novo - Editora Pixel', 'Starter Pack Enaldinho Copa + Starter Pack Cards Enaldinho + Mítico Este Starter Pack Enaldinho na Copa contém: 1 Livro ilustrado 3 Livros de Curiosidades 3 Cabeçudinhos 1 Estojo para Colecionar Starter Pack Cards Elo Monsters contêm: 8 Tokens de Cristal 4 Flow packs (20 cards sortidos) 1 Guia de Regras 1 Porta-cards 1 Tabuleiro Cards: 4 Flow packs (20 card sortidos) e 1 Card Mítico Exclusivo Coleção Enaldinho na Copa - Viagem pelas Maiores Seleções de Futebol. A bola vai rolar!! A Coleção Enaldinho na Copa convida crianças e fãs do esporte a entrarem em campo com Enaldinho e Golito em uma superviagem pelas 20 maiores seleções de futebol de todos os tempos. Segmentos: Colecionáveis, Colecionáveis - Entretenimento Marcas: Pixel Editora: Editora Pixel Idioma: Português Condição: Novo/Lacrado', 259.7, 259.7, NULL, 'Hobbies & Collections > Collectible Items > Sports Collectibles', 'https://cf.shopee.com.br/file/sg-11134201-8260h-mldr755xqpdw7f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F642933481%2F57706705383', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44474982156', 'Comic - Conan, O Bárbaro (2024) 10 - Novo/Lacrado', 'Conan, O Bárbaro (2024) 10 Convencidos a se unirem à ladra Tarnasha para roubar uma relíquia stygia, Conan da Ciméria e Bêlit descobrem que um simples golpe não tem nada de simples. Enquanto Conan e Bêlit dizimavam os inimigos restantes, Tarnasha tomou a relíquia para si e sumiu na noite, obrigando a dupla a fugir. Dois anos se passaram, mil dias desde que Conan viu Bêlit pela primeira vez. Agora, nas terras dos Reinos Negros, a Rainha da Costa Negra está morta e seus anos de saques chegaram a um tenebroso fim. Conan está a sós com seu luto em selva hostil e desconhecida. Tipo de Produto: Revista Segmentos: Comics Marcas: Conan Autor(es): Doug Braithwaite, Jim Zub ISBN: 9786525942117 Check-List: Novembro/2025 Classificação Etária: 12 anos, 16 anos Editora: Panini Número de páginas: 48 Tipo de capa: Canoa Data de Lançamento: 21/11/2025 Idioma: Português Condição: Novo/Lacrado', 28.9, 28.9, NULL, 'Books & Magazines > Books > Comics & Manga', 'https://cf.shopee.com.br/file/sg-11134201-825a8-mg08oot3ib6253', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F642933481%2F44474982156', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
