INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21256361179', 'Guanidina Óleo Semente de Manga Alisa e Relaxa Salon Line 215gr', 'Salon Line Guanidina Óleo de Semente de Manga alisa, relaxa e reduz o volume dos cabelos, deixando-os mais lisos e soltos. Sua fórmula proporciona um resultado rápido e eficiente, além de conter Óleo de Semente de Manga, que hidrata, recupera e fortifica o fio. A Guanidina é compatível com Hidróxido de Sódio e Lithium, e incompatível com Tioglicolato de Amônia. Cuidado com colorações que contenham Amônia.', 35.0, 27.0, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-8258h-mfu7v61jmx3j20', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F616222685%2F21256361179', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19798973264', '9 unidades Cereal Infantil Mucilon de Cereais 360g', 'Características principais do produto: Marca:Nestlé Modelo:Mucilon Segmento:Cereal Infantil Informações Adicionais do Produto: Rico em nutrientes que contribuem para a Imunidade e Desenvolvimento Cerebral. Proporciona uma alimentação equilibrada. Rico em Vitamina A, C, D, E, B6, B9, ferro e zinco. 13 Vitaminas e Minerais. Vitaminas A, C, D, E, B6, B9 (ácido fólico), ferro e zinco.O Ferro e o Zinco ajudam nos processos responsáveis pelo desenvolvimento adequado do cérebro. Modo de Preparo: 1.Lave as mãos antes de preparar os alimentos do seu filho. Use somente utensílios higienizados. 2.Em uma tigela ou prato fundo, coloque 170 ml de leite líquido morno. 3.Misture, aos poucos, 3 colheres de sopa cheias (21g) de Mucilon® Multicereais até ficar homogêneo. 4.Sirva imediatamente com uma colher limpa. Alergênicos: contém derivados de trigo. pode conter leite, soja, centeio, cevada e aveia. contém glúten. Ingredientes após o preparo: farinha de trigo enriquecida com ferro e ácido fólico (60%), açúcar, farinha de milho enriquecida com ferro e ácido fólico (14%), farinha de arroz (5,3%), cálcio (carbonato de cálcio), vitamina C (ácido L-ascórbico), ferro (fumarato ferroso), zinco (sulfato de zinco), vitamina E (acetato de DL-¿-tocoferila), niacina (nicotinamida), ácido pantotênico (D-pantotenato de cálcio), vitamina B1 (tiamina mononitrato), vitamina A (acetato de retinila), vitamina B6 (cloridrato de piridoxina), ácido fólico (ácido N-pteroil-L-glutâmico), vitamina D (colecalciferol), regulador de acidez fosfato de sódio dibásico e aromatizante vanilina. Fornecedor:Nestlé', 120.15, 120.15, NULL, 'Mom & Baby > Milk Formula & Baby Food > Baby Porridge, Puree & Cereal', 'https://cf.shopee.com.br/file/sg-11134201-824io-mpiblkpf73f0d5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F822103155%2F19798973264', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
