INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23196806817', 'Fralda Descartável Huggies Máxima Proteção Mega Tamanho M - 6 Pacotes com 40 Fraldas - Total 240 Tiras', 'Características do Produto: Marca: Huggies Tamanho: M Modelo: Fralda Descartável Peso Recomendado: 5,5 a 9,5kg Informações Gerais: Proteção: 12 horas Público Destinado: Infantil Quantidade de Pacotes: 6 Quantidade por pacote: 40 Unidades Ação Esperada do Produto: Absorver; Confortar; Dar Flexibilidade; Proteger Modo de Uso: Como colocar? Abra a fralda e as orelhas traseiras e levante as barreiras. Coloque o bebê e verifique se a fralda está cobrindo suas costas até a cintura. Como fechar? Descole as orelhas e fixe-as sobre a faixa frontal da fralda, ajustando-as de acordo com o corpinho do bebê. Quando a orelha chegar ao ícone passante, mude para um tamanho maior. Como ajustar? Ajuste o elástico das pernas para garantir que não dobre por cima das barreiras internas. Fornecedor: Huggies', 377.65, 314.9, NULL, 'Mom & Baby > Diapering & Potty > Disposable Diapers', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mgryz4r9e4nb6c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F822103155%2F23196806817', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
