INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58250678907', 'CHAVE COMBINADA CROMO VANADIO FOSFATIZADA 13MM 1PC // SPARTA', 'Chave Combinada Sparta 1490855 – 13 mm Ferramenta precisa e resistente, ideal para uso profissional e doméstico em montagem, manutenção e reparos. Principais Vantagens: Alta resistência e durabilidade: Produzida em aço cromo-vanádio (CrV) forjado a quente, com dureza entre 42–47 HRC, suportando trabalhos intensos e uso prolongado. Proteção contra corrosão: Acabamento fosfatizado que protege contra oxidação, garantindo longa vida útil mesmo em ambientes agressivos. Eficiência em espaços limitados: Anel interno com 12 lados permite giro com apenas 30°, facilitando o uso em locais de difícil acesso. Versatilidade: Compatível com fixadores hexagonais e dodecagonais de 13 mm, adequada para diversas aplicações. A Chave Combinada Sparta 1490855 une robustez, funcionalidade e design inteligente, sendo indispensável para quem busca desempenho e confiabilidade.', 13.2, 13.2, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-821fj-mh698vi5y973ef', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1577891436%2F58250678907', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
