INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23698838346', 'VONIXX REJUVEX PLASTICO EXTERNO', 'Rejuvex – Revitalizador de Plásticos Externos Descrição Geral O Rejuvex é um revitalizador de plásticos desenvolvido para renovar, proteger e dar brilho em plásticos externos de automóveis. Produzido com matérias-primas especiais, é altamente recomendado para uso em oficinas de repintura automotiva. Benefícios Não sai com água; Não contém silicone; Excelente cobertura e acabamento uniforme; Realça a aparência original das peças plásticas. Disponibilidade Embalagem: 400 g Instruções de Uso Certifique-se de que a superfície esteja limpa e seca. Aplique uma pequena quantidade do produto diretamente sobre o plástico. Utilize uma esponja e faça movimentos circulares até a completa cobertura da peça. Evite excesso de produto. Caso necessário, remova o excesso com um pano de microfibra. Ficha Técnica Código: 133 Modelo: VNX Categoria: Plástico – Proteção Vintex Marca: VONIXX', 38.9, 38.9, NULL, 'Spare Parts and Accessories for Vehicles > Others', 'https://cf.shopee.com.br/file/sg-11134201-824gw-mdw34fdl3lducf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1023746412%2F23698838346', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
