INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18299927910', 'Whey Crisp Bar Gourmet - 1 Barra 45g Trufa de Coco - New Millen', 'O Whey Crisp Bar Protein da New Millen é uma barrinha de proteína gourmet que oferece uma combinação deliciosa de sabor e nutrição. Experimente o Whey Crisp Bar Protein e aproveite os benefícios das proteínas de forma prática e saborosa! Como Tomar Ingerir uma barra ao dia ou conforme orientação profissional. Ingredientes Blend Proteico (Proteína de soro de leite concentrada, proteína de soja concentrada, colágeno hidrolisado, proteína de soja isolada e caseinato de cálcio), cobertura sabor chocolate ao leite, ganache sabor chocolate branco com coco, crisp de proteína de soja, coco em flocos, gordura de palma, aroma idêntico ao natural, estabilizante carbonato de cálcio, cloreto de sódio, emulsificante lecitina de soja, conservantes benzoato de sódio e sorbato de potássio. NÃO CONTÉM GLÚTEN. CONTÉM LACTOSE. ALÉRGICOS: CONTÉM LEITE, DERIVADOS DE LEITE, AVELÃS E DERIVADOS DE SOJA. PODE CONTER OVO E AMENDOIM. ...', 19.45, 19.45, NULL, 'Food & Beverages > Breakfast Cereals & Spread > Breakfast Bar', 'https://cf.shopee.com.br/file/sg-11134201-824h4-mfow734d8xe175', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F976704374%2F18299927910', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '11042340545', 'Espátula Multiuso de Plástico 12cm Lisa - Castor', 'A Espátula plástica multiuso 12 cm da Castor é ideal para criação de efeitos decorativos com texturas lisas ou granuladas. Indispensável no manuseio de gesso, rejunte comum, rejunte à base de epóxi, massa corrida, resinas acrílicas, vinílicas e produtos similares. Apresenta grande flexibilidade na hora da aplicação. CARACTERÍSTICAS Material da chapa: Plástico resistente Material do Cabo: Plástico Uso Indicado: Pequenos reparos com massa corrida, aplicação de rejunte epóxi, gesso, argamassa, colas, resinas, etc. Auxiliam na aplicação de papel de parede e podem ser utilizadas na criação de efeitos decorativos. Também utilizada para aplicação de insulfilm. Vantagens: Pode ser usada com produtos à base de água e solventes. Não empena, não racha e é fácil de limpar e fácil de armazenar. Código do fabricante: 190 Limpeza e conservação: Logo após o uso, retirar os resíduos do produto utilizado. Produtos à base de água, lavar com água e sabão. Produtos sintéticos, lavar com solvente adequado e depois com água e sabão. Secar bem e guardar em local arejado. FERRAMENTAS QUE GARANTEM RESULTADOS PRECISOS Perfeição e versatilidade, tudo o que você precisa em uma só ferramenta. A Castor selecionou as melhores e mais resistentes espátulas para você. Tudo para facilitar a sua vida! SEGURANÇA Compre com segurança! Nossa equipe de suporte estará à disposição caso tenha algum problema ou dúvida. Aguardamos seu pedido!', 22.58, 22.58, NULL, 'Home & Living > Tools & Home Improvement > Wall Paints & Coatings', 'https://cf.shopee.com.br/file/02ce97647674c2a8820f1eca157d6f14', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F524472372%2F11042340545', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58258152625', 'DVD The Cure - The Show Of A Lost World - Importado', 'DVD The Cure - The Show Of A Lost World - Importado Em 1º de novembro de 2024, o aclamado álbum "Songs of a Lost World" do The Cure, indicado ao Grammy, foi lançado. Na noite do lançamento, o The Cure apresentou o álbum na íntegra pela primeira e única vez no Troxy, em Londres, para 3.000 fãs. THE CURE: THE SHOW OF A LOST WORLD é um filme reeditado, remixado e remasterizado do show completo daquela noite, com 31 músicas. Dirigido por Nick Wickham, indicado ao Grammy, com nova mixagem de som surround por Robert Smith. Tracklist: 1. Alone 2. And Nothing Is Forever 3. A Fragile Thing 4. Warsong 5. Drone:Nodrone 6. I Can Never Say Goodbye 7. All I Ever Am 8. Endsong 9. Plainsong 10. Pictures of You 11. High 12. Lovesong 13. Burn 14. Fascination Street 15. A Night Like This 16. Push 17. In Between Days 18. Just Like Heaven 19. From The Edge Of The Deep Green Sea 20. Disintegration 21. At Night 22. M 23. Secrets 24. Play For Today 25. A Forest 26. Lullaby 27. The Walk 28. Friday I''m In Love 29. Close To Me 30. Why Can''t I Be You? 31. Boys Don''t Cry Especificações de áudio: 2.0 Uncompressed LPCM Stereo [48k/16b] 5.1 Dolby Digital Surround', 179.9, 134.9, NULL, 'Hobbies & Collections > CD, DVD & Bluray', 'https://cf.shopee.com.br/file/sg-11134201-8259r-mr0jr6jnzg8w4b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1356917260%2F58258152625', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
