INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22892027423', 'Paleta de Sombras 24 Cores - 24 Eyeshadow Palette 28g', 'Imagina Encontrar, em Uma Única Paleta, Todas As Cores Que Você Mais Ama? e Mais Ainda, Encontrar Aqueles Tons Que São a Tendência do Momento e Você Estava Loucx para Usar? Parece Impossível, Mas É Verdade. Conheça a 24 Eyeshadow Palette. São 24 Cores: 11 Tons Opacos e 13 Cintilantes, Um Mix de Cores Que Se Complementam. Entre Os Básicos Preto e Marrom, Passando Por Tons Mais Sóbrios Como Azul e Verde, As Cores Também Trazem Um Toque de Tendência Como Mostarda e Roxo. Além Disso, a Nova Paleta Reúne Os Atributos Que As Amantes de Make Mais Procuram: Alta Pigmentação, Intensidade de Cor e Alta Fixação, Permitindo Durabilidade o Dia Todo. Tudo Isso, Pensado para Compor Diversos Visuais, Possibilitando à Quem Usá-La Brincar com As Combinações sem Medo de Errar. com Isso, o Produto Torna-Se Prático para Ser Utilizado em Qualquer Ocasião. E Quer Saber a Melhor Parte? a Paleta É Linda, Super Resistente e com Um Espelho Interno Bem Amplo, Perfeita para Ser o Item Must-Have da Temporada! Tamanho: 11 X 1,3 X 26 Cm', 129.9, 129.9, NULL, 'Beauty > Makeup > Eyes', 'https://cf.shopee.com.br/file/sg-11134201-825aw-mr22wu8rl3ie7a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F842559166%2F22892027423', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
