INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58205767609', 'Aditivo Liqui Moly Gear-oil Caixa Marcha E Diferencial 20g', 'LIQUI MOLY GEAR-OIL ADDITIVE 20G Produto novo, com garantia e nota fiscal Fabricante: LIQUI MOLY Contém MoS2 altamente concentrado para a redução do desgaste em transmissões manuais e diferenciais, acionamentos de eixo sem bloqueio do diferencial integrado com funcionamento em óleo, assim como sistemas de direção manuais. O MoS2 evita picos de temperatura e garante um funcionamento mais silencioso e uma maior facilidade na mudança de marcha. A transmissão não aquece tanto e aumenta a suavidade de funcionamento e a capacidade de rendimento através do alisamento dos flancos dos dentes. Características - Resistente a cargas e vibrações - Aumenta a segurança operacional - Garante um funcionamento ótimo da transmissão - Reduz o atrito e o desgaste - Excelentes capacidades de funcionamento de emergência - Reduz os ruídos das engrenagens - Garante um funcionamento sem problemas da transmissão Campos de Utilização Para transmissões manuais e diferenciais, acionamentos de eixo sem bloqueio do diferencial integrado com funcionamento em óleo, assim como sistemas de direção manuais, especialmente sob elevadas cargas térmicas. Utilização Adicionar ao óleo para caixas de velocidades. A mistura ocorre por ação própria durante o funcionamento. É adequado tanto para óleos minerais como sintéticos. 20 g são suficientes para 1 l de óleo para engrenagens. Produto à pronta entrega em nossa loja física em Vinhedo ? SP OBS: PARA COMPRAS COM CNPJ FORA DO ESTADO DE SÃO PAULO, TERÁ O ACRÉSCIMO DO IMPOSTO ST 502956(SUBSTITUIÇÃO TRIBUTÁRIA) *', 101.25, 101.25, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Transmission', 'https://cf.shopee.com.br/file/sg-11134201-8260x-ml415ad1jwg79f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1630762847%2F58205767609', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58250185427', 'Eletrodo Solda Elétrica Vonder 5kg 6013-4,00mm', 'OEletrodo Solda Elétrica Vonder 5kg 6013-4,00Mmrevoluciona suas soldagens industriais e de precisão. O Eletrodo Vonder 6013 4,00mm é a solução definitiva para soldados exigentes que buscam qualidade, especificidade e excelência técnica.Projetado para soldadores que apresentam máxima espessura em estruturas metálicas, este eletrodo garante soldagens limpas, uniformes e com excelente resistência. Perfeito para construção civil, metalurgia, manutenção industrial e projetos que desativam soldas de alta qualidade.Desenvolvido com tecnologia de ponta, o Eletrodo Vonder 6013 oferece facilidade na abertura do arco, proteção de fácil remoção e estabilidade incomparável durante o processo de soldagem. Detalhes do produto: Diâmetro: 4,00mm Peso: 5kg Código EAN: 7893946244040 Norma: AWS/ASME SFA 5.1 - E6013 Tipo de Revestimento: Rutílico Cordões de solda com acabamento impecável', 219.9, 95.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-821fx-mggwapkjfqq5cd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F965617276%2F58250185427', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259713980', 'Gelatina em Pó sabor Tutti-Frutti Dr.Oetker', 'A Gelatina em Pó Dr. Oetker sabor Tutti-Frutti é uma sobremesa deliciosa e refrescante, perfeita para qualquer ocasião. Com vitamina C em sua composição, é uma opção saudável e saborosa para toda a família. Para preparar, basta dissolver o conteúdo do pacote em água fervente, adicionar água fria ou gelada e levar à geladeira até adquirir consistência.', 2.79, 2.79, NULL, 'Food & Beverages > Cooking Essentials > Others', 'https://cf.shopee.com.br/file/sg-11134201-8261u-mj72o9fvfymb11', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554900%2F58259713980', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
