INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23591990505', 'Corrediça De Gaveta Trilho Telescópico 45cm Par Com Parafusos', 'Corrediça Gaveta Trilho Telescópico 45cm Par é um conjunto de trilhos de alta qualidade e resistência, especialmente projetado para otimizar o funcionamento de gavetas em móveis diversos. Com 45 centímetros de comprimento, esse par de corrediças oferece uma solução prática e eficiente para facilitar o acesso aos objetos guardados nas gavetas. O sistema de trilhos telescópicos proporciona um comando suave e silencioso, permitindo que as gavetas fiquem abertas e fechadas de forma fluida, mesmo quando estão completamente carregadas. Além disso, essas corrediças garantem uma montagem simples e segura, tornando a instalação um processo descomplicado e rápido. Fabricadas com materiais duráveis e de alta resistência, as corrediças garantem uma vida útil prolongada e são projetadas para suportar o uso diário, mantendo-se por longos períodos sem desgaste significativo. Se você busca uma solução confiável e eficiente para as gavetas de seus móveis, as Corrediças Gaveta Trilho Telescópico 45cm Par são a escolha ideal, proporcionando praticidade, organização e funcionalidade ao seu ambiente. Com essa ferramenta, você terá facilidade de acesso aos seus pertences e poderá desfrutar de um móvel com maior comodidade e qualidade. Especificações: -Tamanho: 45cm ou 450mm -Largura: 3,5cm -Acompanha parafusos de fixação. Nuvem de tags: Corrediça, Gaveta, Trilho Telescópico, 45cm, Par, Móveis, Deslizamento Suave, Montagem Simples, Resistente, Durável, Organização, Praticidade.', 29.9, 22.9, NULL, 'Home & Living > Furniture > Others', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m9ofrty1cpx5e9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F944577712%2F23591990505', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
