INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23992970065', 'Adaptador Chato 2 Pinos 10A Americano P Redondo Margirius', 'Adaptador 2 Pinos 10a Chato Americano P Redondo Margirius O Adaptador Plug 2 Pinos 10a Chato Americano P Redondo Preto é um produto de alta qualidade da marca MarGirius. Este adaptador, modelo Chato/Redondo, possui um único pino 2P, ideal para quem precisa de uma solução prática e eficiente para conectar seus aparelhos. Suas dimensões são compactas, com 5.50 cm de comprimento, 4.10 cm de largura e 2.50 cm de altura, facilitando o transporte e armazenamento. Além disso, o adaptador tem capacidade para suportar uma voltagem de até 250 volts e uma corrente de 10 amperes, garantindo segurança e eficiência na transmissão de energia. Este pacote inclui 1 unidade do Adaptador 2 Pinos 10a Chato Americano Para redondo Preto, proporcionando um excelente custo-benefício. Vale ressaltar que este adaptador não possui portas adicionais e nem entrada USB, sendo especificamente projetado para a função de adaptação de pinos. Nuvem de Tags: Adaptador, Adaptador Chato, 2 Pino, 2P, Americano, Tomada, Pino, 10A, Americano Redondo, Adaptador Redondo.', 28.9, 15.9, NULL, 'Home Appliances > Electrical Circuitry & Parts > Electric Sockets & Extension Cords', 'https://cf.shopee.com.br/file/br-11134207-7r98o-luta9fids9y8de', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F944577712%2F23992970065', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
