INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '57157077176', 'KIAN MIXER 1000W 3X1 INOX TURBO PRETO 127V', '******* UTILIZAR APENAS EM TOMADAS 110V ******* ******* NÃO UTILIZAR ADAPTADORES, O USO DE ADAPTADOR PODERÁ CAUSAR DANOS AO PRODUTO ******* KIAN MIXER 1000W 3X1 INOX TURBO PRETO 127V Oferece a potência e a durabilidade que você precisa para levar suas receitas ao próximo nível. Com 1000W de potência, garante um desempenho superior, ideal para misturar e bater ingredientes de forma rápida e eficiente. Seu corpo em inox traz um design sofisticado e resistente, perfeito para quem busca qualidade e durabilidade em um único produto. Seja para preparos simples ou receitas mais elaboradas, o Mixer 1000W oferece o máximo em praticidade e eficiência na cozinha. Incluso: Mini Processador de 1 litro, Fue/Batedor e um Copo graduado de 700ml. Frequência: 50/60Hz. Potência de 1000W para misturas rápidas e eficientes. Cinco velocidades para maior controle nas preparações. Função turbo para misturas potentes em segundos. Haste e lâmina de aço inoxidável para durabilidade e resistência. Acessórios inclusos: picador e copo medidor para conveniência. Marca: Kian Cor: Inox Características especiais: Turbo Dimensões do produto: 10P x 10L x 10A milímetros Material: Aço inoxidável *Imagens meramente ilustrativas', 196.57, 178.83, NULL, 'Home Appliances > Kitchen Appliances > Mixers', 'https://cf.shopee.com.br/file/br-11134207-820ls-mpdqd6qyabrade', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F447875552%2F57157077176', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
