INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259690946', 'Coca-Cola Refrigerante 200ml', 'O Refrigerante Coca-Cola é perfeito para acompanhar refeições e matar a sede a qualquer hora do dia. Com a Coca-Cola Original 200ml, você pode levar seu refrigerante para onde quiser, pois a embalagem é prática e tem o tamanho ideal para ser transportada. Bebida de sabor único e refrescante, vendida em mais de 200 países e considerada uma das maiores marcas do mundo.', 1.99, 1.99, NULL, 'Food & Beverages > Beverages > Carbonated Drinks & Tonics', 'https://cf.shopee.com.br/file/sg-11134201-825a0-mqnekjvs0iyped', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554990%2F58259690946', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '51056869652', 'Body Splash Fine Touch Desodorante Colonia Barbours 200ml', 'BODY SPLASH FINE TOUCH DESODORANTE COLONIA BARBOURS 200ML FINE TOUCH – Body Splash Sofisticação, delicadeza e envolvência em perfeita harmonia. Fine Touch é uma fragrância elegante e envolvente que traduz feminilidade em cada detalhe. Sua composição combina frescor frutado, um coração floral refinado e um fundo cremoso e confortável, resultando em uma assinatura delicada e marcante. Caminho Olfativo: Floral Amadeirada Musk Notas de Cabeça: Pêssego Branco, Mandarina e Bergamota Uma abertura suave e luminosa que desperta os sentidos com frescor e leveza. Notas de Corpo: Flor de Laranjeira, Lírio-do-Vale, Petália, Uva de Oregon e Rosa Branca Um coração floral elegante, com nuances modernas e aveludadas que revelam sofisticação e delicadeza. Notas de Fundo: Musk, Âmbar, Baunilha e Sândalo Uma base cremosa e envolvente que proporciona conforto e fixação equilibrada na pele. Modo de Uso: Aplique o Body Splash generosamente sobre a pele limpa e seca, concentrando-se nos pontos de pulsação, como pescoço, pulsos e atrás das orelhas. Reaplique ao longo do dia, se necessário, para manter a fragrância fresca e duradoura. Precauções: Uso externo. Inflamável. Não ingerir. Manter fora do alcance de crianças. Em caso de irritação da pele, suspenda o uso e procure orientação médica. Em caso de contato com os olhos, enxágue abundantemente. Não utilizar próximo a fontes de calor. Composição (INCI): Alcohol, Aqua, Parfum, Phenoxyethanol, Farnesol, Glyceryl Laurate, Citronellol,Geraniol, Hydroxycitronellal, Limonene, Linalool. Composição (Português): Álcool Etílico, Água, Perfume, Fenoxietanol, Farnesol, Laurato de Glicerila,Citronelol, Geraniol, Hidroxicitronelal, Limoneno, Linalol. Fabricado por: Freedom Cosméticos Ltda. CNPJ: 53.402.541/0001-02 AFE/MS: 2.00.833-5 Processo ANVISA Nº: 25351.022267/2026-46 Indústria Brasileira body splash feminino sofisticado, perfume floral amadeirado feminino, fragrância com pêssego branco, perfume com flor de laranjeira, perfume feminino cremoso, body splash doce na medida certa, perfume feminino elegante para o dia, fragrância com rosa branca e jasmim, perfume com âmbar e baunilha, body splash delicado e envolvente, perfume feminino moderno, fragrância feminina marcante suave', 77.9, 54.53, NULL, 'Beauty > Bath & Body Care > Body Deodorants', 'https://cf.shopee.com.br/file/br-11134207-820mb-mpuwcyk4yhab75', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1579330222%2F51056869652', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
