INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40719261746', 'Sandália Infantil Feminina Salto Plataforma Dourada Strass Confortável Brilho Original', 'TABELA DE MEDIDAS Nº 28 - 19 cm Nº 29 - 19,5 cm Nº 30 - 20 cm Nº 31 - 21 cm Nº 32 - 21,5 cm Nº 33 - 22 cm Nº 34 - 23 cm A sandália infantil feminina é a escolha ideal para deixar as meninas ainda mais estilosas em festas e ocasiões especiais. Com tiras delicadas em pedraria e acabamento metalizado, une beleza, conforto e segurança em um só calçado. DESCRIÇÃO Linda sandália infantil feminina com design moderno e elegante. Possui tiras com pedrarias brilhantes que dão um toque sofisticado, palmilha macia para conforto e fechamento em fivela que garante segurança ao caminhar. Perfeita para festas, casamentos, aniversários e momentos especiais. DESTAQUES - Design elegante com tiras em pedraria brilhante - Palmilha macia que garante conforto durante o uso - Acabamento metalizado moderno e versátil - Fechamento em fivela para ajuste seguro e prático - Numeração do 28 ao 34 - Ideal para festas, aniversários e eventos especiais', 149.9, 129.9, NULL, 'Baby & Kids Fashion > Girl Shoes > Sandals', 'https://cf.shopee.com.br/file/br-11134207-81ztv-mkmvg64lp3pc0e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1296584125%2F40719261746', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23298912123', 'RESERVATÓRIO DE ÁGUA DO RADIADOR VOLKSWAGEN PASSAT 1.8 20V TURBO 1998 A 2003', 'RESERVATÓRIO DE ÁGUA DO RADIADOR VOLKSWAGEN PASSAT 1.8 20V TURBO 1998 A 2003 ESPECIFICAÇOES TÉCNICAS: CONECTOR 2 PINOS C/TAMPA C/SENSOR C/2 SAÍDAS COMPATÍVEL COM OS MODELOS: AUDI A4 1.8 20V TURBO 1998 A 2005 AUDI A4 2.8 30V V6 1998 A 2000 AUDI A6 2.8 30V V6 1997 A 2001 VOLKSWAGEN PASSAT 1.8 20V TURBO 1998 A 2003 VOLKSWAGEN PASSAT 2.8 30V V6 1998 A 2005 NUMERO ORIGINAL/SIMILAR: 8D0121403L GARANTIA: 3 MESES DUVIDAS FREQUENTES: VOCÊS SÃO CONFIÁVEIS? R: SIM, BASTA OLHAR NOSSA REPUTAÇÃO E MEDALHA . PRESTAMOS UM ÓTIMO ATENDIMENTO E DESPACHAMOS OS PRODUTOS NO PRAZO. AS FOTOS DO PRODUTO SÃO REAIS? R: SIM, FOTO REAL DA PEÇA. A QUALIDADE DO PRODUTO É BOA? R: SIM, TODOS OS NOSSOS PRODUTOS SÃO NOVOS E COM GARANTIA. QUAL O PRAZO DE ENTREGA? R: VOCÊ PODE VERIFICAR O PRAZO DE ENTREGA NA TELA INICIAL ABAIXO DO PREÇO DO PRODUTO. VARIA DE REGIÃO PARA REGIÃO. DEVOLUÇÃO E TROCAS COMO FAZER? R: A DEVOLUÇÃO É GRÁTIS; VOCÊ PODE TROCAR O PRODUTO SE NÃO FICAR SATISFEITO (PRAZO DE 30 DIAS APÓS RECEBER). EM CASO DE GARANTIA COMO FAZER? R: EM CASO DE GARANTIA, ENTRAR EM CONTATO VIA CHAT PARA FAZER A TROCA DA PEÇA. POSSO RASTREAR MEU PEDIDO? R: SIM, APÓS A COMPRA, LIBERA O CÓDIGO DE RASTREAMENTO PARA VOCÊ ACOMPANHAR O PEDIDO EM TEMPO REAL ATÉ A CHEGADA. APÓS A COMPRA, PODEREI MADAR MENSAGEM PARA O VENDEDOR? R: SIM, APÓS A COMPRA CONFIRMADA, O CHAT É LIBERADO. ACESSE O CHAT NO MENU "MINHAS COMPRAS". O PRODUTO É COMPATÍVEL COM MEU VEÍCULO? R: OBSERVE QUE NA DESCRIÇÃO DISPONIBILIZAMOS A COMPATIBILIDADE DA PEÇA. SE O SEU VEÍCULO NÃO ESTIVER LISTADO, NOS FAÇA UMA PERGUNTA AQUI ABAIXO ENVIANDO MODELO E ANO QUE CONFIRMAREMOS A APLICAÇÃO. 19 de setembro de 2025', 210.49, 210.49, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-82585-meufu134thxia7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1355263989%2F23298912123', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
