INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22994155651', 'Tinta Toque Fosco Select Tons de Azul Mais Vendidos 3,2L Suvinil', 'Essa segunda tinta fosca da linha Suvinil Toque oferece pintura uniforme até nos cantinhos mais difíceis. Ela facilita o retoque e o recorte, além de disfarçar pequenas imperfeições, algo característico do acabamento.Na escala de benefícios, esse produto entrega bom nível de pintura lisa e uniforme, assim como resistência à limpeza. Você pode usar a tinta em ambientes internos de massa acrílica, massa corrida, gesso, textura, reboco, fibrocimento e concreto.Marca: SuvinilAcabamento: FoscoAmbiente indicado: Internos e ExternosSuperfícies indicadas: Indicado para superfícies de reboco, massa acrílica, texturas, concreto, fibrocimento em ambientes internos e externos e superfícies de massa corrida e gesso em ambientes internos não molháveis.Linha: Toque Fosco Tipo de Tinta: Acrílico Premium Volume da embalagem: 3,2LRendimento acabado (3,2L): até 23 m²Secagem ao toque: 2 horasSecagem entre demãos: 4 horasSecagem final: 12 horasÉ inflamável? NãoFerramenta indicada para aplicação: Rolo de lã ou trincha.Números de demãos indicadas: 2 a 3 (O número de demãos pode variar dependendo da superfície e cor escolhida)Resistência à abrasão úmida com pasta abrasiva de acordo com a ABNT NBR 14940 (lavabilidade): = 100 ciclosPoder de cobertura seca de acordo com a ABNT NBR 14942: = 6,5 m2/litrosPoder de cobertura de tinta úmida de acordo com a ABNT NBR 14943: = 90,0 %Resistência ao crescimento de fungos em placa de Petri, com lixiviação de acordo com a ABNT NBR 15987: ResisteBrilho de acordo com a ABNT NBR 15299: = 7 UBDiluição: 30% de água potávelPrazo de Validade (embalagem fechada e sem uso): 36 MesesTintas para ambientes internos e externos.01 Tinta Toque Fosco Select Base C2 3,2L Suvinil', 154.83, 154.83, NULL, 'Home & Living > Tools & Home Improvement > Wall Paints & Coatings', 'https://cf.shopee.com.br/file/sg-11134201-7rato-mb2wsxtjlp3l60', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1425275679%2F22994155651', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
