INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '46808101357', 'Mini System Lg Xboom 2350w Rms', 'Mini System LG Xboom CL87 2350W RMS O Mini System LG XBOOM CL87 2350W RMS é um sistema de som potente desenvolvido para festas e ambientes que exigem alto desempenho sonoro. Com 2350W RMS de potência, oferece graves intensos, alta pressão sonora e excelente qualidade de áudio para músicas, eventos e entretenimento doméstico. O modelo conta com iluminação multicolorida sincronizada com a música, efeitos de DJ e recursos de karaokê, tornando a experiência mais interativa. Além disso, possui diversas opções de conectividade, permitindo reproduzir músicas via Bluetooth, USB ou entradas auxiliares. Características do Produto Marca: LG Linha: Xboom Modelo: CL87 Tipo: Mini System / Sistema de som Áudio Potência total: 2350W RMS Sistema de som estéreo com 2 caixas acústicas Woofer de alto desempenho para graves profundos Equalizador e modos de som pré-definidos Conectividade Bluetooth 2 portas USB 2 entradas auxiliares (AUX) Entrada para microfone (P10) Rádio FM integrado Recursos Iluminação LED com efeitos sincronizados com a música Função Karaokê Efeitos DJ (Scratch, Flanger, Phaser, Delay e outros) Multi Bluetooth para conectar mais de um smartphone Controle por aplicativo LG XBOOM Alimentação Bivolt automático (100–240V) Frequência: 50/60 Hz', 2400.0, 1489.0, NULL, 'Audio > Home Audio & Speakers > Speakers', 'https://cf.shopee.com.br/file/sg-11134201-8259x-mqnfwc39klqb77', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1509845472%2F46808101357', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
