INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18199274823', 'Bíblia Sagrada NVI | Leitura Perfeita | Zíper | Couro Soft | Roxo', 'Parte da coleção de Bíblias A promessa , a capa Em memória de mim retoma a Santa Ceia. O cálice e o pão são partes centrais da última refeição de Jesus com seus apóstolos. Jesus nos ensina que o pão representa seu corpo, o qual comemos sua memória e que o cálice representa a nova aliança criada por seu sangue derramado na cruz. Conta com uma capa em couro soft roxo, desenho em baixo relevo e um toque especial em hot stamp. Seu grande diferencial é o fechamento em zíper, que traz conforto e praticidade para levá-la a qualquer lugar, seja na igreja ou para carregar na bolsa no dia a dia. Além disso, seu texto está na versão NVI (Nova Versão Internacional), que se baseia na precisão, clareza e uma abordagem contemporânea e, ao mesmo, fiel ao texto original. Nela, você encontrará ainda a fonte Leitura Perfeita. Desenvolvida exclusivamente para a Thomas Nelson Brasil, a Leitura Perfeita é uma fonte singular, moderna, bonita, clara e legível, ao mesmo tempo em que integra os melhores avanços em tipografia de bíblias modernas. O resultado é uma tipologia que traz total conforto na leitura em qualquer tamanho Adquira a Bíblia Em memória de mim e tenha a palavra de Deus contigo todos os dias!CaracterísticasTexto na tradução NVI (Nova Versão Internacional)Capa em couro softFonte leitura perfeitaHot StampAcabamento lateral em zíper 14x21cm 1184 Páginas', 77.9, 74.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rd60-lvrefmdlmywn15', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F18199274823', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18317452483', 'O Conhecimento Revelado | Luciano Subirá', 'Há um nível de conhecimento e compreensão da Palavra de Deus que não pode ser alcançado com a mente, independente de quão intelectual e brilhante se possa ser. Trata-se do entendimento espiritual, de ver além do natural, e ser tocado não apenas na razão, mas no íntimo do coração. Nessa leitura você será desafiado a aprofundar-se ainda mais na meditação e compreensão das Escrituras Sagradas. 14X21CM 127 Páginas', 31.9, 20.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m6inzd92bubr94', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F18317452483', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
