INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23893150423', 'Livro Quebra-cabeça - Davi e Golias', 'Conheça a história de Davi, um menino que ousa enfrentar o gigante Golias para salvar os hebreus, e aproveite para se divertir montando quebra - cabeças em cada página. Chame seus amigos e família para brincar e aprender com você! 11x17cm 06 Páginas', 11.9, 7.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rffl-m4fyhy1rpb0k11', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F23893150423', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8214064296', 'João Batista - O Pregador Politicamente Incorreto - Ciro Sanches', 'Usando o seu já consagrado estilo leve e bem-humorado, Zibordi nos brinda com um estudo abrangente sobre a vida de um pregador que não buscou ser aceito pelos religiosos de sua época, mas antes priorizou anunciar a verdade do Senhor. João Batista: O pregador politicamente incorreto é o primeiro de uma série de sete livros que se baseiam nas marcas de sete personagens neotestamentários – João Batista, Jesus Cristo, Pedro, Estêvão, Filipe, Barnabé e Paulo. Estes estudos buscam identificar qualidades de cada, mas, principalmente, descobrir aquela que era compartilhada por todos. 112 páginas 21x14cm', 22.95, 20.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/4444f7f1de451841aa475bfbae8072a1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F8214064296', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
