INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22193912858', 'Bíblia Sagrada Pequena NAA | Letra Gigante | PJV | Couro Sintético | Preta', 'Com um visual elegante e moderno, esta Bíblia com letra gigante oferece uma experiência de leitura mais dinâmica e agradável, além de destacar as Palavras de Jesus em Vermelho. A Nova Almeida Atualizada, lançada em 2017 pela SBB, incorpora o que há de mais avançado nos estudos teológicos e científicos sobre as Escrituras e seu contexto original. Resultado de uma profunda revisão da consagrada tradução Almeida Revista e Atualizada, a Nova Almeida Atualizada apresenta um texto clássico com uma linguagem atual, seguindo a norma padrão do português escrito e falado no Brasil. 12x17cm 2144 Páginas', 78.9, 64.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rep8-m88hj9jio781a5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F22193912858', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
