INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19700296850', 'O Perfil do Líder Cristão do Século XXI | Henri J. M. Nouwen', 'O mundo atual caminha em uma velocidade assustadora. Mudanças cada vez mais constantes desafiam os cristãos de todo o mundo a permanecerem fiéis aos ensinos bíblicos e, ao mesmo tempo, buscar as respostas para os grandes questionamentos da sociedade. A solução está na sólida formação de líderes que conheçam verdadeiramente os ensinamentos de Deus e que saibam estender a mão aos que necessitam de ajuda. ”Se existe uma área onde o lider precisa dar atenção é a disciplina de habitar na presença de Deus, e nela meditando de dia e de noite, poderão conduzir os demais cristãos à maturidade. 64 Páginas 14x21cm', 25.9, 23.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/22cf45a7244cea7dc4ca14924a1ca49d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F19700296850', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19600466406', 'O Poder Expulsivo de Um Novo Afeto | Thomas Chalmers', 'Thomas Chalmers foi um ministro escocês que serviu durante a maior parte da sua vida na paróquia de São João, em Glasgow — a maior e mais pobre congregação da cidade. Conhecido pelo seu intenso trabalho de caridade no cuidado dos pobres e oprimidos, Chalmers foi também um teólogo perspicaz. Uma de suas obras mais notáveis é “O poder expulsivo de um novo afeto”, um poderoso escrito por meio do qual Chalmers inspira os cristãos a despojarem-se das armadilhas e emaranhados do pecado, não por meio de uma obediência legalista, mas pelo poder de um novo e maior afeto por Deus. O autor lembra aos santos de Deus que, como peregrinos que vivem neste mundo, o poder verdadeiro sobre as provações e pecados desta vida só é encontrado na afeição a Jesus Cristo, pois, afinal, como uma das consequências da Queda, os sentimentos humanos de amor são muitas vezes indevidamente depositados na criação, e não no Criador. Esta obra clássica da fé reorienta, pois, nossos afetos em direção a Deus. 13X21CM 54 Páginas', 27.9, 24.99, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/b3455460e3b0eb0815ef73cbc4300625', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F19600466406', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '11458476819', 'Os Outros da Bíblia - André Daniel', 'Este livro lança um olhar sobre a história bíblica, mas com um foco inovador: a partir dos povos antigos que interagiram com o Povo de Deus. Eles, os “outros” das narrativas bíblicas – mesopotâmicos, egípcios, cananeus, persas, gregos e romanos – são o tema central desta obra. Como eram as culturas e as crenças religiosas daqueles povos? Que influências elas podem ter operado sobre a fé do antigo Israel – e mesmo na doutrina da igreja cristã? Há ideias que podem ser consideradas biblicamente corretas na teologia dos pagãos? Como a política dos impérios antigos pode ter sido usada no plano divino para trazer Cristo ao mundo? Estas são algumas perguntas que estão respondidas neste livro. André Daniel Reinke realizou uma ampla pesquisa englobando temas como a geografia histórica, sistemas políticos, cultura geral e especialmente o pensamento religioso de cada um destes povos. A partir do entendimento do outro sobre o sagrado, o autor faz uma comparação com a revelação bíblica e com a prática dos antigos hebreus, respondendo então a pergunta central de sua pesquisa: Quais são as convergências, e quais as divergências, entre a fé pagã e a fé bíblica? Este livro é uma obra fundamental para que o leitor possa compreender melhor os contextos históricos, culturais e religiosos dos povos que tanto influenciaram na jornada do Povo de Deus e na própria construção da Bíblia Sagrada. 352 Páginas 16x23 cm', 41.9, 41.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/5774becfde4a20e54c25b93bf47bb9a4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F11458476819', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
