INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9935109438', 'Pastilha de Freio Traseira Cb 600f Hornet Sem Abs 2008 A 2014 Cobreq', 'Pastilha de Freio Traseira Cobreq Racing (semimetálica) Compatível com: HONDA CB 600 HORNET S/ ABS 2008 em diante Cbr 1000 Rr Fireblade 2006 A 2008 Cbr 1000 Rr Fireblade Com Abs 2009 A 2011 Cbr 1000 Rr Hannspree 2006 A 2008 Cbr 1000 Rr Sp 2014 A 2016 Cbr 1000 Rr Sp1 2017 A 2018 Cbr 1000 Rr Sp2 2017 A 2018 Cbr 600 Repsol 2007 A 2009 Cbr 600 Rr 2007 A 2009 Cbr 600 Rr Abs 2007 A 2009 Cbr 600 Rr Limited 2007 A 2009 Kawasaki Zx 1000 10R 2004 A 2004 Zx-10R Winter 2016 A 2018 Zx-10Rr Ninja 998 2017 A 2018 Zx-6 R 636 Ninja 2013 A 2015 Suzuki Gsx 1000 S F 2015 A 2017 Gsx-R 1000 2009 A 2011 Gsx-R 1000 2012 A 2014 Gsx-R 1000 Com Abs 2015 A 2017 Gsx-R 600 2011 A 2013 Gsx-R 750 2011 A 2013 Gsx-S 1000 Com Abs 2015 A 2017 Gsx-S 1000 F Com Abs 2015 A 2017 Yamaha Yzf 1000 R1 2015 A 2017 Yzf 1000 R1 60Th Anniversary 2016 A 2018 Yzf 1000 R1 M 2015 A 2017 Para aplicações de alta performance a Linha Racing da Cobreq é a escolha ideal, essa aplicação foi especialmente projetada para motocicletas a partir de 500 CC, que exigem um melhor poder de frenagem devido as altas temperaturas, com menor desgaste das pastilhas e dos discos de freios, em sua composição são utilizados materiais de fibra de aramidas e kévelar e testados em ambientes extremos de competições como Moto GP, Superbike, Stock Car e F-Truck, assegurando a qualidade e confiabilidade da marca Especificações Técnicas: - Linha Racing; - Qualidade superior comprovada- Pastilha Semi-metálica- Não contém Amianto- Alta durabilidade e performance- Rápida resposta de frenagem e baixo nível de ruído - Fabricado dentro do mais alto padrão de qualidade e segurança- Performance superior- Pastilha de alta duração- Maior segurança ao motociclista - Possui medidas originais- Melhor dissipação de calor e atrito com o disco de freio Importante Recomendamos que a instalação seja feita por profissional especializado e não nos responsabilizamos pelo mau uso do produto. Verifique, antes da compra, se as medidas das pastilhas são compatíveis com a da sua moto.', 159.9, 143.91, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Chassis', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mbo5vzscao4nc8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316500472%2F9935109438', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41314564361', 'Kit Pastilhas e Lonas de Freio Biz 125 Ex 2025-2026 Diafrag', 'Kit Pastilhas e Lonas de Freio Diafrag As pastilhas de freio Dia-Frag Urban Tech oferecem vários benefícios, incluindo ótima capacidade de frenagem em diferentes condições de pista, excelente custo-benefício e progressividade do freio, além de não apresentar "fade" (perda de frenagem) ou ruídos. Compatível com HONDA: BIZ 125 2025 BIZ 125 2026 Conteúdo da Embalagem: 01 Par de Pastilhas de Freio Dianteira Diafrag Urban Tech (Orgânica) 01 Par Lonas de Freio Traseira Diafrag (standard) Especificações Pastilhas: - Modelo:Urban Tech (Orgânica) - Material: ferro / lona - Produzido com melhores equipamentos garantindo segurança e durabilidade. - Oferecendo o melhor custo beneficio, unindo qualidade e eficiência na sua utilidade. - Possui medidas originais - Melhor dissipação de calor e atrito com o disco de freio - Ideal Para Reposição - Maior segurança ao motociclista - Alta Qualidade E Resistência Especificações Lonas: - Chapa traseira de cobre revestido; - Não acompanha Molas;- Maior ligação mecânica entre os materiais de atrito; - Redução de corrosão (Menos ferrugem); - Desgaste do cubo de 20% menos; - Sapatas De Freio Em Alumínio Injetado Sem Emenda - Com Baixos Percentuais De Metais Ferrosos - Acabamento Superficial Antioxidante - Aplicação Dianteira E Traseira - Sapata De Freio Com Medidas Originais - Reduz O Nível De Ruídos E Oferece Frenagens Seguras- Ideal Para Reposição - Alta Qualidade E Resistência Principais benefícios: Excelente resposta de frenagem: As pastilhas oferecem ótima capacidade de frenagem tanto em pistas secas quanto molhadas, proporcionando segurança ao condutor. Ótimo custo-benefício: A relação qualidade e preço das pastilhas Dia-Frag Urban Tech é considerada alta, tornando-as uma opção econômica e eficiente. Progressividade do freio: As pastilhas garantem uma frenagem gradual e suave, evitando travagens bruscas e aumentando a segurança. Ausência de "fade" e ruídos: As pastilhas não apresentam perda de capacidade de frenagem em altas temperaturas ("fade") e não emitem ruídos durante a frenagem. Baixo desgaste do disco de freio: As pastilhas são projetadas para minimizar o desgaste do disco de freio, prolongando a vida útil do sistema de freio. Alto conforto na frenagem: A frenagem com as pastilhas Dia-Frag Urban Tech é suave e confortável, proporcionando uma experiência mais agradável ao condutor. Importante !! - Verifique, antes da compra, se as medidas das pastilhas são compatíveis com a da sua moto. - Recomendamos que a instalação seja feita por profissional especializado e não nos responsabilizamos pelo mau uso do produto.', 79.9, 71.91, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Chassis', 'https://cf.shopee.com.br/file/sg-11134201-7rdxz-mdqdzmh6lffu9b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316500472%2F41314564361', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
