INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22193915032', 'PlayDoh Massa de Modelar Mini Kit Corte Maluco - Hasbro', 'PlayDoh Massa de Modelar Mini Kit Corte Maluco - HasbroA Massa de Modelar PlayDoh Mini Kit Corte Maluco proporciona momentos de diversão e aprendizado para os pequenos. Com este conjunto, as crianças podem soltar a imaginação e criar penteados malucos repetidamente. O brinquedo inclui acessórios de plástico, como um barbeador e uma tesoura de brincar, além de dois potes de massinha colorida atóxica Play-Doh. Diferenciais do Produto:Criação de penteados divertidos com massinha de modelar. Estimula a criatividade e a coordenação motora. Fácil de transportar e armazenar. Acessórios seguros e divertidos para as crianças. Mais sobre o Produto:Perfeito para crianças a partir de 3 anos. Ideal para brincadeiras educativas e criativas. Estimula a imaginação e o desenvolvimento infantil. Proporciona horas de diversão e entretenimento. Dicas de Uso:Permita que as crianças soltem a imaginação criando diferentes penteados com a massinha Play-Doh. Explore a combinação de cores para tornar as criações ainda mais coloridas e divertidas. Utilize os acessórios inclusos para trazer mais realismo e diversão durante a brincadeira. Após a diversão, armazene a massinha e os acessórios na embalagem para facilitar o transporte e organização. Ficha Técnica:Marca: Hasbro; Nome do produto: PlayDoh Massa de Modelar Mini Kit Corte Maluco; Idade recomendada: A partir de 3 anos; Selo Inmetro: 002799/2021; Contém: 1 kit corte maluco, acessórios e 2 potes de massinha.', 57.49, 57.49, NULL, 'Mom & Baby > Toys > Pretend Play', 'https://cf.shopee.com.br/file/sg-11134201-7req6-m8c2xn2rs8827f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F952529254%2F22193915032', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
