INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '6395468894', '365 Atividades Para Meninas', 'Nestas paginas você encontrara 365 atividades e desafios. Este livro e perfeito para você que gosta de colorir, adivinhar, desvendar labirintos, ligar os pontos, somar e subtrair e muito mais. mergulhe nesta aventura e descubra que aprender pode ser muito divertido.', 24.9, 24.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7rdws-m18ldun43p1zd2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F303956123%2F6395468894', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43418283050', 'Sandália Rasteira Feminina Tiras Chinelo de Dedo com Enfeite Metalizado Moda Confortável GiGiL', 'CALÇA O NÚMERO EXATO, Indicamos pedir o tamanho padrão de uso. MATERIAL: Napa Sintética SOLADO: Microexpandido Emborrachado – leve e flexível. ALTURA DA SOLA: Rasteira FORMA: Bico Quadrado DETALHE: Tiras estilo Chinelo e Enfeite ABS Metalizado no cabedal. PALMILHA: Confortável, macia em micro expandido emborrachado. - PROTEÇÃO DO ENVIO: Caixa individual - Embalada com Envelope Plástico Resistente. - FOTO: real do nosso produto. A Rasteirinha London da GiGiL é a escolha perfeita para quem busca praticidade sem abrir mão do estilo. Confeccionada em napa sintética, traz tiras que dividem os dedos e aplicação de enfeite arredondado metalizado em dourado no centro, detalhe que garante um toque sofisticado ao modelo. Com bico quadrado, palmilha lisa e solado leve, a London proporciona conforto ao caminhar e se adapta facilmente a diferentes produções. Aberta e arejada, exibe todo o pé e é ideal para os dias mais quentes. Perfeita para compor looks modernos e descontraídos, do trabalho ao passeio, ela traz leveza e versatilidade para o seu dia a dia. CONSERVAÇÃO: * Para conservar o seu modelo novo e bonito por muito mais tempo é fundamental seguir algumas recomendações: - A limpeza deve ser feita com sabão neutro e pano úmido e não deve ficar de molho. Não usar nenhuma fonte de calor para secar. Guardar em local sem umidade e deixar descansar na sombra por 12 horas após o uso. - Não utilize Máquina de lavar e secar. - Independente do material do seu sapato, não esfregue com força ou passe esponjas grossas. - Caso alguma dessas indicações não forem cumpridas, isso poderá danificar os materiais, a cor e a textura do seu calçado. GiGiL - SEU ESTILO COM UM CLIQUE! Somos uma marca de moda, criativa e antenada. Nosso foco é criar calçados com qualidade e preço justo.', 69.99, 59.99, NULL, 'Women Shoes > Flat Sandals & Flip Flops > Flat Sandals', 'https://cf.shopee.com.br/file/br-11134207-81z1k-meftjdu8bitc0a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F387348115%2F43418283050', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
