INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22098688219', 'Climatizador 80 Litros Ventisol Preto CLIN80PRO-02 220V 150W', 'Transforme o seu ambiente com o Climatizador Ventisol CLIN80PRO-02, um aparelho inovador que une eficiência e tecnologia para proporcionar a você e sua família um espaço mais fresco e saudável. Com design moderno, este climatizador é ideal para quem busca conforto e bem-estar. Conheça os atributos que fazem do Climatizador Ventisol a escolha perfeita para sua casa: Filtro Tipo Colmeia: Proporciona uma filtragem eficiente, garantindo ar limpo e saudável. Econômico: Consome apenas 150W, oferecendo uma solução de climatização que não pesa no bolso. Reservatório de 80L: Grande capacidade que permite longas horas de funcionamento sem necessidade de reabastecimento. Compartimento de Gelo: Aumenta ainda mais a eficiência do climatizador, proporcionando um ar mais gelado e refrescante. 5 em 1: Ventila, climatiza, umidifica, filtra e circula o ar, garantindo um ambiente mais saudável e aconchegante. Proteção para Bomba: Aumenta a durabilidade do aparelho, garantindo um funcionamento seguro e prolongado. Especificações Técnicas CLIN80PRO-02: Voltagem: 220V Capacidade: 80 Litros Cor: Preto Peso Bruto: 13,500 Kg Dimensões (CxLxA): 512x365x1170 mm Itens Inclusos: 1 Climatizador e 1 Kit de Manuais.', 1061.0, 1061.0, NULL, 'Home Appliances > Large Household Appliances > Cooling', 'https://cf.shopee.com.br/file/sg-11134201-7ra10-mbfpcrwykbiu2b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1207374375%2F22098688219', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
