INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20498429060', 'Camisa Barcelona Retrô Classic Masculina Oficial', 'Inspirada nos grandes esquadrões que marcaram época, a Camisa Barcelona Retrô Classic resgata a essência do futebol raiz em uma peça atemporal. Confeccionada em algodão fio tinto premium com acabamento toque pele de pêssego, oferece conforto superior, caimento impecável e visual autêntico para quem valoriza história e estilo. As tradicionais listras grená e azul ganham destaque ao lado do escudo bordado em alto relevo, reforçando a identidade clássica do modelo. Uma peça versátil para compor produções casuais com jeans, sarja ou bermudas, levando a paixão pelo futebol para além dos estádios. Características: Composição: 100% Algodão Tecido fio tinto premium Toque macio tipo pele de pêssego Escudo bordado Modelagem confortável Produto à pronta entrega Por que você vai gostar? Visual retrô autêntico Conforto para o dia a dia Acabamento premium Peça versátil para diversas ocasiões Estilo casual com inspiração futebolística Com que roupa usar: Jeans azul ou preto Calça sarja bege, creme ou preta Bermuda de sarja Tênis casuais e retrô Medidas Aproximadas (Largura x Altura) P (BR): 48 x 67 cm M (BR): 50 x 69 cm G (BR): 52 x 71 cm GG (BR): 54 x 73 cm EGG (BR): 60 x 76 cm Estoque limitado. Garanta a sua e vista a história.', 329.9, 296.91, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > T-shirts', 'https://cf.shopee.com.br/file/br-11134207-820lm-mpmh8y1c7zlvbc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F698219490%2F20498429060', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
