INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43008202782', 'Sandália Rasteira Beira Rio Strass Chinelo Slide Feminino Tiras', 'A Papete Feminina Beira Rio é a escolha perfeita para quem busca unir estilo, conforto e praticidade no dia a dia. Com um design moderno e detalhes delicados, ela se destaca pelas pérolas aplicadas no cabedal, que trazem um toque de elegância e feminilidade ao visual, sendo ideal para compor desde produções casuais até looks mais sofisticados. Confeccionada com materiais de alta qualidade, possui palmilha macia em EVA, que oferece excelente absorção de impacto, garantindo conforto prolongado e leveza em cada passo. O cabedal em material sintético é resistente, e super fácil de limpar. Seu solado antiderrapante proporciona segurança e estabilidade em diferentes tipos de superfícies. Além do design prático no estilo slide, que facilita o calce, essa papete conta com uma estrutura anatômica que se adapta aos pés. Ideal para quem busca um calçado versátil, confortável e com um visual sofisticado para acompanhar nas tarefas do dia a dia, passeios ou momentos de lazer. Composição do Calçado: Marca: Beira rio Material: Sintético Palmilha: EVA Solado: Borracha Guia Tamanhos: Nº 33 – 22,0 CM Nº 34 – 22,5 CM Nº 35 – 23,0 CM Nº 36 – 24,0 CM Nº 37 – 24,5 CM Nº 38 – 25,0 CM Nº 39 – 26,0 CM Nº 40 – 26,5 CM Nº 41 – 27,0 CM Nº 42 – 27,5 CM', 149.9, 81.99, NULL, 'Women Shoes > Flat Sandals & Flip Flops > Flat Sandals', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mc2ejax0n6pxa5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F287287585%2F43008202782', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
