INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21897421022', 'Óleo Corporal Nupill Amêndoa e Coconut 100ml', 'O Óleo de coco e macadâmia Nupill é um óleo de hidratação corporal mais nobre, com propriedades de alta hidratação porém com textura mais leve na aplicação. Combina a hidratação do coco e da macadâmia sem deixar a pele saturada e proporciona toque aveludado. A Nupill desenvolveu uma série de óleos corporais que têm toque macio e aveludado e são formulados com óleo de amêndoa e enriquecidos com ativos que vão além da hidratação e proteção da pele. Esse é um deles. Conheça os outros óleos corporais da Nupill: Amêndoa + Vitamina E Amêndoa + Colágeno Amêndoa + Semente de uva com colágeno Amêndoa + Avelã com Vitamina E Óleo de coco – hidratação intensa para peles ressecadas, propriedades anti microbianas e anti-inflamatórias. Enriquecido com óleo de macadâmia com alto poder de hidratação e antioxidante, eficaz contra o envelhecimento precoce das células da pele. Não mancha toalha de banho ou roupa. Modo de Uso: Aplique o óleo de coco e macadâmia Nupill na pele espalhando o por toda a área a ser hidratada durante o banho ou a seco, como preferir.', 21.02, 21.02, NULL, 'Beauty > Bath & Body Care > Body Oil', 'https://cf.shopee.com.br/file/sg-11134201-7rblb-lmhhjjdbdsuj70', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F21897421022', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
