INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209715571', 'Feijão Preto Camil', 'O Feijão Preto Camil é um alimento muito nutritivo, rico em proteínas e fibras, perfeito para o dia a dia. Fonte de ferro e antioxidantes, auxilia no bom funcionamento do organismo e contribui para uma dieta equilibrada. Ideal para preparar acompanhamentos, saladas, sopas e a tradicional feijoada brasileira. * Sem Glúten * Pode conter soja', 8.49, 8.49, NULL, 'Food & Beverages > Food Staples > Dried Goods', 'https://cf.shopee.com.br/file/sg-11134201-825bc-mqnel3zy12bkbd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555128%2F58209715571', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
