INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23598424627', 'Andador Bebê Tutti Baby Princesa Rosa com Centro Atividades', 'Centro de atividades infantil Rosa - Andador Princesa Tutti Baby Andador para Bebê Princesa – Os Primeiros Passos de um Conto Encantado. Uma pequena princesa prestes a viver uma das aventuras mais mágicas da infância: os seus primeiros passinhos. O Andador de Atividades Princesa foi criado especialmente para transformar esse momento em um verdadeiro conto de fadas, cheio de cor, imaginação e alegria. Com adesivos encantadores e uma bandeja de brinquedos que estimula a curiosidade, o Andador Princesa é o companheiro ideal para essa fase tão especial. Além da beleza, ele oferece toda a segurança e conforto que uma verdadeira realeza merece. Características encantadoras do Andador infantil Princesa: Indicado para crianças a partir de 6 meses e até 12kg Assento acolchoado para conforto digno de princesa Bandeja de brinquedos interativa com adesivos personalizados de tema princesa Trava de segurança automática 3 níveis de altura ajustáveis Freios antiqueda para máxima proteção 4 rodízios, sendo os traseiros fixos para maior estabilidade Segurança de verdadeiras majestades: A bandeja de brinquedos do Andador Princesa é certificada conforme a norma NBR NM 300, oferecendo tranquilidade para os pais e muita diversão para as pequenas. Certificações: Andador: IQB (0006) | Registro: 1472/2022 Brinquedos: SGS (0040) | Registro: 006760/2018 Para as pequenas sonhadoras que estão dando seus primeiros passos rumo ao seu próprio reino. Andador Princesa – Porque toda princesa merece um começo encantado.', 258.7, 224.9, NULL, 'Mom & Baby > Toys > Baby & Toddler Toys', 'https://cf.shopee.com.br/file/sg-11134201-7renx-m8z3owevdep3ab', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F14796227