INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '51809318991', 'Siàge Condicionador Hidratação Micelar 200ml', 'Condicionador Eudora Siàge Hidratação Micelar desembaraça imediatamente os fios, proporcionando madeixas macias e soltas por mais tempo. Sua fórmula sela as cutículas capilares, retendo a umidade natural dos cabelos, mantendo a hidratação e permitindo um balanço incrível. O produto reequilibra a estrutura do fio, devolvendo brilho e maciez. Além disso, ele protege dos agressores diários sem pesar, deixando os fios incrivelmente sedosos.', 62.79, 50.21, NULL, 'Beauty > Hair Care > Hair and Scalp Conditioner', 'https://cf.shopee.com.br/file/sg-11134201-820l5-mnd6rg0kge8163', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F51809318991', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '56700321469', 'Absorvente Noturno com Abas Libresse Pure Sensitive Ultrafino 28 unidades', 'Libresse é uma marca com uma linha completa de produtos para o ciclo menstrual. Acreditamos que o ciclo menstrual é único. Vamos surpreender e transformar a relação com a sua menstruação, oferecendo um lugar seguro sem vazamentos e desconfortos. Independente do fluxo, são opções de acordo com a necessidade de cada pessoa que menstrua, afinal seu corpo suas regras. Ofereça delicadeza à sua pele e conforto com a absorção. Nossa linha Pure Sensitive auxilia a prevenir possíveis irritações – 0% alergênicos, fragrâncias e corantes. Uma excelente opção para ter um conforto invisível graças ao seu formato anatômico. Te dão total liberdade e proteção para viver sem preocupações. Com canais para garantir máxima absorção do fluxo menstrual do interior do canal vaginal, distribuição e evitar vazamentos. São macios, extrassuaves e para inserção fácil sem nenhum desconforto adaptando-se ao corpo através de seu aplicador. Ginecologicamente e dermatologicamente testado, livre de cloro e ftalatos. Não testado em animais. Embalagem em braille com dizeres para rápida identificação.', 33.29, 33.29, NULL, 'Health > Personal Care > Feminine Care', 'https://cf.shopee.com.br/file/sg-11134201-825ba-mge3lkxkgjrh52', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F56700321469', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44073240796', 'Kit Protetor Solar Sundown FPS 50 200ml + Protetor Solar 100ml', 'Com tripla proteção, ajuda a proteger a pele de elementos agressores como o sol, cloro e a água salgada do mar. Oferece proteção imediata UVA + UVB, protegendo a pele de queimaduras solares dentro e fora d’água. É 3x mais resistente à água e ao suor* e seguro para uso em toda família.', 98.59, 98.59, NULL, 'Beauty > Bath & Body Care > Sun Care', 'https://cf.shopee.com.br/file/sg-11134201-824i3-mfl8easyq2a0f4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F44073240796', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18435439180', 'Kit Desinfetante Pinho Sol Limão 500mL com 5 unidades', 'Kit Desinfetante Pinho Sol Limão 500mL com 5 unidades Pinho Sol® é um desinfetante de uso geral de alta qualidade: Elimina 99,9% das bactérias, germes e fungos Limpa, desinfeta e perfuma o ambiente Excelente rendimento: 500ml (rende 25 litros)', 61.59, 61.59, NULL, 'Home & Living > Home Care Supplies > Cleaning Agents', 'https://cf.shopee.com.br/file/366cc7d022c8a5937c31965857e65510', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F18435439180', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23393929040', 'Pasta de Amendoim 600g - Dr Peanut', 'Para quem busca um estilo de vida saudável ou admiradores de produtos gourmet, a Pasta de Amendoim é rica em proteínas, gorduras boas e fibras, além de ser zero açúcar e composta por ingredientes selecionados. Uma escolha perfeita para quem quer enriquecer suas refeições e lanches de forma prática e saborosa. Destaques do Produto: Fonte de proteínas e energia para seu dia a dia; Sem adição de açúcares e sem glúten; Textura cremosa e sabor marcante de pistache; Ingredientes premium, garantindo máxima qualidade. Utilize em sobremesas, panquecas, shakes ou deguste diretamente do pote para momentos de puro prazer! Dê mais sabor para sua rotina com a Pasta de Amendoim da Dr. Peanut. Experimente e surpreenda-se!', 71.9, 52.9, NULL, 'Health > Food Supplement > Fitness', 'https://cf.shopee.com.br/file/br-11134207-820li-mqj6c9354qgx79', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F242277934%2F23393929040', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22528103213', 'Ração Biofresh Para Gatos Castrados Frango - 1,5Kg', 'Ração Biofresh Para Gatos Castrados Frango - 1,5Kg - Indicado para gatos; - Livre da adição de transgênicos, contém conservantes naturais; - Ajuda a manter o trato urinário saudável; - Alimento completo e equilibrado. A Ração Biofresh Para Gatos Castrados Frango ? 1,5Kg é inovador e diferente porque possui alta inclusão de carnes frescas com um toque de vegetais e frutas nobres. O resultado é um alimento grain free, completo e equilibrado que se destaca por elevar a nutrição de carnívoros ao seu mais alto nível. A tecnologia Biofresh garante a preservação deste alimento de forma segura e 100% natural, sem adição de conservantes artificiais. Os alimentos têm sua preservação 100% segura e natural, garantida por meio dos antioxidantes naturais e atmosfera modificada, além de adição de fibras e minerais de alta qualidade. Recomendação de uso As quantidades aqui apresentadas são orientativas, podendo variar de acordo com raça, sexo e estilo de vida, entre outros fatores. Sirva o alimento seco, em recipiente limpo, dividido em várias refeições diárias e mantenha sempre água limpa e fresca ao alcance de seu gato. Em caso de dúvida, consulte um médico veterinário. Peso do gato (kg) Quantidade diária (g/dia) Peso ideal 2 - 2,5Kg 30 - 35g 3 - 3,5Kg 40 - 45g 4 - 4,5Kg 50 - 53g 5 - 5,5Kg 56 - 60g 6 - 6,5Kg 65g 7 - 7,5Kg 70g 8+ 75g (+5g a cada Kg) *Faltando composição*', 188.8, 169.92, NULL, 'Pets > Pet Food > Cat Food', 'https://cf.shopee.com.br/file/sg-11134201-23020-t4knw5i703nv22', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F645931940%2F22528103213', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23892560342', 'Carregador Portátil 1 Hora Power Bank 10000mAh Preto', 'Carregador Portátil 1 Hora Power Bank 10000mAh Preto Carregamento Ultra-Rápido Design Compacto e Elegante Ideal para Viagens e Uso Diário Alta Capacidade 1. Carregamento Ultra-Rápido: Este Power Bank permite carregar dispositivos em apenas 1 hora, oferecendo uma solução rápida e eficiente para manter seus aparelhos sempre prontos para uso. 2. Capacidade de 10000mAh: Com uma capacidade de 10000mAh, este carregador portátil é perfeito para recarregar smartphones, tablets e outros dispositivos, fornecendo energia suficiente para o dia todo em uma única carga. 3. Design Moderno e Portátil: Apresentando um design elegante na cor preta e formato compacto, este Power Bank é fácil de levar em qualquer bolsa ou bolso, tornando-o ideal para viagens ou uso diário. 4. Versatilidade para Diversas Situações: Seja para viagens, trabalho ou atividades ao ar livre, este carregador portátil é uma ferramenta essencial para garantir que seus dispositivos permaneçam carregados em qualquer lugar. 5. Segurança e Confiabilidade: Equipado com tecnologia avançada, protege seus dispositivos contra sobrecargas e curtos-circuitos, garantindo uma carga segura a cada uso. garantia de 90 dias', 98.23, 98.23, NULL, 'Mobile & Gadgets > Accessories > Powerbanks & Batteries', 'https://cf.shopee.com.br/file/br-11134201-7r98o-ls7d76xc8pow0c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1163157664%2F23892560342', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22998193932', 'Fita PVC sem Adesivo Hulter 100X10m Preta HT110PA', 'Fita PVC Sem Adesivo Preta Hulter 100X10m A Fita PVC Sem Adesivo Preta Hulter 100X10m é uma excelente opção para proteção e isolamento de componentes, oferecendo resistência e durabilidade em várias aplicações. Com um formato compacto e flexível, essa fita de 100 mm de largura e 10 metros de comprimento é fácil de manusear e aplicar, proporcionando um acabamento eficiente e seguro em tubulações, sistemas elétricos, hidráulicos e outros elementos industriais e residenciais. Sua composição em PVC de alta qualidade garante resistência ao desgaste, umidade e variações de temperatura, assegurando proteção confiável por longos períodos. Ideal para aqueles que buscam uma solução prática e versátil, a Fita PVC Hulter pode ser aplicada em diferentes contextos, auxiliando na organização de fios, no isolamento de tubos e na preservação de estruturas contra possíveis danos externos. Sua cor preta torna a fita discreta e elegante, adequada para locais que exigem uma aparência mais profissional e acabamentos visivelmente refinados. Além disso, a flexibilidade do material permite que ele se ajuste a diversas superfícies e contornos, facilitando o uso em espaços de difícil acesso. O produto também se destaca pela segurança, pois o PVC utilizado na fabricação oferece resistência a eletricidade e calor, sendo uma alternativa eficaz para a proteção de sistemas elétricos. Com sua qualidade e eficiência, a Fita PVC Hulter é uma solução econômica e funcional para quem busca praticidade e proteção em suas instalações. Se você precisa de uma fita confiável e fácil de aplicar, a HT110PA é a escolha certa, ajudando a manter suas instalações organizadas e seguras sem complicações.', 15.9, 15.9, NULL, 'Home & Living > Tools & Home Improvement > Industrial Adhesives & Tapes', 'https://cf.shopee.com.br/file/sg-11134201-7rdxj-mdbruy58fnswfc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1398462025%2F22998193932', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19398989187', 'VINHO JP. CHENET CABERNET SAUVIGNON-SYRAH TINTO 750ML', 'Você está comprando: VINHO JP. CHENET CABERNET SAUVIGNON-SYRAH TINTO 750MLPaís de origem: FrançaValidade: IndeterminadaSOBRE O PRODUTO Elaborado com a união de duas grandes castas, cultivadas em um terroir excepcional, nasce um vinho moderno, equilibrado e sedoso. De coloração rubi, aroma de frutas maduras e notas de café. Em 1984 a Les Grand Chais de France concebeu uma garrafa de gargalo curvo, chamada de “Josephine”. A nova marca foi chamada de JP. CHENET e o sonho de compartilhar com o mundo um vinho francês de qualidade, fácil de escolher e identificar começou a tornar se realidade. Assim, contra o fluxo de uma oferta complexa de vinhos franceses, nasceu a 1ª marca varietal francesa. Essa é a marca de vinho francês mais vendida no mundo, tendo uma distribuição em mais de 160 países. Em 1991 a JP. Chenet ganhou o Prêmio Verre Avenir, o oscar de embalagem, pela sua garrafa característica. Em 2013 a marca lança sua linha de Espumantes Ice, revolucionando o mercado de espumantes com essa nova bebida. HARMONIZE COM Carnes vermelhas, Massas, Pizza, Queijos CaracterísticasCOMPOSIÇÃO UVA: Syrah GRADUAÇÃO ALCÓOLICA: 13%AMADURECIMENTO: Sem estágio em carvalho, o vinho estagia em tanques de aço inoxidável entre 3 e 6 meses, permanecendo em contato com as borras.SABOR: leve e frutado, repleto de notas de frutas vermelhas maduras. AROMA: aroma de frutas maduras e notas de café', 162.06, 162.06, NULL, 'Food & Beverages > Alcoholic Beverages > Wine & Champagne', 'https://cf.shopee.com.br/file/sg-11134201-7rbm6-lmem8zj2r8ex26', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F844012318%2F19398989187', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18797415691', 'VINAGRE BALSAMICO DE MODENA LA PASTINA 500ML', 'Você está comprando: VINAGRE DE VINHO BRANCO PAGANINI 500ML Origem: ITÁLIA SOBRE O PRODUTO Aceto envelhecido em barris de carvalho e castanhas, o que resulta em um produto de aroma e paladar agridoce. Produzido em Modena – Itália, possui selo de Indicação Geográfica Protegida (IGP), que atestam a origem e qualidade do produto. De sabor frutado, é perfeito para acrescentar um toque de sofisticação em grelhados, queijos e saladas. LA PASTINA, ALIMENTAMOS SUA PAIXÃO Uma seleção de produtos premium unindo qualidade, praticidade e confiabilidade. É reconhecida pelos mais renomados chefs e apreciadores da alta gastronomia. Pioneira em diversas categorias, a La Pastina vive em constante busca por produtos diferenciados, saudáveis e saborosos, oferecendo ao consumidor sofisticação e facilitando a vida daqueles que buscam trazer ao seu dia a dia uma incrível experiência gourmet à mesa. Acreditamos no poder transformador do alimento e nossa filosofia está baseada na cultura da enogastronomia Mediterrânea. Trazer mais sabor à vida das pessoas é a nossa verdadeira paixão.', 65.43, 65.43, NULL, 'Food & Beverages > Cooking Essentials > Seasonings & Condiments', 'https://cf.shopee.com.br/file/sg-11134201-7rblp-lm8u0tjp38m171', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F844012318%2F18797415691', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58205958475', 'Kit Acidificante Matizador Completo Haskell (3 Itens) | Neutraliza Amarelado e Recupera Brilho dos Loiros', 'O Kit Completo Acidificante Matizador da Haskell é a rotina ideal para neutralizar o amarelado, recuperar o brilho e reduzir a porosidade de cabelos loiros, descoloridos ou grisalhos. Com ação acidificante que equilibra o pH capilar, a linha promove selagem das cutículas e melhora o alinhamento da fibra. A combinação da tecnologia Activeshine com o extrato de flor de lótus proporciona brilho tridimensional, preservação da cor e fios mais macios desde a primeira aplicação. Perfeito para quem busca matização uniforme com tratamento profundo e resultado saudável. Benefícios • Neutraliza o tom amarelado indesejado • Equilibra o pH e sela as cutículas • Reduz a porosidade e melhora a retenção de pigmentos • Devolve brilho intenso e luminosidade • Diminui o frizz e melhora a penteabilidade • Matização eficaz sem ressecar os fios O kit contém • 01 Shampoo Acidificante Matizador 300 ml • 01 Supermáscara Acidificante Matizadora 240 g • 01 Balm Cicatrizante Acidificante Matizador 100 ml Tecnologia e Ativos • Activeshine — tecnologia que potencializa o brilho e a uniformidade da cor • Extrato de Flor de Lótus — ação antioxidante e hidratante para fios macios e luminosos Indicação: cabelos loiros, descoloridos ou grisalhos Fragrância: floral Modo de uso: Aplique o Shampoo Acidificante Matizador nos cabelos molhados, massageie suavemente e enxágue. Aplique a Supermáscara no comprimento e pontas, deixe agir conforme o nível de matização desejado e enxágue. Finalize com o Balm Cicatrizante nos fios úmidos. Não enxágue e finalize como desejar.', 233.7, 233.7, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/sg-11134201-8261b-ml7vpn9q8qv970', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1562135680%2F58205958475', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23993149977', 'GRAXA UNIGRAX CA-2 1KG - UNI', 'UNIGRAX CA é uma graxa à base de cálcio, hidrorepelente, fabricada com óleo lubrificante de alta viscosidade, tendo uma cor castanho escura e grande adesividade. Recomendada para lubrificação das articulações de chassis de caminhões, automóveis, tratores, motocicletas, máquinas agrícolas, mancais de deslizamento e sempre que necessite de uma graxa para trabalhos em temperaturas não superiores a 70ºC. É também utilizada em indústrias pesadas, tais como mineração, laminação de aço e metais não ferrosos, manufatura de produtos químicos e usinagem de metais. ATENDE AS CLASSIFICAÇÕES: ASTM 4950: LA DIN 51825: OG1D-20 (NLGI 1) / OG2D-20 (NLGI 2)', 42.43, 41.16, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Additive and Lubricant', 'https://cf.shopee.com.br/file/sg-11134201-7rdvt-ly0wp8ymue1re3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F272868574%2F23993149977', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9757132808', 'Caixa Medicamento Frasqueira Media Nitron', 'A Nitron atua no mercado de utilidades domésticas em plásticos há 35 anos. Com mais de 300 itens em linha, hoje a Nitron é uma das principais fabricantes de utilidades domésticas em plástico do Brasil, resultado de uma atuação voltada principalmente na qualidade de seus produtos, investimentos constantes e modernização profissional, respeitando as principais necessidades e desejos de seus consumidores. DESCRIÇÃO DO PRODUTO: Frasqueira Maleta para Medicamentos Grande ideal para guardar medicamentos, remédios, band-aids, possui tampa de proteção transparente que ajuda a preservar a organização os medicamentos, possui Lacre e alça. BPA Free (Livre de BPA - O BPA é uma substância química que faz mal à saúde) Design alegre que se adequa em todos os momentos Material incrivelmente resistente CARACTERÍSTICA DO PRODUTO: Compisição : Polipropileno Marca: Nitron DIMENSÕES DO PRODUTO: Peso: 190 g Largura: 16,3 cm Comprimento: 24,2 cm Altura: 12,8 cm Capacidade: 2,8 Litros', 30.9, 30.9, NULL, 'Home & Living > Home Organizers > Storage Boxes, Bags & Baskets', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lnwyiqz022fg15', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F312703265%2F9757132808', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22497385481', 'Manípulo Fêmea 5/16 UNC 18 FPP Modelo 4526 Preto Polipropileno', 'O Manípulo Fêmea Modelo 4526 é ideal para aplicações que exigem regulagem manual prática e fixação segura de partes móveis em máquinas e equipamentos. Fabricado em polipropileno de alta resistência, proporciona durabilidade, leveza e excelente desempenho em ambientes industriais e comerciais. Sua rosca interna padrão 5/16” UNC 18 FPP garante encaixe preciso e firme, oferecendo segurança na fixação. BENEFÍCIOS PRINCIPAIS Regulagem prática e segura Permite ajustes manuais rápidos sem necessidade de ferramentas. Alta resistência Fabricado em polipropileno resistente a impactos e desgaste. Fixação eficiente Rosca interna padrão UNC garante encaixe firme e preciso. Versátil Ideal para máquinas, equipamentos e dispositivos que necessitam ajustes frequentes. APLICAÇÕES • Máquinas industriais • Equipamentos mecânicos • Dispositivos com regulagem manual • Fixação de partes móveis ESPECIFICAÇÕES TÉCNICAS Modelo: 4526 Fêmea Material: Polipropileno Cor: Preta Rosca interna: 5/16” – 18 FPP UNC Tipo: Manípulo com rosca interna ITENS INCLUSOS 01 Manípulo Fêmea 5/16 UNC 18 FPP – Modelo 4526 Produto vendido por unidade. FAQ Qual o tipo de rosca? Rosca interna 5/16” padrão UNC 18 FPP. Precisa de ferramenta para ajuste? Não. O manípulo é projetado para regulagem manual. É resistente? Sim. Produzido em polipropileno de alta resistência, ideal para uso contínuo.', 8.64, 8.39, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-81ztm-mkmhig5sc83n5b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F272868574%2F22497385481', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
