INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19097655719', 'Cabo USB-C + USB-C i2GO 2m 3a Nylon Trançado Chumbo', 'O Cabo USB-C + USB-C i2GO PRO, possui dois conectores do Tipo-C e é ideal para Tecnologias de Carregamento Rápido. Você pode plugá-lo sem se preocupar com a orientação do conector. É Compatível com todos os dispositivos que utilizem portas USB-C. Suporta carregamento rápido Power Delivery de até 60W e carregamento de MacBooks com entrada USB-C Mais potente, rápido e prático: Garante maior transferência de energia (3 Amperes) e possui grande velocidade para transferências de dados (480 Mbps) Sincroniza músicas, fotos, vídeos e dados enquanto carrega Acabamento em alumínio e conector reversível Resistor pull-up integrado de 56k 0hm garante uma conexão e carregamento seguro entre quaisquer dispositivos com USB-C Quando o assunto é resistência e durabilidade, o Cabo USB-C + USB-C i2GO PRO se destaca através de sua blindagem em folha de alumínio e malha de cobre protetora, tendo sido desenhado e testado para suportar mais de 30.000 dobras sem danificar o seu funcionamento. Itens Inclusos: 1 Cabo USB-C + USB-C i2GO 2m 3a Nylon Trançado Chumbo *Garantia i2GO: Esse produto está garantido contra defeitos de fabricação por 1 ano. Para ativar 2 anos mais (3 anos no total), registre seu produto em nosso site.', 78.9, 39.9, NULL, 'Mobile & Gadgets > Accessories > Cables, Chargers & Converters', 'https://cf.shopee.com.br/file/sg-11134201-7rcet-lt43ly5ju61bf3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1182069552%2F19097655719', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23998424598', 'Tênis Rainha Vl 2500 RA0001', 'Conheça o Tênis Rainha VL 2500, perfeito para compor seu visual no dia a dia, com muito estilo e conforto! Ele é feito em material têxtil macio e confortável com recortes estilizados e um solado emborrachado. Aproveite e aposte em looks modernos com esse modelo inspirado no streetstyle.', 259.89, 152.88, NULL, 'Men Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-81zw4-milwfbm9xhj8f5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F920605202%2F23998424598', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43723412261', 'Lampada Led Pera Filamento Clear 9w/15w 2700k/4000k/6500k Branco Quente/Neutro/Frio E27 Bivolt Deluxe By Avant', 'A nova lâmpada Pera Filamento da Deluxe By Avant possui versões para todos os gostos, escolha a sua favorita e encante-se. Com seu design clássico e tecnologia de filamento LED, ela é a escolha perfeita para criar ambientes aconchegantes e cheios de estilo, aliando beleza vintage com a eficiência da iluminação moderna. PROPRIEDADES: Material: Base em alumínio, corpo e bulbo em vidro. CARACTERÍSTICAS DE FUNCIONAMENTO: Tensão nominal: 100V - 240V (Bivolt Automático) Potência nominal: 9W ou 15W Corrente nominal: 127V - 85mA | 220V - 60mA Fator de potência: 0,70 Frequência: 50-60Hz Eficiência luminosa: 100 lm/W ESPECIFICAÇÕES TÉCNICAS E COMERCIAIS: Modelo: Pera Filamento Clear Fluxo Luminoso: 900 lm ou 1500 lm Temperatura de Cor: Branco Quente 3000k, Neutro 4000k ou Frio 6500k Base: E27 IRC: 80 Ângulo de Abertura: 180° Medidas: 60mm x 105mm Vida Útil: 25.000 horas Índice de Proteção: IP20 (Uso Interno) Dimerizável: Não Garantia Oficial da Marca de 12 meses para defeitos de fabricação. Sobre a Marca A Deluxe By Avant é referência em iluminação, desenvolvendo produtos que combinam design, tecnologia e eficiência. A marca se compromete com a qualidade e a inovação para iluminar seus espaços.', 49.9, 34.9, NULL, 'Home & Living > Lighting', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mfmp7d8i00e8cf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1297519240%2F43723412261', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19298104893', 'Conjunto Fitness Feminino Poliamida Cintura Alta Basic Lux', 'Conjunto Fitness Feminino Poliamida Cintura Alta Basic Lux As leggings para academia da Rocca! com tecnologia Zero Transparência garantem total confiança durante os treinos, pois evitam que o modelo fique transparente, mesmo em movimentos mais intensos. Isso oferece maior segurança e conforto para quem se preocupa com a privacidade e a qualidade do tecido. Feita para te acompanhar em todos os momentos, a legging Vermelha é ideal para quem está sempre em ação. Além disso, a tecnologia Easy Care torna a manutenção da legging muito mais fácil, já que o tecido é resistente a amassados e mantém sua forma e cor mesmo após várias lavagens. Essas tecnologias combinadas oferecem máximo desempenho, praticidade e durabilidade, permitindo que o modelo continue impecável e confortável a cada uso. Produção responsável Sabia que 100% dos produtos ROCCA ! são fabricados no Brasil, com 100% produzidos em nossas próprias fábricas? Colocamos as pessoas em primeiro lugar, guiados por nosso Código de Conduta que enfatiza o "Programa de Trabalho Justo".', 124.9, 112.41, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > Sets', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m8nhng9b6gep6b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F675303259%2F19298104893', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
