INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19797678526', 'Boneco Funko POP! The Exorcist Regan', 'Aos 12 anos, Regan foi possuída por algo maligno, horrorizando todos ao seu redor, e ela clama por ajuda para ser libertada disso. Você será capaz de ajudar o Boneco Funko POP! Regan a encontrar ajuda em sua coleção de O Exorcista. A figura de vinil tem aproximadamente 10 centímetros de altura.', 164.99, 164.99, NULL, 'Hobbies & Collections > Collectible Items > Action Figurines', 'https://cf.shopee.com.br/file/sg-11134201-7rd5o-lvay3u9denvzaa', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F689242394%2F19797678526', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '46360393523', 'Mãozinha Beleza Brasileira 35g Creme Hidratante para Mãos Anti-Idade Rápida Absorção Mãos Ressecadas', 'Creme para as mãos que promove hidratação e maciez. Possui ativos que reduzem os sinais de envelhecimento e oferece ação desodorante. Com toque seco e rápida absorção, a pele das mãos ficarão hidratadas o dia todo. O que só ele faz: - Ação rejuvenescedora e pró firmeza. - Ação desodorante com fragrância floral frutal. - Toque seco e rápida absorção. Quando usar? Use diariamente. Reaplique durante o dia, sempre que sentir necessidade. Como usar o Mãozinha? Aplique nas mãos uma pequena quantidade e espalhe, até a completa absorção. Pode ser usado mais de uma vez no dia.', 49.9, 39.0, NULL, 'Beauty > Hand, Foot & Nail Care > Hand Care', 'https://cf.shopee.com.br/file/br-11134207-820lk-mo5ghzzemyv6bb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F500017527%2F46360393523', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
