INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23307000689', 'Pote Rosto Dolomita com Tampa de Bambu - Oikos', 'Esse é o pote rosto dolomita com tampa e bambu da OIKOS. Versátil: ele vai bem em todos os cantos da casa: no banheiro, na sala, no quarto, no escritório, dentro dos armários, nas prateleiras e onde mais você quiser. Bem prático: ótimo para guardar e organizar itens de banheiro como cotonetes, algodão e grampos. acessórios pequenos como brincos, anéis e pulseiras. objetos variados como clipes, moedas e produtos de cozinha como ervas e temperos. Decorativo: com formato de rosto e cores únicas, esse pote pode ser utilizado também como item decorativo. um ponto de cor que transforma qualquer ambiente ;) Tampa de bambu: o bambu não gosta de umidade ou contato com água por muito tempo, é bom guardar sempre em local seco e arejado. Detalhe do material: a dolomita é um material resistente e durável. com acabamento fosco, ele combina com vários estilos de decoração, do elegante ao mais rústico. Dimensões do produto: Altura: 14Cm Largura: 10Cm Comprimento: 14Cm', 86.9, 71.9, NULL, 'Home & Living > Bathrooms > Toothbrush Holders & Toothpaste Dispensers', 'https://cf.shopee.com.br/file/sg-11134201-8262q-mlf7u42a2eit6a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F752849300%2F23307000689', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
