INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18069896293', 'Balde dobrável de plástico 5 litros - Simplo', '"Conheça o Balde dobrável de plástico 5 litros da Simplo. Multiuso, resistente e fácil de guardar, é ideal para organizar a lavanderia e economizar espaço. Possui alça para facilitar o transporte, é retrátil com aros estruturados e diminui a altura em até 5 vezes! É de PP / TPR. Limpe bem e seque a bacia antes de guardar. Evite deixar no sol ou perto de outras fontes de calor. Não use com água sanitária e outros produtos que contenham cloro, removedores, produtos à base de petróleo ou líquidos oleosos. Leve funcionalidade e modernidade para sua casa! Segure a borda externa e pressione o fundo para abrir. Para fechar, apoie o fundo em uma superfície lisa e feche dobra por dobra. Ideal para organizar a lavanderia e economizar espaço. - Economiza espaço (diminui a altura em até 4x). - Com alça para facilitar o transporte. - Com apoio de mão. - Fácil de guardar. - Resistente: retrátil com aros estruturados. - Multiuso: sempre a mão para o que precisar. Limpe bem e seque o balde antes de guardar. Evite deixar no sol ou perto de outras fontes de calor. Não pode: - Usar com água sanitária e outros produtos que contenham cloro, removedores, produtos à base de petróleo ou líquidos oleosos."', 80.9, 57.9, NULL, 'Home & Living > Home Care Supplies > Basins, Buckets & Water Dippers', 'https://cf.shopee.com.br/file/br-11134211-23010-wubwxagoozlvcf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F752849300%2F18069896293', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23399348421', 'KIT REPARO ALTO FALANTE TARAMPS 7DRIVER SL 3K1 15 POLEGADAS ORIGINAL', 'Utilizados na manutenção de alto falantes danificados, os kits de reparo são procurados quando ocorre queima da bobina ou algum tipo de dano no cone do alto falante. O kit reparo possibilita efetuar o reparo do alto, evitando assim a necessidade de compra de um novo alto falante. Especificações do Kit Reparo Alto Falante Taramps 7Driver SL 3K1 15 polegadas Original: Produto original Taramps 7Driver; Reparo para woofer com bobina queimada ou cone danificado; Fácil substituição; Acompanha cola; Acabamento central original; Encaixe perfeito; Kit Reparo Alto Falante Taramps 7Driver SL 3K1 15 polegadas Original Composto por: - 1 Cone com bobina; - 1 Acabamento central; - 1 Jogo de guarnição; - 1 Cola; *Por se tratar de um reparo, o mesmo só terá garantia caso a substituição seja realizada em uma autorizada da marca; *Somente a autorizada que fez a substituição poderá acionar garantia do fabricante caso o mesmo apresente defeito; *Não será aceita a devolução de reparo já instalado no alto falante; *A resistência da bobina deve ser aferida antes da instalação; *Não se responsabilizamos por instalação mal realizada; *A impedância do reparo deve ser a mesma do alto falante, caso contrário não será compatível; *Este reparo é específico para o modelo anunciado, não é compatível com outro alto falante; *É de responsabilidade do profissional que fará a substituição garantir que a bobina fique centralizada livre de contato com o GAP; *Não se responsabilizamos por mau uso do produto (Ex: Queima da bobina ou cordoalha, centragem ou borda cortada, cone dobrado ou cortado na base da bobina); *Só aceite receber a mercadoria após verificar se a mesma coincide com a que consta no pedido e se está em perfeito estado; *Em caso de duvidas utilize o campo de perguntas antes de fazer o pedido;', 484.99, 484.99, NULL, 'Audio > Home Audio & Speakers > Others', 'https://cf.shopee.com.br/file/sg-11134201-8262u-mkybtp8ob8jqd6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F406280808%2F23399348421', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
