INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44429929209', 'FILTRO DE AR ESPORTIVO PLASMOTO LAVAVEL TITAN FAN START 125 150 160 2014 A 2025', 'O Filtro de Ar Esportivo Plasmoto é a escolha ideal para quem busca melhor desempenho e economia a longo prazo. Com elemento filtrante lavável, proporciona maior fluxo de ar para o motor, contribuindo para uma resposta mais eficiente sem abrir mão da proteção. Fabricado com materiais de alta qualidade, possui excelente vedação e encaixe perfeito, garantindo instalação simples e sem adaptações. Compatibilidade Honda Titan 125 Honda Fan 125 / 150 / 160 Honda Start 160 Anos: 2014 a 2025 Características do Produto Marca: Plasmoto Tipo: Filtro de ar esportivo lavável Cor externa: Preto Elemento filtrante: Vermelho Reutilizável (lavável) Alta durabilidade Melhor fluxo de ar para o motor Vantagens Pode ser lavado e reutilizado, gerando economia Ajuda na melhor respiração do motor Mantém proteção contra impurezas Instalação fácil, padrão original Conteúdo da Embalagem 1 Filtro de Ar Esportivo Plasmoto', 69.78, 69.78, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-81zv6-mmw3epczlg5cc1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1297313782%2F44429929209', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
