INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21898075977', 'Lip Oil Epidrat Hyalu Berry FPS30 - 6mL', 'EPIDRAT HYALU LIP OIL FPS 30 BERRY hidrata, proporcionando o brilho ideal, volume e preenchimento dos lábios, sem causar desconforto. Reduz os vincos, deixando os lábios realçados e nutridos. Possui ácido hialurônico, vitamina E e óleo de rosa mosqueta, ativos que proporcionam maior poder de hidratação, ação antioxidante e rejuvenescedora. Com tivehecimente 5 PS 30 Contee proteção contra os raios UVA e UVB. Este produto não é um protetor solar.Hipoalergênico. Dermatologicamente testado. Não escorre nos lábios.', 79.9, 79.9, NULL, 'Beauty > Makeup > Lips', 'https://cf.shopee.com.br/file/sg-11134201-825zr-mja5qkqxw4job0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1392870796%2F21898075977', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23891891959', 'PNEU TRASEIRO PIRELLI 150/70-17 SPORT DEMON TL 69H SEM CÂMARA', 'PNEU TRASEIRO 150/70-17 SPORT DEMON TL 69H ORIGINAL Marca: PIRELLI Modelo: SPORT DEMON Medida: 150/70-17 Aro: 17 Índice de peso: 69 Índice de velocidade: H Posição: TRASEIRO Tipo de Montagem: SEM CAMARA Cód Barras: 8019227134339 Observações: Produto novo. Imagem meramente ilustrativa Garantia: 5 anos Contra Defeito de Fabricação Observações: Não informamos e nem enviamos um DOT específico de pneu. Temos uma grande quantidade de pneus em estoque e um alto fluxo de pedidos diários que impossibilita o envio de um pneu com DOT específico. Todos os nossos produtos possuem fabricação recente, são novos, originais e ACOMPANHA NF. NAO TRABALHAMOS COM PNEUS REMOLD. ATENCAO !! Garantia de 5 anos somente por defeitos de fabricação, ficando inválida em caso de danos por acidentes, buracos na pista, mau uso e ainda má instalação. É necessário e indispensável instalar o pneu com um profissional especializado. Em relação a trocas e/ou devoluções, salientamos que deve observar o prazo para realizar a mesma. Os itens devem estar obrigatoriamente, no mesmo estado em que recebeu e com suas etiquetas. NÃO ACEITAMOS DEVOLUÇÕES DE PNEUS QUE JÁ FORAM MONTADOS E/OU USADOS. -Todas as garantias são dadas pelos fabricantes, e variam de produto para produto. Caso tenha alguma dúvida, entre em contato conosco. -Para devoluções, os produtos deverão ser remetidos em suas embalagens originais. -Certifique-se de preencher corretamente seus dados pessoais e endereço para que não haja problemas com o pedido. -Imagem meramente ilustrativa -Tire todas as dúvidas antes da compra. -Evite transtornos!', 802.0, 802.0, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Motorcycle Tires', 'https://cf.shopee.com.br/file/sg-11134201-7rdwx-lykzcxjy0js8f5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F842545535%2F23891891959', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
