INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22096982114', 'ADITIVO FLUIDO RADIADOR PETRONAS COOLANT 11 INORGÂNICO CONCENTRADO VERDE 1L', 'O PETRONAS COOLANT 11 é um fluido especial concentrado a base de monoetilenoglicol, usado em sistemas de arrefecimento de veículos para baixar o ponto de congelamento e elevar o ponto de ebulição da água. Contém aditivação isenta de aminas e fosfatos. Possui propriedades antiferrugem, antiespuma e alto nível de reserva alcalina, o que evita qualquer tendência à corrosão, quando utilizado naconcentração correta e deve ser utilizado na concentração de 50% de produto e 50% de água desmineralizada, ou conforme recomendação do fabricante, não podendo, assim, ser misturado com fluido de arrefecimento de aditivação orgânica. ESPECIFICAÇÕES NBR 13705; ASTM D-3306; ASTM D-4985. ITENS INCLUSOS: 01 - Aditivo Radiador Inorgânico Concentrado Paraflu Coolant 11', 67.82, 67.82, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Additive and Lubricant', 'https://cf.shopee.com.br/file/br-11134201-7r98o-m0bzqvhavhb19f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1073836395%2F22096982114', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
