INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23398853584', 'Jogo 3 Peças Com Lençol King E Duas Fronhas Lisa Mikasa', 'LENÇOL ESSENCE LISO JOGO KING 3 PEÇAS PRODUTO ORIGINAL COM NOTA FISCAL Com toque macio e acabamento sofisticado, o lençol Essence Liso é a escolha certa para transformar sua cama em um espaço de puro conforto. O jogo queen vem completo com 3 peças, incluindo o lençolde elástico que se ajusta perfeitamente ao colchão de 1,93m x 2,03m x 40cm, garantindo caimento impecável durante toda a noite.As DUAS fronhas, no tamanho 50cm x 70cm, oferecem a mesma suavidade e elegância, proporcionando noites de sono tranquilas e revigorantes.Disponível nas cores areia, branco e cinza, combina facilmente com qualquer estilo de quarto, trazendo praticidade e um visual moderno. Garantia: 7 Dias', 129.9, 129.9, NULL, 'Home & Living > Bedding > Bedsheets, Pillowcases & Bolster Cases', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mdz080ld0jk393', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F312703265%2F23398853584', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
