INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21839034353', 'Kit Relação Tração Transmissão CBX 250 Twister 2001 2002 2003 2004 2005 2006 a 2008 Original Cofap', 'PREÇO REFERENTE A UM KIT RELAÇÃO / TRAÇÃO / TRANSMISSÃO - NOVO CÓDIGO: TMC410001 MARCA: COFAP (ORIGINAL) ______________________________________________ APLICAÇÕES: Honda | CBX 250 TWISTER | 2001 Á 2008 COMPONENTES: 1 Corrente - 520HX106L 1 Coroa - 37 Dentes 1 Pinhão - 13 dentes ______________________________________________ OBSERVAÇÕES IMPORTANTES: * Produto com garantia de 3 meses. * Produto em estoque e com envio em imediato. * Recomendamos que os produtos sejam instalados por profissionais especializados A marca COFAP existe desde 1951 no mercado brasileiro e, a partir dos anos 70, graças a um formidável esforço de exportação, em 98 países dos 5 continentes. Inicialmente, a marca foi utilizada para produtos da linha motor, mas, logo em seguida, passou a ser utilizada também para os produtos Undercar, cujo carro-chefe é, sem dúvida, o amortecedor, percebido pelo mercado brasileiro como um produto sinônimo da marca "top of mind" do segmento de autopeças. Se é Cofap, é de confiança e no mundo inteiro.', 150.0, 124.5, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Transmission', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lxlg8a3yv1drf8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F843202413%2F21839034353', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
