INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19499238032', 'Cola de Contato Kisafix - Galão 2,8Kg Sapateiro, MDF, Couro, Tecidos, Platicos, Aluminios | Direct Borrachas', 'Adesivo de Contato à Base de Solvente – Galão 2,8kg | Killing Adesivo profissional de alta performance, indicado para aplicações em diversos materiais. Desenvolvido à base de borracha de policloropreno e solventes potentes, proporciona colagem rápida, resistente e duradoura. Ideal para o setor moveleiro, tapeçaria, calçadista, automotivo e outras aplicações que exigem fixação firme. Principais Benefícios Colagem forte e de alta durabilidade Aplicação fácil e rendimento excelente Aderência em materiais porosos e não porosos Secagem rápida (10 a 30 minutos, conforme ambiente) Aplicações Indicadas Ideal para colagens em: - Madeira, MDF, compensado, aglomerado - Couro, tecidos, espumas e borracha - Metais, plásticos (ABS), fibra natural - Pisos vinílicos, carpetes e materiais emborrachados - Fitas de borda, lâminas decorativas (HPL, MDP) Características Técnicas - Composição: Borracha de policloropreno, resinas sintéticas, hexano, tolueno, acetona e solventes alifáticos e aromáticos - Aspecto: Líquido viscoso - Teor de sólidos: 18% a 21% - Viscosidade Brookfield: 2900 a 3300 cP - Densidade: 0,855 a 0,880 g/cm³ - Secagem ao toque: 15 a 30 minutos - Peso líquido: 2,8 kg - Medidas da embalagem: 18 x 19 cm - Tipo de embalagem: Galão - Fabricante: Killing Modo de Aplicação Limpe bem as superfícies que serão coladas. Aplique uma camada uniforme do adesivo em ambas as partes. Aguarde de 10 a 30 minutos (dependendo da temperatura e ventilação). Una as partes e pressione firmemente para garantir a fixação. ⚠️ Atenção: Produto inflamável. Manusear em local ventilado e longe de fontes de calor. ✔️ Produto original com qualidade comprovada.', 120.0, 120.0, NULL, 'Home & Living > Tools & Home Improvement > Industrial Adhesives & Tapes', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mcrw5ypahce9c7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F386232023%2F19499238032', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41765883617', 'Boneco Funko Pop! One Piece Rob Lucci com Hattori com Chase', 'Prepare-se para uma missão de elite com o Boneco Funko Pop! Rob Lucci com Hattori (Chase)! Esta edição exclusiva da linha POP! & Buddy traz o enigmático agente da CP9 ao lado de seu inseparável pombo, Hattori, com chance de encontrar a versão rara Chase com terno preto (1 em cada 6 unidades). As figuras de vinil medem aproximadamente 11 centímetros (Lucci) e 3 centímetros (Hattori) e vêm com embalagem especial de autenticação via Octane5. Ideal para fãs de One Piece e colecionadores que buscam peças únicas, cheias de estilo e ação. Não perca essa adição poderosa para sua tripulação!', 199.99, 199.99, NULL, 'Hobbies & Collections > Collectible Items > Action Figurines', 'https://cf.shopee.com.br/file/sg-11134201-824i5-me0j188h7ochc6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F689242394%2F41765883617', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '26239288135', 'Mixer Mondial Power Red Premium 2 em 1 com Lâminas em Aço 500W Vermelho/Inox 220V - M-10', 'O Power Mixer Red Premium Mondial M-10 é perfeito para quem busca praticidade e versatilidade no dia a dia. Com 500W de potência e função Turbo, ele mistura, tritura e processa alimentos com rapidez e eficiência. Ideal para preparar vitaminas, sopas, caldos, molhos, cremes e triturar grãos, legumes, temperos e muito mais. BENEFÍCIOS: 2 em 1: Mixer + Processador de alimentos para mais praticidade. Função Turbo: Potência extra para triturar alimentos mais consistentes. Lâmina em Aço Inox: Resistente, corta em múltiplas direções e é ideal até para alimentos quentes. Jarra de 800mL com Tampa: Armazene e prepare suas receitas com praticidade. Porta-acessórios: Organização e economia de espaço. Base Antideslizante: Mais estabilidade no uso. CARACTERÍSTICAS: Modelo: M-10 Potência: 500W Funções: Mixer e Processador Voltagem: 220V Cor: Vermelha/Inox Capacidade da jarra: 800mL Dimensões: 38 cm (A) x 6,5 cm (L) x 6,5 cm (P) Peso: 1,2 kg CONTEÚDO DA EMBALAGEM: 1 Mixer + 1 Processador + 1 Copo com tampa + 1 Porta-acessórios + 1 Manual de instruções', 279.9, 229.9, NULL, 'Home Appliances > Kitchen Appliances > Mixers', 'https://cf.shopee.com.br/file/sg-11134201-7rdvf-mcrtx8oes9a167', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1296760327%2F26239288135', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
