INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23092638886', 'Piercing Helix Conch Tragus Labret Aço Cirúrgico Pvd Tridente 1 Zircônia', 'Bem-vindo a 《LOMISS》🎉🎉🎉 Somos uma grande empresa de piercing de São Paulo. Todos os produtos da loja são produtos de alta qualidade e a pronta entrega. Clique em "Seguir" e obtenha o cupom de desconto "5%off" LABRET - Modelo: Labret - Espessura Da haste:1.2 mm - Comprimento da haste: 8mm - Material: Aço Cirúrgico - Pedra: Zircônia - Fecho: Rosca Piercing 100% Novo e a Pronta Entrega - Podendo ser Usado: Helix, Tragus, Conch, Nariz, Boca-Medusa e Outros Lembrando que: Cada pessoa tem formato de corpo/local de aplicação (mais pra dentro/fora), então varia com tamanho de joia. Fácil Colocação e Remoção *PVD - É uma tecnologia utilizada para a deposição de filmes metálicos finos sobre diversos tipos de substratos. O processo é realizado, sob vácuo, onde os metais a serem depositados são evaporados. É particularmente indicado para aqueles produtos inovadores e de qualidade que necessitam atender elevados padrões e permite ainda obter uma vasta gama de cores. - Elevada resistência ao desgaste e abrasão; - Resistência ao suor e transpiração humanos; - Hipoalergênicos. ✚ Como cuidar de suas joias novas ✚ As joias corporais, independentemente do material, requerem cuidados redobrados, pois o material pode penetrar na carne. Recomendamos o seguinte. - Sempre remova as joias durante esportes com suor intenso, natação e banho, pois qualquer coisa, desde água, óleo, cloro, perfume e suor, pode danificar as joias. - Se for necessário limpar, use sempre água morna e sabão neutro. Nunca use álcool ou quaisquer produtos químicos, pois podem causar descoloração ou outras reações adversas às joias. Certifique-se de secar bem o corpo e as joias antes de reinserir. Certifique-se de usar um pano macio e não abrasivo para evitar riscar o metal. - Se você tiver alguma reação a joias folheadas (como colares, pulseiras, anéis, etc.), não recomendamos nenhuma joia folheada, pois você pode ter uma reação semelhante. - Recomendamos que você guarde suas joias em uma bolsa com zíper quando não estiver em uso.', 54.9, 54.9, NULL, 'Fashion Accessories > Additional Accessories > Others', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lnspuw14y7yk83', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F493729464%2F23092638886', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22693823466', 'Piercing Transversal Titânio Losango Zircônia Cravejada', '💖 💖 🥳 🥳 Bem-vindo a 《LOMISS Piercing》🥳 🥳 💖 💖 🎊🎊👍👍Somos uma grande empresa de piercing. O endereço está localizado em São Paulo.Todos os produtos da loja são de alta qualidade. 👍👍🎊🎊 🚚 🚚🚀 🚀 Temos uma grande quantidade de estoque. Enviaremos seu pedido em até 24 horas após o pagamento. 🚀 🚀🚚 🚚 🎉🎉🎫 🎫Clique em """"SEGUIR"""" e receba vouchers de desconto exclusivos.🎫 🎫🎉🎉 ---------------------------------------------------------------------------------------------------------------- ⭐⭐O produto é 100% titânio puro. Absolutamente sem alergias!! ⭐⭐Características:Resistente à corrosão, alta resistência, Inibição de bactérias, não alergênico！ 💎- Diâmetro Interno: 38mm 💎- Espessura da Haste: 1.6mm 💎- Material:Titânio 💎- Fecho: Rosca 💎- Pode Ser Usado: Orelha - Transversal 💎- Quantidade: 1 Unidade Lembrando que: Cada pessoa tem formato de corpo/local de aplicação (mais pra dentro/fora), então varia com tamanho de jóia. Fácil Colocação e Remoção Piercing 100% Novo e a Pronta Entrega *PVD - É uma tecnologia utilizada para a deposição de filmes metálicos finos sobre diversos tipos de substratos. O processo é realizado, sob vácuo, onde os metais a serem depositados são evaporados. É particularmente indicado para aqueles produtos inovadores e de qualidade que necessitam atender elevados padrões e permite ainda obter uma vasta gama de cores. - Elevada resistência ao desgaste e abrasão; - Resistência ao suor e transpiração humanos; - Hipoalergênico.', 85.8, 46.9, NULL, 'Fashion Accessories > Additional Accessories > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rd3u-m78g9e73vo3094', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F493729464%2F22693823466', NULL, NULL, '2026-07-28T02:11