INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23298978117', 'Tinta guache Neon Laranja 250ml 0105 Acrilex', 'INMETRO 002188/2014 A Tinta Guache Neon Acrilex é perfeita para estimular a criatividade e deixar os trabalhos artísticos ainda mais divertidos e vibrantes. Com acabamento em cores neon intensas, proporciona efeito luminoso e diferenciado, ideal para destacar desenhos, pinturas e projetos escolares. Detalhes: - Não tóxico - Cores vibrantes e com efeito neon - Para trabalhos artísticos, escolares. - Importante para o desenvolvimento da criatividade, coordenação motora e percepção visual das cores. - Pode ser aplicado em papel, papel cartão, cartolina, gesso, madeira, cerâmica e E.V.A.', 27.76, 23.6, NULL, 'Stationery > Art Supplies > Water & Poster Colours', 'https://cf.shopee.com.br/file/sg-11134201-82596-mqbz41gihde3bc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400736454%2F23298978117', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
