INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19035141589', 'Limpador Diluível Ajax Fresh 1l', 'Furação de Limpeza Profunda e Sem Agressão - Brilho intenso sem resíduos Ajax Fresh Limpeza Pesada é indicado para limpeza geral de pisos, azulejos, vidros, cerâmicas e superfícies laváveis. Proporciona uma limpeza profunda sem agredir as superfícies e deixa sua casa com um agradável cheirinho de limpeza. Tem um rendimento incrível pois é diluível em água. Quer saber como usar? É fácil: Dilua 2 tampas e meia do produto em 5 litros de água. Umedeça o pano e passe sobre as superfícies a serem limpas. Se a limpeza é pesada, pode-se utilizar puro com um pano úmido na remoção de manchas e sujeiras mais difíceis. 1L – Rende até 60 litros.', 25.79, 25.79, NULL, 'Home & Living > Home Care Supplies > Cleaning Agents', 'https://cf.shopee.com.br/file/sg-11134201-7rbl6-lopq3tu7m7uu8f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F557242410%2F19035141589', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
