INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23099144398', 'Mochila Grande 2 Compartimentos Notebook 17 Sestini Work 2 - Preto', 'A mochila grande Sestini Work 2 é a escolha ideal para quem busca praticidade e estilo no dia a dia. Com um design moderno e funcional, ela é perfeita para transportar um notebook de até 17 polegadas, garantindo segurança e conforto. Confeccionada em poliéster de alta qualidade, a mochila conta com dois compartimentos principais, permitindo uma organização eficiente dos seus pertences. O compartimento acolchoado para o notebook oferece proteção extra, enquanto o organizador interno facilita o armazenamento de itens menores, como canetas e documentos. As alças de mão espumadas e a alça carona proporcionam conforto ao carregar, mesmo em longas distâncias. As costas e alças espumadas garantem um ajuste confortável ao corpo, tornando o transporte mais agradável. Além disso, os bolsos laterais em tela com elástico são ideais para guardar garrafas de água ou outros objetos que precisam estar sempre à mão. O fechamento com zíper e os puxadores com trava para cadeado oferecem segurança adicional, permitindo que você transporte seus itens com tranquilidade. O logo em metal confere um toque de sofisticação ao design da mochila, que é perfeita tanto para o ambiente de trabalho quanto para o uso diário. Com a mochila Sestini Work 2, você terá um acessório prático, confortável e estiloso, ideal para acompanhar sua rotina.', 299.9, 299.9, NULL, 'Baby & Kids Fashion > Baby & Kids Accessories > Bags & Luggage', 'https://cf.shopee.com.br/file/sg-11134201-821f1-mgwi7w6230nfa6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F867958784%2F23099144398', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22699171728', 'Conjunto infantil menino blusão e calça manhattan Fakini', 'Conjunto blusão e calça em moletom! O blusão possui decote redondo, mangas longas, estampa frontal, modelagem e comprimento regular. A calça possui elástico o cós, modelagem regular e comprimento alongado com barra. Composição: Cor Cinza Mescla: Blusão e Calça 94% Algodão 6% Poliéster Cor Marinho: Blusão e Calça 100% Algodão Cor Preto: Blusão e Calça 100% Algodão Cuidados com o produto: Lavagem a mão Temperatura máxima 40ºC Não alvejar Não secar em tambor Secagem em varal a sombra Temperatura máxima da base do ferro a 110°C sem vapor Vapor pode causar danos irreversíveis Não limpar a seco.', 114.9, 114.9, NULL, 'Baby & Kids Fashion > Boy Clothes > Suits & Sets', 'https://cf.shopee.com.br/file/sg-11134201-8260g-mloyl8fep1xh98', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1658229758%2F22699171728', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
