INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23094337147', 'Kit 4 Águas Desmineralizadas Koube 1L Radiador Bateria e Limpador', 'PRODUTO NOVO Precisa de água pura e segura para radiador, bateria ou limpador de para-brisa? Características do Produto – Marca: Koube Químicos – Tipo: Água desmineralizada premium – Conteúdo: 4 frascos de 1 litro (31760X4) – Aparência: Líquido límpido, incolor – Condutividade elétrica: Baixa – Isento de sais minerais e íons Por que escolher este produto – Alto grau de pureza – Evita corrosão em radiadores e baterias – Mantém o desempenho do sistema de arrefecimento – Prolonga a vida útil de baterias e aditivos – Pode ser usado também em limpadores de para-brisa Dicas de Uso – Use para diluir aditivos concentrados, conforme recomendação do fabricante – Em baterias e reservatórios de limpador, adicione diretamente – Nunca utilizar como água potável (imprópria para consumo humano) Perguntas Frequentes – Pode ser usada pura no radiador? Sim, mas o ideal é diluir aditivos concentrados conforme indicação do fabricante. – É compatível com qualquer marca de bateria? Sim, pode ser utilizada em todas as marcas de baterias automotivas. – Qual a diferença entre água comum e desmineralizada? A água comum possui sais minerais e impurezas que podem causar corrosão, já a desmineralizada é pura e segura. – O produto é pronto para uso em limpadores de para-brisa? Sim, basta adicionar diretamente no reservatório do veículo. Escolha qualidade e segurança para seu veículo.', 54.07, 48.67, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Additive and Lubricant', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mdqdt4zo9upl50', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1552175911%2F23094337147', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
