INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22092593963', 'Lanterna Refil Módulo Corujinha Traseira LED Carreta Facchini Original Aspock Braspoint III e IV 24V Freio Luz Ré', 'Lanterna Refil Módulo Corujinha Traseira LED para Carreta Facchini Original Aspock Braspoint III e IV 24V Freio + Luz + Ré Chegou a hora de você economizar comprando a Lanterna Refil Módulo Corujinha Traseira LED para Carreta Facchini Original Aspock Braspoint III e IV 24V Freio + Luz + Ré Aplicação compatível - Compatível com as lanternas Braspoint III a VI - Corujinha Parabrisa O que acompanha - 01un Lanterna Refil Módulo Corujinha Traseira LED para Carreta Facchini Original Aspock Braspoint III e IV 24V Freio + Luz + Ré Cor - Vermelho Material - Acrílico Dimensões - Medidas (AxLxP) 6 x 15 x 15 cm Peso - 0,300 Kg Fabricante - Aspock Código Fabricante -1113400 Outros diferenciais - Compatível com as lanternas Braspoint III a VI - Posição, freio, ré - Peça com excelente acabamento e encaixes perfeitos - 24V - Original Aspöck Confiança e Transparência: As informações de linha e códigos originais são fornecidas apenas como referência para facilitar e garantir a escolha certa do produto para seu veículo.', 167.35, 167.35, NULL, 'Spare Parts and Accessories for Vehicles > Heavy Duty and Boats > Spare Parts for Heavy Duty Vehicles', 'https://cf.shopee.com.br/file/sg-11134201-7rbmt-lnbtezl4ejir42', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F908791545%2F22092593963', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23193589592', 'Grecin 5 Shampoo Tintura Tonalizante Castanho Médio Escuro H-40 60ml - Cobre os cabelos grisalhos em 5 minutos.', 'Grecin 5 Shampoo tonalizante cobre todo o grisalho em 5 minutos. para uma aparência natural. - Fácil e rápido: Elimina os grisalhos em 5 minutos. - Fórmula patenteada, combina com a cor original do cabelo para resultados com aparência natural. - O resultado é duradouro, basta reaplicar quando os fios grisalhos crescerem novamente. - Sem amônia, é suave com os cabelos, deixando-os com uma aparência mais volumosa e sem grisalhos. - Nova fórmula com Queratina, Azeite de Oliva e Vitamina E. Aparência jovem e natural. Simples assim. IMPORTANTE: Sempre leia e siga as instruções de uso do folheto incluso. *Lembre-se de realizar o teste de alergia 48h antes de usar" Aplique. Espere 5 min. Lave com shampoo e enxague.', 29.9, 28.11, NULL, 'Beauty > Hair Care > Hair Colour', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m3uyz2lj59a02e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1356924405%2F23193589592', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23693673152', 'Kit 2x unidades Grecin Control Gx Shampoo De Barba e Redutor Grisalhos - Para todos os tipos de barba. Aparência jovem', '"Novo Control GX de Grecin, um shampoo que reduz gradualmente a barba grisalha deixando uma aparência natural e discreta. - Lave sua barba com ele diariamente, como seu shampoo comum, até chegar no resultado desejado. Depois, use algumas vezes por semana para manter o visual. - Reduz gradualmente o grisalho - Resultado discreto e aparência natural - Limpa e revitaliza a barba. Aparência jovem e natural. Simples assim. IMPORTANTE: Sempre leia e siga as instruções de uso do folheto incluso. *Lembre-se de realizar o teste de alergia 48h antes de usar"', 199.0, 169.15, NULL, 'Beauty > Men''s Care > Hair Care', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m5lyzhmn6iyt9e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1356924405%2F23693673152', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
