INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58213395702', 'PURINA FRISKIES® MOLHO CREMOSO para Gatos Adultos Mar de Sabores 80g - com 15 unidades', 'PURINA FRISKIES® MOLHO CREMOSO para Gatos Adultos Mar de Sabores 80g - com 15 unidades Com uma incrível variedade de combinações de sabores de proteína e molho cremoso, FRISKIES® proporciona um mundo divertido de nutrição e sabor. Friskies® Molho Cremoso é um alimento úmido para gatos feito sem corantes e conservantes artificiais, que pode ser orferecido como uma refeição, já que é 100% completo e balanceado. Ajuda a manter o seu gato saudável através da combinação de vitaminas e minerais essenciais. Contribui para um trato urinário saudável, auxilia na hidratação diária e contribui para pele e pelos saudáveis. Possui proteínas de alta qualidade que contribuem para manter músculos fortes. Especificações Técnicas: Modo de Usar:Abra o sachê e sirva o conteúdo em um recipiente limpo.Forneça de 2 a 3 sachês por dia para cada 4kg de peso do seu gato adulto, ou conforme orientação do veterinário.Se misturar com ração seca, ajuste as quantidades para manter o peso saudável do pet.Mantenha sempre água fresca e limpa à disposição.', 69.9, 69.9, NULL, 'Pets > Pet Food > Small Pet Treats', 'https://cf.shopee.com.br/file/sg-11134201-82583-mqcogmbweq6j17', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1738906516%2F58213395702', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22094738007', 'Garrafa Térmica de Água, Café e Chá 1L com Alça em Madeira Estilo Nórdico Minimalista Ideal para Mesa Posta e Uso Diário', 'A Garrafa Térmica Nórdica 1L une design moderno e praticidade em um produto ideal para quem aprecia beleza e funcionalidade no dia a dia. Seu estilo minimalista com alça curvada em madeira traz um toque sofisticado que valoriza qualquer mesa posta ou ambiente. Com isolamento térmico eficiente, mantém suas bebidas quentes ou frias por horas, sendo perfeita para café, chá, leite, sucos ou água. Produzida com materiais de alta qualidade, é resistente, fácil de limpar e combina perfeitamente com cozinhas modernas, escritórios ou espaços gourmet. Ideal para uso diário e também como presente elegante, a garrafa térmica nórdica é o equilíbrio perfeito entre design, funcionalidade e estilo. ✅ Destaques do Produto ☕ Mantém quente e frio por horas – ideal para café, chá, leite e água 🌿 Alça curvada em madeira natural – conforto, segurança e charme escandinavo 🧊 Isolamento térmico eficiente – conserva a temperatura e evita vazamentos ✨ Design nórdico minimalista – combina com ambientes modernos e sofisticados 🎨 Cores elegantes disponíveis – Bege, cinza taupe, Preto e Branco clássico 💧 Fácil de limpar e manusear – tampa prática e acabamento fosco premium 💝 Perfeita para mesa posta e presente – une beleza, praticidade e durabilidade 📦 Especificações Técnicas Capacidade: 1 Litro Material: Plástico resistente com alça em madeira natural Acabamento: Fosco premium Isolamento: Dupla parede térmica com vedação segura Dimensões: 25 cm de altura x 13 cm de largura Peso: 430 g Uso: Bebidas quentes e frias Cores: Bege , Cinza Taupe, Branco e Preto ( ESCOLHA A COR NO ANUNCIO)', 69.99, 69.99, NULL, 'Home & Living > Kitchenware > Tea, Coffee & Bartending Equipments', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mh8fxi7af9j8e7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F752637589%2F22094738007', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
