INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '55204534977', 'Caixa Para Ovo Colher 100/150g Ressurreição 6 Uni Cromus', 'A Caixa Horizonte para 1 Meio Ovo 100/150g Ressurreição foi desenvolvida para valorizar, proteger e apresentar seus produtos de forma elegante e significativa. Ideal para acomodar 1 meio ovo de Páscoa entre 100 e 150g, possui estampa temática Ressurreição, que transmite simbolismo, delicadeza e um visual especial para a celebração pascal. Conta com tampa em acetato transparente, que permite a visualização do produto e destaca o acabamento do chocolate, agregando valor à apresentação. Seu design funcional inclui espaço interno para acomodar colher, oferecendo praticidade na composição do presente, porém a colher não acompanha o produto. Produzida com matéria-prima de qualidade em papel cartão e acetato, apresenta estrutura resistente, fácil montagem e excelente estabilidade. Com medidas aproximadas de 14x11x6cm, o pacote contém 6 unidades, sendo a escolha ideal para confeiteiros e artesãos que buscam uma embalagem temática, organizada e que eleve o padrão do produto final.', 42.39, 31.37, NULL, 'Stationery > Gift & Wrapping > Others', 'https://cf.shopee.com.br/file/sg-11134201-82605-mjea6qmt50qo68', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1507942655%2F55204534977', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
