INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18154791964', 'Condicionador Millenar Oleos Gregos Restauração 300Ml Amend', 'CONDICIONADOR MILLENAR OLEOS GREGOS RESTAURAÇÃO 300ML AMEND Condicionador com alto poder emoliente. Sua fórmula combina o óleo de oliva e de camelina dourada ao Pro-Biofilm Complex que combatem e previnem danos causados por processos químicos, proporcionando brilho e hidratação profunda aos fios e atuando na reparação dos danos da fibra capilar. Dermatologicamente testado. Inspirados no conhecimento milenar do povo grego que buscava inspiração na beleza divina, desenvolvemos um condicionador com alto poder emoliente. Sua fórmula combina os óleos de oliva e de camelina dourada ao Pro-Biofilm Complex** que combatem e previnem danos causados por processos de transformação, tais como *descoloração, relaxamento ou alisamento, proporcionando brilho e hidratação profunda aos fios e atuando na reparação dos danos da fibra capilar. Livre de Petrolato, Parabenos e Corantes. Dermatologicamente testado.', 67.54, 67.54, NULL, 'Beauty > Hair Care > Hair and Scalp Conditioner', 'https://cf.shopee.com.br/file/sg-11134201-7ra18-m4p3ayeekjyz1e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F385388689%2F18154791964', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
