INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '16604689261', 'Ração Premier Ambientes Internos para Gatos Adultos com Pelos Longos Sabor Frango - 1,5Kg', 'PremieR Gatos Adultos Pelos Longos – Frango oferece ao seu gato adulto de pelos longos um cuidado especial todos os dias. Através de uma combinação de ingredientes nobres, realça a beleza da pelagem, tornando-a exuberante e macia. No entanto, esses pelos densos podem predispor à formação das “bolas de pelos”. Essas são resultado do acúmulo de pelos no trato digestório pelo hábito de se lamber dos felinos. PremieR Gatos Adultos Pelos Longos – Frango traz em sua fórmula fibras selecionadas como a aveia e polpa de beterraba que previnem a formação dessas indesejáveis “bolas de pelos”.', 130.81, 104.65, NULL, 'Pets > Pet Food > Cat Food', 'https://cf.shopee.com.br/file/727fdbf68d5ad4ace6968b2614a3c543', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F438604073%2F16604689261', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
