INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8869580246', 'Livro - Fred - Capa comum - Ciranda Cultural', 'O pai de Kátia fez uma portinha especial para Fred, mas o gatinho estava com medo de usá-la. Ele sabia que o terrível Max estava do lado de fora esperando para atacar... E agora? O que Fred vai fazer? Editora: Ciranda Cultural Edição: 1, 2014 Autor: Linda Jennings Idioma: Português Páginas: 32 Dimensões: L 24.50 x A 28.00 x E 0.40 ISBN: 9788538059059', 39.9, 39.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/57217e0cba18ff1caa6826c526aefd39', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F8869580246', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13319311576', 'Livro 50 mulheres para se inspirar Ciranda Cultural', 'Conheça neste livro grandes personalidades femininas que enfrentaram todo tipo de desafio e dificuldade para conquistar seu espaço no mundo e deixar seu legado. São incríveis histórias de perseverança, força e superação que vão inspirar você a encontrar e a lutar pela sua própria causa_x000D_ _x000D_ Editora: Ciranda Cultural_x000D_ Edição: 1, 2021_x000D_ Autor: Alice Ramos_x000D_ Idioma: Português_x000D_ Páginas: 112_x000D_ Dimensões: L 16.00 x A 23.00 x E 0.80_x000D_ ISBN: 9786555004311', 24.9, 24.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/1cce4650bf9d35b56cca7dd751b33406', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F13319311576', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22899192534', 'Pote Tupper Redondinha Kids 500ml', 'Com as Tupper Redondinhas, você pode manter os alimentos frescos e afastar umidade graças à tampa hermética. Elas são perfeitas para armazenar lanches, frutas, ingredientes secos e muito mais! A vida é corrida, e as suas refeições precisam acompanhar seu ritmo! Nossa tampa à prova de vazamentos garante que seus lanches ou pratos cuidadosamente preparados fiquem seguros, sem bagunça durante o transporte. Jogue na sua bolsa com confiança, sabendo que sua comida vai chegar intacta e pronta para saborear. Com um design externo belamente decorado, você pode até usá-la na despensa para armazenar grãos, na geladeira ou como organizador de materiais de artesanato, brinquedos infantis, materiais de escritório e muito mais. SOMOS A LOJA OFICIAL DA TUPPERWARE: TODOS OS NOSSOS PRODUTOS SÃO ORIGINAIS E VÊM DIRETO DA NOSSA FÁBRICA PARA O CONFORTO DO SEU LAR.', 113.12, 63.9, NULL, 'Home & Living > Kitchenware > Food Storage', 'https://cf.shopee.com.br/file/br-11134207-820l9-mmw36ukn8xs469', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1608053305%2F22899192534', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22993208272', 'Tênis Slip on Infantil Unissex Elástico Confort Pequito', 'O Tênis Slip on Infantil Unissex Elástico Confort apresenta um design moderno e prático, ideal para o dia a dia das crianças. O cabedal, parte superior, possui elásticos em forma de X que proporcionam um ajuste confortável e seguro, sem a necessidade de amarrar o cadarço e auxilia a desenvolver a autonomia da criança ao calçá-lo. A ponteira branca adiciona um toque de estilo, enquanto o solado antiderrapante oferece segurança, mantendo a leveza necessária para os momentos das brincadeiras. Do que o produto é feito? Solado emborrachado antiderrapante, cabedal em Neoprene, elástico em X na parte superior, biqueira em napa vegana com bordado. Tamanhos: 20 ao 34. Cor: Preto. Como medir o pé da criança: Selecione com atenção a cor e tamanho correspondentes com a medida do pé da criança. É importante estar com as medidas certas para realizar a compra, evitando trocas e devoluções. Passo 1: Coloque o pé da criança sobre uma folha de papel, em uma superfície reta. Passo 2: Marque o calcanhar e a ponta do dedão com um risco. Use a régua ou fita métrica para medir a distância entre as duas marcas e descubra a medida em centímetros do pé. Lembre-se que a medição começa a partir do número 0. A seguir, observe na tabela de medidas o número que mais se aproxima da quantidade de centímetros do pé da criança. Tabela de Medidas Comparar com a tabela disponível. 20. 13.7 cm 21. 14.3 cm 22. 15 cm 23. 15.7 cm 24. 16.3 cm 25. 17 cm 26. 17.7 cm 27. 18.3 cm 28. 19 cm 29. 19.7 cm 30. 20.3 cm 31. 21 cm 32. 21.6 cm 33. 22.3 cm 34. 23 cm Tênis Elástico Infantil Pequito - Características Gerais do Produto: • Faixa Etária: Pré Infantil - até 6 anos (20 ao 27) • Gênero: Unisex • Material Externo: Neoprene • Cor: Preto • Solado: Emborrachado antiderrapante • Limpeza e Conservação: Lavagem manual. Não utilizar escova, detergentes ou solventes. Evitar molho e secar a sombra. • Tabela de Medidas: img/2024/07/produto/2951/tabela-de-medidas-atualizada-2024.jpg Acompanha o produto: • 1 par de tênis 1 caixa de papelão Garantia: • Garantia de Fábrica', 129.9, 115.9, NULL, 'Baby & Kids Fashion > Others', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m04tko1gyv6x9e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F386057181%2F22993208272', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
