INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44557720423', 'Saída Maternidade em Tricot Luxury - Azul Serenity com Tranças Yuri', 'Tamanho P. Ideal para bebê 0 a 3 meses. Jogo com 3 peças Composição das Peças Macacão Longo: Design: Possui um trabalho rico em tranças (cable knit) no peitoral e nas pernas, além de detalhes em relevo horizontal. Gola: Gola polo na cor branca, com bordados geométricos delicados (losangos) em azul. Punhos: Acabamento em branco, criando um contraste elegante. Praticidade: Abertura frontal e entrepernas com botões brancos, facilitando a troca. Pés: Modelo com pé fechado integrado (estilo "pezinho"). Manta: Confeccionada no mesmo tom de azul do macacão, apresenta um barrado trabalhado com acabamento em ondas (vandyke) e uma trama pontilhada que confere textura à peça. Touca: Touca em tricô, garantindo um ajuste confortável e mantendo a temperatura da cabeça do bebê.', 169.9, 154.9, NULL, 'Baby & Kids Fashion > Baby Clothes > Bodysuits & Jumpsuits', 'https://cf.shopee.com.br/file/br-11134207-820l8-mm8ts9k8sy6c2d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F432637056%2F44557720423', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
