INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23494655478', 'Jogo de Velas Ignição Astra Cobalt Spin PI0067 BPR6EY Peça Nova', 'LOJA OFICIAL NOVA CHEVROLET GM NOVA CHEVROLET, QUALIDADE E CONFIANÇA AO SEU ALCANCE! Especificação Técnica: Garantia: 3 Meses Marca: Peça Nova Código de Referência: PI0067 Valor: Unitário Produto Novo Descrição Técnica: A principal função da vela de ignição é conduzir a corrente elétrica gerada no transformador até a câmara de combustão, transformando-a em centelha elétrica de alta tensão, responsável pela correta queima da mistura ar/combustível. As velas de ignição Peça Nova são fabricadas com materiais de alta qualidade e tecnologia R.P.C., garantindo desempenho e durabilidade. A vida útil depende diretamente da correta manutenção do motor e da qualidade do combustível utilizado. Aplicação do Produto: 1 Jogo Vela de Ignição Peça Nova – Compatível com veículos Chevrolet, Volkswagen, Fiat e Ford. Aplicações: CHEVROLET • Astra 2.0 – 2004 a 2008 • Blazer 2.4 – 2001 a 2011 • Celta 1.0 / 1.4 – 2000 a 2005 • Corsa 1.0 / 1.4 / 1.6 – 2003 a 2005 • Omega 4.1 – 1997 a 2000 • S10 2.4 (Gasolina) – 2000 a 2004 • Silverado 4.1 – 1997 a 2007 • Vectra 2.0 8V – 2005 a 2008 • Zafira 2.0 8V – 2001 a 2008 • Cobalt 1.8 – 2012 a 2016 • Spin 1.8 – 2012 a 2016 • Meriva 1.8 – 2002 a 2012 • Montana 1.8 – 2004 a 2010 VOLKSWAGEN • Logus 1.6 / 1.8 / 2.0 AP – 1995 a 1996 • Quantum 1.8 / 2.0 AP – 1991 a 1996 • Santana 1.6 / 1.8 / 2.0 AP – 1991 a 1996 • Saveiro 1.6 / 1.8 / 2.0 AP – 1991 a 1996 • Parati 1.6 / 1.8 / 2.0 AP/AE – 1982 a 1995 • Kombi 1.4 / 1.6 – 1992 a 1997 • Fusca 1.6 – 1993 a 1996 • Gol 1.6 / 1.8 / 2.0 AP – 1987 a 1996 FIAT 1.8 • Doblò – 2003 a 2006 • Idea – 2006 a 2014 • Palio – 2004 a 2010 • Punto – 2007 a 2010 • Siena – 2004 a 2010 FORD • Escort – 1993 a 1996 Similares / Referência Cruzada: GM – 93206675 NGK – BPR6EY BOSCH – F000KE0P43 DELPHI – XH40003 ACDelco – CR43CXLS CHAMPION – RN9YC DENSO – W20EXR-U Especificações Técnicas: • Aplicação: Álcool / Gasolina / Bicombustível • Rosca: Longa • Diâmetro da Rosca: 14 mm • Medida do Hexágono: 20,8 mm • Grau Térmico: 6 • Comprimento da Rosca: 19 mm • Construção: Resistiva • Folga do Eletrodo: Convencional • Característica Principal: Eletrodo Central com Corte em V Conteúdo da Embalagem: 4 Velas de Ignição Peça Nova Códigos Relacionados: PI0108, PI0109 Importante: A Garantia da Nova Chevrolet não cobre má instalação ou mau uso do produto.', 38.41, 38.41, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Ignition', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mgnstc5d9blw92', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F422105437%2F23494655478', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
