INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23697465386', 'Tampa Do Filtro De Ar Condicionado Logan Adptação CES2198 todos os modelos até 2010', 'tampa do FILTRO DE AR CONDICIONADO LOGAN NESTE KIT VÃO OS 3 PARAFUSOS E O FILTRO COM a tampa colada no filtro Qual a importância de trocar o filtro de ar condicionado? A necessidade de trocar o filtro não só existe como é de extrema importância. Afinal, o ar que você respira dentro do carro passa por ali e, quanto mais sujo ou velho ele estiver, pior será a qualidade do ar no interior do carro. O filtro tem a função de reter poeira, fuligem e eliminar qualquer tipo de impureza do ar.', 39.99, 39.99, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lujoxoliokus6f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1021060335%2F23697465386', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
