INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19997413452', 'BRUSCHETTA LA PASTINA ALCACHOFRA E PIMENTÃO 280G', 'Você está comprando: BRUSCHETTA LA PASTINA ALCACHOFRA E PIMENTÃO 280GSOBRE O PRODUTO: Conhecidas pelo sabor, versatilidade e praticidade, as bruschettas são uma ótima pedida para incrementar qualquer momento a mesa, desde um lanchinho até um banquete. A combinação da acidez da alcachofra com a doçura do pimentão resulta em um produto de sabor bem equilibrado. É uma ótima opção para servir como aperitivo junto de pão italiano ou crostini, acompanhando carnes magras ou utilizando no preparo de risotos, massas e molhos. LA PASTINA, ALIMENTAMOS SUA PAIXÃO Uma seleção de produtos premium unindo qualidade, praticidade e confiabilidade. É reconhecida pelos mais renomados chefs e apreciadores da alta gastronomia. Pioneira em diversas categorias, a La Pastina vive em constante busca por produtos diferenciados, saudáveis e saborosos, oferecendo ao consumidor sofisticação e facilitando a vida daqueles que buscam trazer ao seu dia a dia uma incrível experiência gourmet à mesa. Acreditamos no poder transformador do alimento e nossa filosofia está baseada na cultura da enogastronomia Mediterrânea. Trazer mais sabor à vida das pessoas é a nossa verdadeira paixão.', 59.23, 59.23, NULL, 'Food & Beverages > Food Staples > Preserved Vegetables', 'https://cf.shopee.com.br/file/sg-11134201-7rbm0-lm8v8bu10nyyd9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F844012318%2F19997413452', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
