INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23699168957', 'Kit 4 Drivers Bomber DBP01 100W RMS 8 Ohms Para Projetos Automotivos Potentes Som de Qualidade Plus', 'Seja bem-vindo a Eletroking, leia atentamente a descrição do produto abaixo antes da compra, qualquer dúvida, nos acione no campo de perguntas do anúncio. Kit 4 Drivers Bomber DBP-01 100 Watts Rms - 8 Ohms É uma excelente escolha para quem busca qualidade sonora e potência para o sistema de áudio. Com 100 Watts RMS e 8 Ohms de impedância, este driver é capaz de entregar um som claro e potente, ideal para projetos de médio e grande porte. Seu design robusto e a qualidade dos materiais garantem durabilidade e um desempenho confiável. Especificações Técnicas: • Marca: Bomber • Modelo: DBP-01 • Composição/Material: Plástico • Potencia: 100 Watts Rms • Impedância: 8 Ohms • Resposta de Frequência: 3500Hz a 20000Hz • Medidas: 5,2 x 5,2 x 7,2cm Conteúdo da Embalagem: • 04 Driver Bomber DBP - 01 100 Watts Rms Importante: • Garantia de 90 Dias. • Valor do Kit. • Todos os Nossos Produtos São Novos, Originais e Acompanham Nota Fiscal. • A Eletroking recomenda que a instalação seja feita por profissional especializado e não se responsabiliza pelo mau uso do produto.', 115.0, 108.1, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/sg-11134201-821cx-mh9kfzyxn9c89a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F463375702%2F23699168957', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
