INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14063059902', 'bomba de ar manual tramontina 160psi 11 bar encher pneu bike bicicleta carro moto', 'Quem gosta de estar preparado para várias situações em casa pode contar agora com um item muito prático e útil no dia a dia. A Bomba de Ar Manual Tramontina 160 psi 11 bar. Ideal para trabalhos domésticos de inflar boias, bolas e pneus de bicicleta é leve e portátil podendo ser facilmente transportada e ainda tem ponteiras adaptadoras. Sua mangueira tem 60 cm com válvula especial, o corpo é feito em aço especial pintado e tem cabo e detalhes injetados. O produto perfeito para você ter na sua garagem, com comprimento máximo de bombeamento de 60 cm e diâmetro do tubo de 3,2 cm. Garanta agora mesmo a praticidade e a qualidade para todas as sua atividades. Garanta já a sua! Especificações Técnicas: • Corpo em Aço Especial Pintado • Cabo e Detalhes Injetados • Mangueira de 60 cm com Válvula Especial • Pressão Máxima: 160 Psi / 11 Bar • Comprimento Máximo de Bombeamento: 600 mm • Diâmetro do Tubo: 32 mm • Leve e Portátil podendo ser Facilmente Transportado • Ideal para Trabalhos Domésticos de Inflar Boias, Bolas e Pneus de Bicicleta • Possui Manômetro com duas Escalas de Pressão para Facilitar o Entendimento do Usuário • Possui Ponteiras Adaptadoras para Boias e Bolas para Facilmente Adaptar o Produto as mais Diversas Aplicações Conteúdo da Embalagem: • 01 Bomba de Ar Tramontina • 01 Ponteira Adaptadora para Inflar Bolas • 01 ponteira Adaptadora para Inflar Boias • 01 ponteira Adaptadora para Inflar Câmaras com Bico Tipo Presta (Fino) Acoplada Junto à Válvula de Fixação • Manual Certificado de Garantia Importante: • Garantia de 273 Dias.', 139.9, 131.51, NULL, 'Spare Parts and Accessories for Vehicles > Accessories for Motorcycles > Others', 'https://cf.shopee.com.br/file/sg-11134201-7qvf0-lh9jnahiyayidc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F463375702%2F14063059902', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22694420688', 'Descarbonizante Limpa Tbi Eletronica Koube Uso Em Tbi Sensores Atuador Marcha Lenta Carter Cabeçote', '🧽 DESCARBONIZANTE LIMPA TBI 300ML - KOUBE 🔧 Limpeza profunda e segura para TBI, sensores e coletores de admissão ⚡ Secagem rápida e ação hidro-repelente 📦 CONTEÚDO DA EMBALAGEM 1x Frasco de Descarbonizante Limpa TBI Koube 300ml 🔢 Código: 28234 // 20.002 🏷️ Marca: KOUBE Químicos 🛠️ ESPECIFICAÇÕES TÉCNICAS 📌 Tipo: Descarbonizante Limpa TBI 🆕 Condição: NOVO 👀 Aparência: Líquido límpido 🎨 Cor: Incolor ⚖️ Densidade: 0,800 – 0,900 ✅ APLICAÇÕES 🌀 Limpeza de TBI eletrônico, atuadores de marcha lenta, sensores e coletores de admissão 🧪 Dissolve gomas, vernizes e incrustações 🧯 Ideal para cárter e tampas de cabeçote antes da aplicação de junta líquida ❌ Não danifica potenciômetros, sensores, atuadores ou catalisadores 🧼 CARACTERÍSTICAS 💧 Hidro-repelente, seca rápido e sem resíduos 🧹 Remove impurezas e contaminações internas 🛡️ Seguro para os componentes eletrônicos do motor 📋 INSTRUÇÕES DE USO 🔄 Agite bem antes de usar 🎯 Aplique a uma distância de 5 a 10 cm ➕ Utilize o prolongador, bem encaixado 💨 Realize a limpeza com o motor em funcionamento (~2000 rpm) 🌬️ Use somente em áreas ventiladas ⚠️ Evite que o produto seja aspirado diretamente pelo motor ℹ️ INFORMAÇÕES ADICIONAIS 📦 Produto disponível para envio imediato 🧾 Novo, com nota fiscal e garantia de 90 dias 🖼️ Produto exatamente igual às imagens do anúncio 🔁 Devoluções apenas com embalagem original e nota fiscal 🚫 AVISO LEGAL ❌ Proibida cópia ou uso das imagens e conteúdos 📜 Protegido pela Lei de Direitos Autorais (Lei 9.610/98) 🛡️ GARANTIA 📅 Garantia: 90 dias 🔧 Instalação recomendada em oficinas especializadas ❗ Não cobrimos mão de obra ou mau uso 📞 SUPORTE E ATENDIMENTO 🕗 Segunda a Sexta: 08h às 18:30h 🕘 Sábado: 08h