INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23697017106', 'Cartão de Memória Sdhc Sandisk 32gb Cartão Sd 100Mbs c10 V3', 'Cartão de Memória Sdhc Sandisk 32gb Cartão Sd 100Mbs c10 V3 Sandisk Cartão de Memória Sdhc 32gb Cartão Sd Extreme Velocidade de Leitura de até 100Mbs Classificação de Velocidade de Vídeo V30 Classe Padrão c10 Interface de Barramento Uhs-I U3 / No Brasil Projetado para dispositivos SD que podem capturar vídeo Full HD e 4K, bem como fotografia raw e burst, o cartão de memória SDHC Sandisk Extreme é compatível com o barramento UHS-I; Apresenta uma classificação de classe de velocidade de V30, que garante velocidades mínimas de gravação de 30 MB/s. Se o seu dispositivo não suporta o padrão V30, este cartão também suporta o padrão U3, que também garante velocidades mínimas de gravação de 30 MB/s; As velocidades de leitura suportadas são de até 100MB/s e as velocidades de gravação atingem o máximo de 60MB/s. Uma chave de proteção contra gravação integrada ajuda a proteger seus dados contra o apagamento acidental; Marca: Sandisk Nome do modelo: Extreme Referência: SDSDXVT-032G-GNCIN Velocidade de Leitura Sequencial até 100Mbs Classificação de Velocidade de Vídeo V30 Interface de Barramento Uhs-I U3 Dimensões: 15 x 10 x 0,5 cm Peso: 0,016 Itens inclusos: 1x Cartão de Memória Sd 32gb Garantia: 90 dias', 294.58, 294.58, NULL, 'Mobile & Gadgets > Accessories > Memory Cards', 'https://cf.shopee.com.br/file/sg-11134201-7rblu-llxigavviatn60', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1078289679%2F23697017106', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18799253350', 'Tampo para Balcão 240cm Berlim Branco/Thasos', 'O Tampo para Balcão Berlim 240 é ideal para ser utilizado por quem não deseja usar pia, mas também não quer deixar o balcão destampado. Ele também pode ser utilizado como suporte, tampa e diversas outras funcionalidades se adequando a varias necessidades do cliente. O MDP de 15 mm utilizado em sua fabricação é um material de ótima qualidade, e vai se adequar a sua necessidade, adquira já o seu! Formato: Retangular Peso (kg): 22 Garantia: 03 Meses Acabamento: BP Melamínico Largura (cm): 240 Espessura (mm): 15 Suporta Até (kg): 25 Profundidade (cm): 54.2 Escala de Brilho: Fosco Origem do Produto: Nacional Material Principal: MDP Necessita Montagem: Sim Complexidade da Montagem: Baixa: pode ser montado por uma pessoa sozinha Possui Recorte para Cooktop: Não Marca: Caemmun Cor do Produto: Thasos Itens Inclusos: 1 Tampo Cor Predominante: Branco Quantidade de Gavetas: Não Possui', 421.68, 421.68, NULL, 'Home & Living > Furniture > Desks & Tables', 'https://cf.shopee.com.br/file/sg-11134201-825an-mr3b79fqhvk525', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F855489892%2F18799253350', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
