INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '29520204267', '[NEW] ISOI Blemish Care Eye & Wrinkle Patch 90P', 'Olho e Patch de rugas ISOI Blemish Care ISOI 90P Patch ocular diário de 3 minutos para o meio da testa para diminuir a idade da pele em 3,5 anos. Anexe 3 minutos todos os dias para diminuir a idade da pele por 3,5 anos em 4 semanas. 100% de satisfação na pele jovem, rosto de gotejamento melhorado, pele suave devido a rugas reduzidas e levantamento ocular. Ingredientes de destaque O Hidrogel Hidrogel que contém vitaminas que ajudam no clareamento e glutationa da pele, proporcionando uma pele brilhante e clara. O complexo de ácidos hialurônicos de tamanhos diferentes fornece camada de umidade para fornecer pele profundamente hidratada e firme. O óleo de rosa e pétala de rosa real para fornecer nutrientes ricos na pele búlgara, óleo de flor de rosa e pétala de rosa real para fornecer nutrientes ricos à pele. Modo de usar Após a limpeza, limpe o tom da pele e, em seguida, use a pinça para tirar remendos e prender nas áreas de preocupação, incluindo a área dos olhos e o meio da testa. Retire o remendo após 20 a 30 minutos e, em seguida, dê leves batidinhas na essência restante na pele para absorção.', 168.94, 168.94, NULL, 'Beauty > Skincare > Eye Treatment', 'https://cf.shopee.com.br/file/sg-11134207-7rfh7-m3ljev666zz144', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F920292999%2F29520204267', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259720066', 'Lagunitas IPA Cerveja Long Neck', 'A Lagunitas IPA é uma cerveja American Indian Pale Ale (IPA) que nasceu em 1995 na Califórnia. Uma versão única de um estilo antigo, preservando o aroma e amargor dos lúpulos cítricos e florais americanos. Perfeita para harmonizar com hambúrguer, carnes gordurosas, churrasco, comida mexicana, queijo roquefort, gorgonzola e gouda. Além de saborosa, a Lagunitas apoia ONGs que cuidam de cachorros de rua e músicos independentes.', 12.99, 12.99, NULL, 'Food & Beverages > Alcoholic Beverages > Beer & Cider', 'https://cf.shopee.com.br/file/sg-11134201-825zo-mj72osdxpkaqee', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554900%2F58259720066', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
