INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23594232174', 'Boneco Funko Pop! Super Quarteto Fantástico - Galactus', 'O devorador de mundos chegou! O Boneco Funko Pop! Super Galactus é a peça imponente que faltava na sua coleção. Parte da linha Marvel Studios: Quarteto Fantástico – Primeiros Passos, essa figura de vinil com cabeça oscilante mede aproximadamente 17 centímetros de altura e traz todo o poder do icônico vilão cósmico da Marvel. Com detalhes impressionantes, é ideal para fãs do universo Marvel que buscam um colecionável de destaque e cheio de personalidade!', 439.99, 439.99, NULL, 'Hobbies & Collections > Collectible Items > Action Figurines', 'https://cf.shopee.com.br/file/sg-11134201-7rdxg-mc9ke5mw9u7rd7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1289869635%2F23594232174', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
