INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20199606815', 'Guarda Roupas Casal Ripado com Espelho 2 Portas de Correr 4 Gavetas Trianon Branco Zanzini', 'O Guarda Roupas Trianon foi desenvolvido para quem busca sofisticação, praticidade e melhor aproveitamento do espaço. Possui duas portas de correr, sendo uma delas com amplo espelho, proporcionando um visual moderno e elegante. Seu interior é bem distribuído e conta com quatro gavetas com corrediças telescópicas, garantindo abertura suave e maior conforto no uso diário. As duas primeiras gavetas possuem divisões internas, ideais para manter seus itens pessoais sempre organizados. Além disso, conta com puxadores em MDF, proporcionando um toque moderno e maior durabilidade. Aposte na combinação perfeita entre elegância e eficiência e transforme seu ambiente! MEDIDAS: A = 220 cm L = 220 cm P = 52,8 cm MEDIDAS DO ESPELHO (cada um): A = 93,2 cm L = 42,5 cm P = 0,3 cm PESO: 157,6 kg PESO SUPORTADO: 44 kg GAVETAS SUPORTAM ATÉ: 3 kg PRATELEIRAS SUPORTAM ATÉ: 4 kg CABIDEIROS SUPORTAM ATÉ: 5 kg MODELO: Guarda Roupas Casal com Espelho 2 Portas de Correr 4 Gavetas Trianon MARCA: Zanzini TIPO DE PINTURA: Semi Fosco ACABAMENTO: UV Verniz MATERIAL: MDP ESPESSURA DO MATERIAL: 12mm PORTAS: 2 (Portas de correr) GAVETAS: 4 PRATELEIRAS: 2 QUANTIDADE DE CABIDEIROS: 3 CABIDEIROS: Metálicos CORREDIÇAS: Telescópicas PUXADORES: MDF QUANTIDADE DE PUXADORES: 2 ESPELHO: Sim (2 Lâminas) GARANTIA: 3 Meses DIFERENCIAL: Portas de correr / Puxadores em MDF / Corrediças telescópicas que proporcionam deslize suave / Amplo espelho SISTEMA DE MONTAGEM: Parafusos auto atarraxantes, cola, cavilhas, pregos Importante sobre a entrega: A entrega é realizada até a portaria ou porta de entrada do endereço indicado, desde que o acesso seja permitido. Para locais com portaria, a entrega será feita no piso térreo. Não realizamos montagem, desmontagem, transporte por escadas ou içamento. É responsabilidade do cliente verificar se as dimensões do produto são compatíveis com portas, elevadores e corredores. Evite imprevistos: confira todos os detalhes antes de concluir sua compra.', 2110.0, 1849.0, NULL, 'Home & Living > Furniture > Wardrobes', 'https://cf.shopee.com.br/file/sg-11134201-825zm-mjzj2gnc8s1t84', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1097902002%2F20199606815', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18997798533', 'Relógio Technos Masculino Executive Dourado - 2115TWZ/1K', 'A linha Executive apresenta seu seu novo modelo, com uma caixa inédita de design moderno e coroa diferenciada. Seu mostrador conta com a elegante numeração romana, mostrador texturizado de fácil leitura e calendário na posição de 6h. Produto 100% em aço inoxidável, com máquina quartz japonesa Miyota, resistência à água de 50 metros. Versão com pulseira de aço em 9 links ou pulseira de couro legítimo.', 570.0, 456.0, NULL, 'Watches > Men Watches', 'https://cf.shopee.com.br/file/sg-11134201-824j5-mpmjvnoxui2o5a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1332527814%2F18997798533', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
