INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14615933602', 'Amortecedor Traseiro Peugeot 207 2009 A 2015 Nakata', 'IDEAL AUTO PECAS - Desde 1992 - IDEAL PARA SEU CARRO! Amortecedor Traseiro (Par) - Original Nakata APLICACAO: PEUGEOT 207 HATCH DE 2009 A 2015 PEUGEOT 207 PASSION DE 2009 A 2015 PEUGEOT 207 SW DE 2009 A 2012 DESCRICAO DO PRODUTO O amortecedor e um componente basico para o funcionamento do sistema de suspensao. Os primeiros sinais de desgaste sao a falta de estabilidade e ruidos, sendo que essa deterioracao depende principalmente das condicoes do solo onde o veiculo circula. Portanto, em estradas pavimentadas de forma adequada eles duram mais e em solos com grandes diferencas de niveis eles duram menos, exigindo uma vitoria mais frequente.', 431.9, 431.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Suspension and Steering', 'https://cf.shopee.com.br/file/af945e6680b8d4fde798073d9bb08a8f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F616290090%2F14615933602', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
