INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58203777047', 'Rolamento Dianteiro Chevrolet Corsa Montana Meriva - IR18775', 'Especificações Técnicas: • Marca: IRB Automotive • Cód. da montadora: 93362342 • Posição: Roda Dianteira • Integração com ABS: Sim (Pode ser usado em veículos sem ABS também) • Tipo de rolamento: Duplo Medidas: • Diâmetro Interno: 34 mm • Diâmetro Externo: 67 mm • Espessura: 37 mm Aplicações: - Chevrolet Meriva 1.8 8/16V lançados a partir de 2003 - s/ ABS - Chevrolet Meriva 1.4 8V lançados a partir de 2008 - s/ ABS - Chevrolet Corsa 1.0/1.4/1.8 8V lançados a partir de 2002 - Chevrolet Novo Corsa lançados a partir de 2002 - Chevrolet Montana 1.8 8V lançados a partir de 2004 - Chevrolet Montana 1.4 8V lançados a partir de 2008 Os Rolamentos IRB são fabricados com aço GCR15, que é conhecido por sua excelente dureza, o que o torna capaz de suportar cargas pesadas e resistir ao desgaste, mesmo em condições de operação severas. Apesar de sua dureza, o aço GCR15 favorece uma boa tenacidade, o que significa que pode absorver impactos e choques sem quebrar facilmente, prolongando vida útil do rolamento. IRB é uma marca que fornece peças automotivas voltada ao segmento de reposição para todo Brasil. Atendendo frotas de veículos nacionais e importados! Não esqueça de verificar ano e modelo do veículo! Na dúvida, verifique a compatibilidade pelo código da peça do seu veículo ou mande mensagem para verificarmos a aplicação do produto para você. Evite erros na compra!', 54.9, 49.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Suspension and Steering', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mjre2cfqrthef4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1497249598%2F58203777047', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
