INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58255272534', 'BUCHA DESLIZANTE BENGALA PAR XJ6 N 09 A 15', 'PAR DE BUCHAS DESLIZANTE DE BENGALA Compatibilidade: YAMAHA XJ6 N de 2009 até 2015 Alta qualidade: bucha deslizante de bengala ORIGINAL Parts produzida com revestimento em PTFE (teflon), garantindo deslizamento preciso para o melhor desempenho da suspensão. Produto novo, à pronta entrega, com garantia, compatível exclusivamente para os anos descritos abaixo. YAMAHA XJ6 N 2009 YAMAHA XJ6 N 2010 YAMAHA XJ6 N 2011 YAMAHA XJ6 N 2012 YAMAHA XJ6 N 2013 YAMAHA XJ6 N 2014 YAMAHA XJ6 N 2015 Este produto refere-se a: 2 (duas) unidades de bucha deslizante da bengala com PTFE (teflon) externo, marca ORIGINAL Parts SKU: SBK-1547 MEDIDAS NOMINAIS: Medida nominal da bucha deslizante: 40 * 42 * 20 Marca da suspensão OEM na montadora: KAYABA Tipo de suspensão: Telescópica convencional O QUE É? A bucha deslizante da bengala é responsável por permitir o movimento suave do tubo interno dentro da suspensão dianteira, reduzindo o atrito e garantindo estabilidade e conforto durante a pilotagem. SERVE EM OUTRA MOTO? Não. Mesmo que outras motos tenham peças parecidas, as medidas podem ser diferentes. Este produto é exclusivo para o modelo de moto e anos indicados acima. Se tiver dúvidas, entre em contato com nosso suporte técnico antes da compra. Consulte também a política de trocas e devoluções. MEDIDAS CONFIÁVEIS As medidas seguem rigorosamente o padrão original da moto e são 100% calibradas. Você pode confiar na precisão técnica das nossas buchas deslizantes. GARANTIA Este item tem 90 dias de garantia contra defeitos de fabricação. Fatores externos como mau manuseio ou montagem sem ferramentas adequadas, que possam danificar o produto, não são cobertos pela garantia, configurando mau uso. RECOMENDAÇÃO IMPORTANTE Ao substituir este item, verifique também os demais componentes da suspensão da sua moto. Consulte nossa linha ORIGINAL Parts TECHCILINDROS para um reparo completo e seguro. SOBRE A MARCA A TECHCILINDROS atua desde 2008, oferecendo qualidade e variedade em tubos de bengala para motos de média e alta cilindrada, atendendo mais de 90% do mercado nacional. Em 2018, lançou a marca ORIGINAL Parts, com componentes premium de vedação e suspensão, garantindo mais segurança e durabilidade.', 83.09, 83.09, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Chassis', 'https://cf.shopee.com.br/file/sg-11134201-8262m-mkqygfojrq4md8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1609848355%2F58255272534', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58206191427', 'RETENTOR BENGALA PAR CB 500 F 13 A 18', 'PAR DE RETENTORES DE BENGALA Compatibilidade: HONDA CB 500 F de 2013 até 2018 Alta qualidade, vedação precisa e maior durabilidade: retentor de bengala ORIGINAL Parts é produzido em NBR de alto desempenho, desenvolvido para resistir a atrito, calor e contato com o fluido da suspensão. Produto novo, à pronta entrega, com garantia, compatível exclusivamente para os anos descritos abaixo. HONDA CB 500 F 2013 HONDA CB 500 F 2014 HONDA CB 500 F 2015 HONDA CB 500 F 2016 HONDA CB 500 F 2017 HONDA CB 500 F 2018 Este produto refere-se a: 2 (duas) unidades de retentor de bengala com mola dupla, marca ORIGINAL Parts SKU: RTK-1458 MEDIDAS NOMINAIS: Medida nominal do retentor: DCY-B 41 * 54 * 11 (Mola Dupla) Marca da suspensão OEM na montadora: SHOWA Tipo de suspensão: Telescópica convencional O QUE É? O retentor de bengala é responsável por evitar o vazamento do fluido interno da suspensão dianteira, garantindo o funcionamento correto, a vedação precisa e a durabilidade do sistema. SERVE EM OUTRA MOTO? Não. Mesmo que outras motos tenham peças parecidas, as medidas podem ser diferentes. Este produto é exclusivo para o modelo de moto e anos indicados acima. Se tiver dúvidas, entre em contato com nosso suporte técnico antes da compra. Consulte também a política de trocas e devoluções. MEDIDAS CONFIÁVEIS As medidas seguem rigorosamente o padrão original da moto e são 100% calibradas. Você pode confiar na precisão técnica dos nossos retentores. GARANTIA Este item tem 90 dias de garantia contra defeitos de fabricação. Fatores externos como mau manuseio ou montagem sem ferramentas adequadas, que possam danificar o produto, não são cobertos pela garantia, configurando mau uso. RECOMENDAÇÃO IMPORTANTE Ao substituir este item, verifique também os demais componentes da suspensão da sua moto. Consulte nossa linha ORIGINAL Parts TECHCILINDROS para um reparo completo e seguro. SOBRE A MARCA A TECHCILINDROS atua desde 2008, oferecendo qualidade e variedade em tubos de bengala para motos de média e alta cilindrada, atendendo mais de 90% do mercado nacional. Em 2018, lançou a marca ORIGINAL Parts, com componentes premium de vedação e suspensão, garantindo mais segurança e durabilidade.', 32.33, 32.33, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Chassis', 'https://cf.shopee.com.br/file/sg-11134201-8260k-mle14zrk6z9k8e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1609848355%2F58206191427', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
