INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23897595371', 'SOCORRO, CAÍ DENTRO DO VIDEOGAME', 'SOCORRO, CAÍ DENTRO DO VIDEOGAME Uma série de sucesso internacional que fará com que fãs de videogames implorem sempre por mais um volumeSer sugado para um videogame não é tão divertido quanto você pensa. Jesse e seu melhor amigo vão parar dentro do jogo mais irado do momento. Claro, há coisas legais como mochilas a jato, tanques de guerra e vidas infinitas, mas o que acontece quando o jogo começa a se virar contra você?Com perseguições, aventuras e muito humor, os amigos vão enfrentar grandes desafios até conseguirem sair das telas e retornar ao mundo real.. Informações Adicionais Autor: BRADY, DUSTIN Data Publicação: 30/12/1899 Tipo de capa: BROCHURA Condição do Item: Novo Subtitulo: SOCORRO, CAÍ DENTRO DO VIDEOGAME Idioma: INDEFINIDO Páginas: 112 Edição: 1 ISBN-13: 9786559570560 ISBN-10: 6559570568', 23.92, 23.68, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7rd49-luh35fq4t0e5e5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F826663787%2F23897595371', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18699852954', 'SERIAL KILLERS', 'SERIAL KILLERS Qual é a linha tênue entre um pensamento perturbador e a ação? Jeffrey Dahmer, Ted Bundy, o Maníaco do Parque... é extensa a lista de nomes de assassinos em série que ganharam notoriedade na mídia nas últimas décadas. Cada caso tem sua particularidade: a escolha das vítimas, as armas utilizadas, a cena do crime e, principalmente, a motivação. Buscar as raízes dos comportamentos e dos transtornos de personalidade desses possíveis indivíduos é o ponto chave dessa discussão para entender o que os move a cometer esses crimes O que você vai encontrar aqui: • Como funciona a mente de um serial killer; • Principais aspectos e características; • Teorias existentes para explicar o comportamento; • O fascínio e a repulsa que causam na sociedade; • Mitos e verdades sobre o tema.', 32.9, 32.9, NULL, 'Books & Magazines > Books > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rdyc-mc6ih7cv1mxaa6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F826663787%2F18699852954', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259721086', 'Refrigerante de cola Pepsi Twist', 'Experimente a combinação perfeita de cola e limão com Pepsi Twist, um refrigerante único e refrescante! Lançada no Brasil em 2002, Pepsi Twist é a escolha ideal para quem busca um sabor diferenciado e marcante. Refrescante e saborosa, perfeita para qualquer momento do dia.', 1.79, 1.79, NULL, 'Food & Beverages > Beverages > Carbonated Drinks & Tonics', 'https://cf.shopee.com.br/file/sg-11134201-8258c-mqnekhpb9vrf73', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554900%2F58259721086', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
