INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '11020371692', 'Pincel marca texto Grifpen com 6 unidades Tons Pastéis MT/TP6ZF\357003 Faber-Castell', 'INMETRO 003661/2012 O Marca Texto Grifpen da Faber-Castell possui a ponta chanfrada, que possibilita traços finos e grossos a depender da posição que a ponta é colocada no papel. Seu formato triangular garante maior conforto ao escrever e as cores são super fofas em Tons Pastel. Ah, a tinta não passa para o outro lado da folha viu? Detalhes: - Tinta redistente á luz. - Tinta e componentes plásticos atóxicos. - Tampe após o uso. - Evite temperaturas acima de 45°C e exposição direta aos raios solar.', 40.74, 34.9, NULL, 'Stationery > Writing & Correction > Highlighters', 'https://cf.shopee.com.br/file/sg-11134201-82592-mqyqtncahde4ec', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F479054821%2F11020371692', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
