INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23994055236', 'Refrigerador Esmaltec 306 Litros Branco RCD38 – 127 Volts', 'Refrigerador Esmaltec 306 Litros Branco RCD38 – 127 Volts O Refrigerador Esmaltec 306 Litros Branco RCD38 combina design, praticidade e eficiência. Com duas portas que facilitam a distribuição interna, é ideal para ambientes com menos espaço, oferecendo excelente aproveitamento interno. O congelador possui capacidade de 69 litros e opera a uma temperatura de até -18°C. O sistema de refrigeração é Cycle Defrost, e o produto está disponível nas voltagens 127V e 220V, além de contar com classificação A em eficiência energética, garantindo maior economia. Desenvolvido com o mais alto padrão de qualidade conforme normas ABNTNBR, a Esmaltec é certificada pela norma ISO 9001. O refrigerador apresenta pés elevados que conferem imponência ao design, prateleiras internas removíveis que facilitam a limpeza e oferecem mais espaço, além de acessórios como porta-ovos, forma de gelo e separador de garrafas. Este é o produto ideal para sua casa, unindo funcionalidade e sofisticação. Imagens meramente ilustrativas', 2721.0, 2721.0, NULL, 'Home Appliances > Kitchen Appliances > Refrigerators', 'https://cf.shopee.com.br/file/sg-11134201-8258l-mqz2cv42k1s60b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1323031590%2F23994055236', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
