INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20797725975', 'Chinelo de Quarto One Piece', 'Depois de um dia cheio de aventuras e de brincadeiras, bateu aquela dorzinha no pé? A gente te ajuda! Com esse chinelo suas noites de descanso serão mais divertidas e confortáveis, fofinho e quentinho, é a companhia perfeita para os pós de um dia agitado! Não importa qual é a aventura, esse chinelo te acompanha em todos os lugares! A pantufa é importada e é uma excelente companhia para os dias de home office! Mas não para por ai, em dias gelados em casos de extrema preguiça e previsão de cama e série para o dia todo, essas pantufas te acompanham em todos os seus episódios favoritos! Além de quentinha, é muito confortável e possui sola emborrachada! Comprimento X Largura X Altura: Tamanho P: 24x10x10cm. Tamanho M: 26x10x10cm. Tamanho G: 28x10x10cm. Tamanho GG: 30x10x10cm. Adulto ou Criança - Unissex Tamanho P: Calça 33 - 35 Tamanho M: Calça 36 - 38 Tamanho G: Calça 39 - 41 Tamanho GG: Calça 42 - 44 Peso: 0,150g Cuidados e recomendações de uso: Lavar a mão com água fria. Não usar alvejante. Secar na horizontal. Secagem natural. Não passar e limpar a seco.', 124.9, 124.9, NULL, 'Men Shoes > Sandals & Flip Flops > Flip Flops', 'https://cf.shopee.com.br/file/sg-11134201-822wg-moeljh0eu2v4b5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F404743073%2F20797725975', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23399436815', 'Cachaça Cristalina Sagatiba', 'Sagatiba é a busca pela reinvenção da cachaça e do Brasil. A Cristalina é multidestilada em coluna de aço, o que garante uma bebida livre de impurezas e de alta qualidade. Ideal para a preparação de caipirinhas e outros drinks.', 36.49, 36.49, NULL, 'Food & Beverages > Alcoholic Beverages > Liquor & Spirits', 'https://cf.shopee.com.br/file/sg-11134201-825bc-mqnelyvzqdxfcd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1703290516%2F23399436815', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22998483134', 'Micro-ondas Electrolux 23L Branco Efficient com Descongelamento Assistido (ME23B)', 'O Micro-ondas Electrolux Branco 23L Efficient (ME23B) é pensado para facilitar sua rotina na cozinha. Com ele, você economiza tempo no preparo de suas receitas graças a sua potência de 1100W, e garante maior eficiência no consumo diário de energia por sua Classificação energética A. O ME23B conta com a tecnologia de Descongelamento Assistido da Electrolux para alcançar resultados mais uniformes ao descongelar os ingredientes, avisando no painel o momento certo de virar ou mexer os alimentos. Seu painel inteligente, com ajustes automáticos de potência, disponibiliza quatro modos de preparo diferentes e funcionais para tornar sua rotina mais prática: derreter; desidratar; cozinhar rápido e cozinhar delicado. Acione a Função Desidratar para fazer chips de frutas ou vegetais, além de desidratar ervas para conservá-las por mais tempo. Selecione a Função Cozinhar Delicado se quiser preparar alimentos macios, como peixes e alguns tipos de vegetais. Para vegetais mais duros e carne bovina, utilize a Função Cozinhar Rápido. O Micro-ondas Electrolux possui a função Manter Aquecido, que conserva suas receitas recém preparadas quentes e deliciosas até o consumo. A função Tira Odor é ideal para manter seu produto livre de possíveis odores dos preparos anteriores graças ao sistema de recirculação do ar interno.', 659.0, 529.0, NULL, 'Home Appliances > Kitchen Appliances > Microwaves', 'https://cf.shopee.com.br/file/sg-11134201-81zth-mmx27omfft3a5b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1526836548%2F22998483134', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43558483079', 'Carcaça do Farol Fan 125 Titan 2000 Preto CF-02 - Pro Tork', 'Características:- Marca: Pro Tork- Modelo: CF-02Especificações:- Item para reposição;- Matéria-prima de alta qualidade.- Cor: PretoMotos Compatíveis:- Fan 125- Titan 2000Dimensões e peso:- Dimensões: 20 x 20 x 15 cm- Peso: 400gConteúdo da Embalagem:- 1 Carcaça do farol', 22.0, 19.27, NULL, 'Spare Parts and Accessories for Vehicles > Accessories for Motorcycles > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rdxx-mc6hxpm9yblla5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F356143297%2F43558483079', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41467370037', 'Caixa Térmica 22 Litros Vermelha Soprano Camping Praia', 'Caixa Térmica 22 Litros Vermelho Tropical Soprano 09000.5022.17 Conheça a nova Caixa Térmica Tropical de 22 litros! Compacta e alongada, essa caixa é ideal para transportar garrafas de 2 litros em pé, oferecendo praticidade e conveniência para o seu dia a dia. Perfeita para quem busca leveza e eficiência, sua estrutura facilita o manuseio até para pessoas com menor força. Complemente sua experiência com a qualidade e inovação que só a linha Tropical proporciona. Ideal para piqueniques, viagens, momentos ao ar livre e para estar sempre ao seu lado. Organize as suas garrafas de pé: mais facilidade para o seu dia a dia! Eficiência térmica de até 18 horas (com 20% de gelo) Tampa serve como bandeja Pegas laterais Por ser mais alta e menos larga, se encaixa melhor em pequenos espaços e permite o transporte de forma mais fácil. Tampa com trava e alça retrátil Capacidade de 31 latinhas de 350ml ou 4 garrafas de 2l, de pé. Principais características: Organização eficiente: Transporte garrafas de pé com facilidade no dia a dia. Eficiência térmica: Mantém a temperatura por até 18 horas (considerando 20% da capacidade com gelo). Capacidade: 22 litros. Tampa multifuncional: Serve como bandeja. Praticidade: Pegas laterais, tampa com trava e alça retrátil. Otimização de espaço: Mais alta e menos larga, encaixa melhor em pequenos espaços e facilita o transporte. BPA Free Isolamento térmico de EPS. Capacidade (sem gelo): Latas de 350 ml: 31 unidades ou Latas de 473 ml: 24 unidades ou Garrafas de 600 ml: 23 unidades ou Garrafas de 1 litro: 6 unidades ou Garrafas de 2 litros: 4 unidades. Outras Características: Dimensões: 37,2 x 30,8 x 38,8 cm Peso: 1,965 kg Garantia do fabricante: 3 meses', 79.9, 67.2, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Camping & Hiking', 'https://cf.shopee.com.br/file/sg-11134201-824hq-me7k6oh4evphce', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F844004880%2F41467370037', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14682012775', 'Biscoito Magnus Original para Cães 1kg', 'Especificações Idade Adulto Pet Cachorros Porte de Raça Médio, Grande e Pequeno Quantidade 400g Apresentação Disponível em embalagens com 400 g e 1kg Composição Farinha de trigo . harina de trigo . wheat flour, milho integral moído . maíz integral molido . ground whole corn, farelo de trigo, salvado de trigo. wheat bran, farinha de vísceras de frango . harina de vísceras de pollo . poultry meal, gordura vegetal . grasa vegetal . vegetable fat, glúten de trigo . wheat gluten, açúcar . azúcar . sugar, cloreto de sódio . cloruro de sodio . sodium chloride, palatabilizante . palatante . palatability enhancer, vitamina . vitamins (A, D3, E, K3, C, B1, B2, B12, biotina, pantotenato de cálcio, niacina, cloreto de colina), minerais . minerales . minerals (sulfato de ferro, sulfato de cobre, iodato de cálcio, óxido de zinco, óxido de manganês, selenito de sódio), ácido propiônico . propionic acid, BHA, BHT.', 32.9, 32.9, NULL, 'Pets > Pet Food > Dog Treats', 'https://cf.shopee.com.br/file/br-11134207-7r98o-ll51fpst95j09f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F398944029%2F14682012775', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23597589471', 'Brinquedo Blocos de Montar Mundo Encantado - Buque De Flores Surpresa 1 Peça - Xalingo 28498', '*O modelo adquirido, será surpresa. Cada produto é vendido separadamente. O valor do produto refere-se a apenas um modelo. As crianças poderão adquirir diferentes Blocos para Montar da linha Flores da Xalingo! É uma surpresa diferente em cada embalagem! São 6 modelos diferentes de flores coloridas, para misturar e criar. As peças são muito resistentes, leves e fáceis de montar. E no final, com a junção de todas as flores, se forma um lindo buquê! A quantidade de peças varia conforme o modelo, sendo de 20 a 29 peças. O brinquedo motiva a criança passar o tempo através do aprender brincando, pois desenvolve a coordenação motora e habilidades de diferenciação das partes e do todo. Garanta já e dê o melhor presente para a brincadeira dos pequenos! Características: - Marca: Xalingo - Modelo: 28498 *Imagens Meramente Ilustrativas* Especificações do produto: Idade: Recomendado para crianças a partir dos 6 anos. Inmetro: 003497/2022 Dimensões Aproximadas (AxLxC): 31,5 x 7 x 23,5 cm Conteúdo da Embalagem: - 1x flor surpresa colecionável', 20.07, 18.07, NULL, 'Mom & Baby > Toys > Block Toys', 'https://cf.shopee.com.br/file/sg-11134201-7rd5u-lwmyw0ehtze133', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F356143297%2F23597589471', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40351156721', 'Antipulgas Banni para Cães 5,1kg até 10kg Ourofino 1 Pipeta', '- Indicado para cães; - Para cães filhotes, adultos e idosos; - Para tratamento de infestações por pulgas, carrapatos e helmintos gastrintestinais; - Composto entre fipronil e moxidectina; - Contém 1 flaconete de 0,67mL. Banni é um endectocida tópico para cães composto pela associação entre fipronil e moxidectina para tratamento de infestações por pulgas (Ctenocephalides felis felis), carrapatos (Rhipicephalus sanguineus) e por helmintos gastrintestinais como Ancylostoma spp., Toxocara spp. e Trichuris vulpis. Banni é indicado para cães filhotes, adultos e idosos. Sua fórmula combina três princípios ativos: Fipronil, Moxidectina e Praziquantel, proporcionando uma ação abrangente contra diversos parasitas. Modo de usar Administrar por via tópica. - Certifique-se de que o volume do flaconete é compatível com o peso do animal. - Antes da aplicação, observe se não há produto na saída do flaconete, batendo na parte superior. - Dobre a parte superior do flaconete no local indicado. - Com o animal em posição confortável, afaste os pelos na região da nuca para aplicar diretamente na pele. - Aplique todo o conteúdo do flaconete em um único ponto na região da nuca, evitando que o produto escorra pelos pelos. A proteção contra pulgas e carrapatos inicia-se logo após a aplicação, com eficácia superior a 90%. A ação antiparasitária mantém-se por até 49 dias, dependendo das condições ambientais e do grau de infestação. Contraindicações - Não utilizar em cães com menos de 30 dias de vida. - Não aplicar em animais com hipersensibilidade conhecida aos componentes da formulação do produto. - Não aplicar em pele lesionada. - Não utilizar em gatos. Fórmula Cada 100 mL contém: Fipronil .................................... 12,500 g Moxidectina ................................. 3,000 g Veículo q.s.p. .............................. 100,000 ml', 70.9, 70.9, NULL, 'Pets > Pet Healthcare > Medication', 'https://cf.shopee.com.br/file/sg-11134201-824gj-mdw8vhy3yfwi03', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F398944029%2F40351156721', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22495866092', 'Kit 2un Tapete Higiênico Super Secão Para Cachorro 30 Unidades', '- Indicado para cães; - Contém gel absorvente; - Possui atrativo canino; - Adesivo no tapete para melhor fixação; - Tamanho do tapete 80x60cm; - Área de absorção 60x50cm. Tapete Higiênico Super Secão C/30 Unidades SuperSecão é o tapete higiênico recomendado para as necessidades do seu cão pela casa, os tapetes higiênicos da Petix SuperSecão são ideais para você começar a treinar seu animal estimação a realizar suas necessidades apenas naquele local. Com o Tapete Higiênico para Cachorro Super Secão é possível organizar o ambiente, controlar odores e bagunças, já que o material foi formulado para facilitar a vida de qualquer dono de animal! Confeccionado em material absorvente e resistente, ele pode ser utilizado por cães adultos e filhotes., se tornando ideal para pets de todos os tamanhos e idades. O Tapete Higiênico Super Secão é fabricado com atrativo canino, gel absorvente e fita adesiva autocolante. Com ele, fica muito mais fácil cuidar de um cãozinho. O tapete pode ser fixado no chão ou nas paredes, uma medida ideal para machos e filhotes. SuperSecão ajuda seu cãozinho a fazer as necessidades no local exato, evitando a situação desagradável ao encontrar suas necessidades pelos cômodos da casa. Medidas aproximadas Área total do tapete: 80x60cm Área de absorção: 60x50cm Composição Celulose, polímeros, polietileno, polipropileno, papel, polímeros superabsorventes, fita adesiva', 179.8, 179.8, NULL, 'Pets > Litter & Toilet > Dog Training Pads & Trays', 'https://cf.shopee.com.br/file/sg-11134201-7qvd3-lhglezlvhdfbd8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F398944029%2F22495866092', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58205796066', 'Blusa Feminina Infinita Cor Amarelo', 'Blusa Feminina Infinita Cor, confeccionada em refinado Viscotorcion Rotativo. Apresenta base lisa, decote suavemente arredondado e bainhas delicadas nas mangas e no comprimento, garantindo caimento impecável. Uma peça versátil e sofisticada, ideal para compor looks básicos e despojados, acrescentando sutil toque de elegância e charme.', 79.99, 79.99, NULL, 'Women Clothes > Tops > Shirts & Blouses', 'https://cf.shopee.com.br/file/sg-11134201-8258i-mr0mmaxssb9ca5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F778895824%2F58205796066', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21670521238', 'Suplemento Sarcopen Vet Para Cães e Gatos Avert 10g', 'Sarcopen Vet Avert é um suplemento indicado para cães e gatos. Contém altos níveis de proteína e aminoácidos de cadeia ramificada (BCAAs), nutrientes essenciais aos tecidos musculares e para uma suplementação proteica adequada. Modo de usar Administrar o conteúdo de 1 sachê, diluído em cerca de 20 a 30 ml de água, por via oral, 1 vez ao dia ou a critério do profissional responsável pela nutrição de seu animal. Sempre procure um médico veterinário. Composição L-Leucina, L-Valina, L-Isoleucina, colágeno hidrolisado (48,26%), ácido ascórbico, aroma de bacon e maltodextrina.', 10.52, 10.52, NULL, 'Pets > Pet Healthcare > Medication', 'https://cf.shopee.com.br/file/sg-11134201-23010-yn5il31zkylv94', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F398944029%2F21670521238', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12546336563', 'Ração Golden Para Gatos Adultos Castrados Sabor Carne 10Kg', 'Seu gato é castrado e tem pelo menos seis meses de idade? Então você acabou de encontrar uma ótima opção de alimentação para o seu amigo! Por ser castrado, você precisa ficar atento ao peso do seu gatinho, e a Ração Golden Gatos Castrados Carne é perfeita para isso. Ela é elaborada com calorias e gorduras reduzidas, mas super completa em nutrientes. Você não precisa se preocupar em complementar a alimentação do seu gato, porque essa ração já tem tudo de que ele precisa! Além de um sabor irresistível até para os paladares mais exigentes, a Ração Golden Gatos Castrados Carne conta ainda com Taurina em sua composição, um aminoácido essencial para que seu amigo tenha coração e olhos mais saudáveis. Sua formulação também auxilia no cuidado com o trato urinário.', 183.9, 180.11, NULL, 'Pets > Pet Food > Cat Food', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lsu4t6lo9m3o5b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F398944029%2F12546336563', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
