INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22221488759', 'Colônia Pet Cachorro e Gato Hydra Groomers Forever Baby 450mL', 'Destinada ao uso profissional, a Colônia Pet Society Hydra Groomers Forever Baby é para pets que querem ficar perfumados por mais tempo. Com alta concentração de fragrância, possui longa duração e fixa duas vezes mais. Uso profissional. Fragrância Floral Talcada, com notas de laranja, flor de lótus, maçã e sândalo. Modo de Uso: Após a secagem, aplicar a Colônia Pet Society Hydra Groomers Forever Baby por toda a pelagem. Frasco: 450mL.', 250.9, 225.81, NULL, 'Pets > Pet Grooming > Hair Care', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m2lg3s9yk6j771', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F688030691%2F22221488759', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
