INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20171603058', 'Microfone Condensador Profissional Canto Podcast Bm-800', 'KIT PROFISSIONAL MICROFONE CONDENSADOR BM-800 + ACESSÓRIOS ATENÇÃO!!! PARA USO É NECESSÁRIO O USO DE PLACA DE ÁUDIO. Possuímos modelo com encaixe preto ou prata que são enviados conforme disponibilidade de estoque. - Compatível com PC, Notebook, Caixa de Som, Amplificadores, Mesa de Estúdio, etc. - Não necessita de interfaces ou softwares para eliminação de ruídos. - Ideal para gravação de áudio de instrumentos musicas. - Cabo XLR para P2 super resistente, robusto e emborrachado. - Filtra e elimina perfeitamente ruídos externos, som da respiração. - Não necessita de cabos de energia, pode ser ligado diretamente na porta P2 Itens inclusos: - 1 Microfone Condensador - 1 Cabo XLR x P2 - 1 Espuma - 1 Pop Filter - 1 Clipe de Fixação - 1 Shock Mount - 1 Braço 100% Articulado Especificações: Modelo: BM-800 - Tipo: Condensador de alto desempenho - Tamanho do diafragma: 34mm - Padrão polar: Unidirecional - Resposta de frequência: 20Hz - 20KHz - Sensibilidade: -34dB +-2dB (0dB=1V/Pa a 1kHz) - Impedância de saída: 150 +- 30% (a 1kHz) - Impedância de carga: > 1000 - Nível de ruído equivalente: 16dB - Max. nível de pressão sonora: 132dB (akHz', 173.99, 96.8, NULL, 'Audio > Microphones', 'https://cf.shopee.com.br/file/sg-11134201-7rd5x-m7hx3vq8gckp3a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F376716003%2F20171603058', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '56251163837', 'Farol Milha Fiesta Courier 2000 2001 2002 2003 2004 2005 2006 2007 2008 2009 2010 2011 2012', 'Código do produto: 5915 O farol de milha é uma peça essencial para visibilidade em vias noturnas ou em dias de neblina. Eles devem estar sempre em bom estado para maior segurança do motorista e seus ocupantes. Este item possui material de alta qualidade e resistência, composto com sua lente em vidro que deixa seu carro com aspecto diferenciado de todos os outros. Compatível com: Ford - Fiesta 2000 - Fiesta 2001 - Fiesta 2002 - Fiesta Street 2000 - Fiesta Street 2001 - Fiesta Street 2002 - Fiesta Street 2003 - Fiesta Street 2004 - Fiesta Street 2005 - Fiesta Street 2006 - Courier 2000 - Courier 2001 - Courier 2002 - Courier 2003 - Courier 2004 - Courier 2005 - Courier 2006 - Courier 2007 - Courier 2008 - Courier 2009 - Courier 2010 - Courier 2011 - Courier 2012 Especificações Técnicas: - Lente Lisa - Material da Lente em acrílico - Material da Carcaça em Plástico - Encaixe de lâmpada H1 ATENÇÃO O valor anunciado referente a Unidade mais o frete por conta do comprador. A empresa não se responsabiliza pela má instalação do produto. Procure por um profissional especializado!', 100.48, 100.48, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Lighting', 'https://cf.shopee.com.br/file/sg-11134201-821fy-mgxfhor43f9q09', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F469347212%2F56251163837', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42853493010', 'A sete chaves - Editora Arqueiro', 'Da autora de A empregada, 3 milhões de exemplares vendidos no mundo. Se quiser fazer algo errado, é melhor ter certeza de que ninguém vai descobrir. Quando tinha 11 anos, Nora Nierling nem imaginava que, enquanto fazia os deveres de casa no quarto, seu pai matava mulheres no porão. Até o dia em que ela encontrou a porta destrancada e resolveu descobrir por que o pai passava tanto tempo lá. Décadas depois, Aaron Nierling está atrás das grades – onde vai ficar para sempre – e Nora é uma cirurgiã bem-sucedida, que leva uma vida tranquila mas solitária. Ninguém sabe que ela é filha de um famoso serial killer. E ela pretende continuar assim. Um dia, porém, Nora fica sabendo que uma de suas pacientes foi assassinada. E o mais chocante: Do mesmo modo único e terrível que o pai dela usava com suas vítimas. Alguém sabe quem Nora é e quer que ela pague por esse crime. Só que ela não é uma assassina como o pai. A polícia não tem como culpá-la por nada.Desde que não entre em seu porão.', 44.9, 44.9, NULL, 'Books & Magazines > Books > Fantasy', 'https://cf.shopee.com.br/file/sg-11134201-7rauf-maow82yxznfnac', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F42853493010', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
