INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23297421783', 'Kit 4 Alto Falantes Pioneer Linha Ford Escolha Seu Carro', 'Principais Características alto falantes triaxiais: - Bobina de voz resistente ao calor - Midrange com cone de filme de 30 mm - Suspensão boleada - Tweeter piezo elétrico de 11 mm em PET - Woofer com cone de IMPP (Polipropileno moldado por injeção). ESPECIFICAÇÃO TÉCNICA ALTO FALANTES 6": Potência: - Potencia máxima PMPO - 200 W (cada Alto falante) - Potencia de entrada nominal RMS - 50 W (cada Alto falante) - Resposta em frequência - 40 Hz a 20.000 Hz - Sensibilidade (1 W / 1 m) - 86 dB - Impedância - 4 ohms Dimensões: - Profundidade de instalação – 46 mm - Dimensões do alto-falante - 165 mm x 61 mm - Dimensões para corte - 144 mm ESPECIFICAÇÃO TÉCNICA ALTO FALANTES 6": Potência: - Potencia máxima PMPO- 180 W (cada Alto falante) - Potencia de entrada nominal RMS - 50 W (cada Alto falante) - Resposta em frequência - 55 Hz a 20.000 Hz - Sensibilidade (1 W / 1 m) - 85 dB - Impedância - 4 ohms Especificação Técnicas TS-6960BR: * Modelo: TS6960BR * Diâmetro Nominal: 6x9 Polegadas * Potência RMS: 100W RMS (Cada) * Potência Musical PMPO: 400W * Impedância Nominal: 4 Ohms * Modelo Quadriaxial * Alto Falante 4 Vias * Resposta de Frequência: 40Hz a 20.000Hz * Sensibilidade: 88dB 1W/1m * Na Cor Preta com Roxo * Bobina Simples * Cone Injetado em Polipropileno * Fácil Instalação * Acompanha Grade de Acabamento * Dimensões Aproximadas (CxAxP): 25x18x10cm CONTEUDO DOS MODELOS: Modelos: - Courier: 1 Par TS-1360BR Triaxial 5" - Fusion: 1 Par TS-1760BR Triaxial 6" + 1 Par TS-6960BR Quadriaxial 6x9" - Ecosport: 2 Pares TS-1760BR Triaxial 6" - Fiesta Novo: 1 Par TS-1760BR Triaxial 6" + 1 Par TS-1360BR Triaxal 5"', 352.5, 352.5, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car A