INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '46751749161', 'Sacola de Papel Decorativa Natalina Árvore e Estrela 14x5x15x6cm', 'Celebre o espírito natalino com muito estilo utilizando a Sacola de Papel Decorada Natalina Branca com Detalhes Dourados 15x15x5, uma embalagem sofisticada que transforma qualquer presente em uma lembrança especial. Ideal para presentes pequenos e delicados, essa sacola une beleza, praticidade e sustentabilidade, tornando-se uma excelente opção para o Natal. Com acabamento branco refinado e detalhes dourados brilhantes, como estrelas, sinos, bolas natalinas, árvore e floco de neve, a sacola apresenta um design encantador e festivo. Produzida em papel de alta qualidade e resistente, é uma escolha elegante para embalar cosméticos, bijuterias, doces, acessórios ou lembrancinhas natalinas. O cordão trançado dourado confere um toque artesanal e facilita o transporte, garantindo praticidade sem perder o charme. As medidas de 15 cm de largura, 15 cm de altura e 5 cm de profundidade tornam esta sacola compacta, versátil e perfeita para lojas, eventos corporativos ou presentes pessoais. Sua estrutura firme e acabamento reluzente proporcionam uma apresentação de alto padrão, valorizando cada detalhe do presente. Além da beleza estética, a Sacola de Papel Natalina Branca e Dourada é ecológica e reciclável, refletindo um compromisso com a sustentabilidade e com o consumo consciente. É a escolha ideal para quem busca unir elegância e responsabilidade ambiental durante as festas de fim de ano. Encante seus clientes, amigos e familiares com uma embalagem de presente natalina que transmite carinho, luxo e alegria. A Sacola de Papel Decorada Natalina Branca 15x15x5 é o toque final perfeito para tornar seus presentes inesquecíveis.', 18.99, 18.99, NULL, 'Stationery > Gift & Wrapping > Gift Bags', 'https://cf.shopee.com.br/file/sg-11134201-821fa-mh98jqasszre71', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F341754426%2F46751749161', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
