INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18399885892', 'Cuba Deend De Cerâmica RotondaNero Para Banheiro 42x42x14cm', 'A cuba de cerâmica Deend Rotonda Nero traz elegância e modernidade para o banheiro, com um design redondo sofisticado que valoriza a decoração do ambiente. Seu acabamento fosco em preto oferece um visual imponente e exclusivo, tornando-se o ponto de destaque em banheiros de estilo contemporâneo. Produzida em cerâmica de alta resistência, essa cuba é prática, durável e fácil de limpar. Com formato de sobrepor, alia funcionalidade e design, garantindo praticidade no uso diário e um toque de requinte para composições minimalistas ou luxuosas. Características: Marca: Deend Modelo: D250413 Material: Cerâmica de alta resistência Formato: Redondo de sobrepor Acabamento: Preto fosco Dimensões: 13,5 cm (A) x 41,5 cm (L) x 41,5 cm (C) Benefícios: Design redondo moderno e sofisticado Acabamento fosco que transmite exclusividade Alta durabilidade e resistência para uso diário Fácil higienização e manutenção Peça versátil que combina com diversos estilos de banheiro Conteúdo da embalagem: 1 Cuba de cerâmica Deend Rotonda Nero', 342.57, 229.52, NULL, 'Home & Living > Tools & Home Improvement > Sinks & Water Taps', 'https://cf.shopee.com.br/file/sg-11134201-824ih-mpo07y9a03k128', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939446263%2F18399885892', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
