INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23494529444', 'Melatonina em Gotas - 20ml Maracujá - Catarinense Nutrição', 'A melatonina é um hormônio ligado ao ciclo circadiano, ou seja, a forma como o organismo organiza suas funções quando estamos acordados e durante o sono. A substância começa a ser produzida na glândula pineal quando o dia escurece, para ajudar o organismo a se preparar para dormir. Como Tomar Recomenda-se ingerir 1 gota antes de dormir. Gotejar com o frasco na vertical e bater levemente no fundo para iniciar o gotejamento. Este produto é indicado para indivíduos com 19 anos ou mais. Este produto não é um medicamento. Não exceder a recomendação diária de consumo indicada. Mantenha fora do alcance de crianças. Ingredientes Água; Melatonina; Agente de massa: Glicerina (INS 422); Aromatizante: Aroma idêntico ao natural de Maracujá e Acidulante: ÁCido Cítrico (INS 330). ...', 36.59, 36.59, NULL, 'Health > Food Supplement > Well Being', 'https://cf.shopee.com.br/file/sg-11134201-82588-mfx253gcum8aeb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F976704374%2F23494529444', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22098768933', 'Banqueta Para Mecânico Com Porta-Ferramentas Vonder', 'A banqueta para mecânico VONDER é uma solução prática e confortável para profissionais que atuam em oficinas, montagens e serviços automotivos. Com estrutura resistente em aço carbono e assento em plástico emborrachado, oferece durabilidade e conforto mesmo em longas jornadas de trabalho. Equipada com bandeja porta-ferramentas e rodízios giratórios independentes, proporciona mobilidade e organização durante o uso. Suporta até 135 kgf, somando o peso do operador e das ferramentas, sendo ideal para pisos lisos e nivelados. Características: Referência: 3579130000 Cor: Preta Material: Estrutura em aço carbono com assento em plástico emborrachado Medida do assento: 360 mm x 260 mm Altura máxima: 360 mm Capacidade máxima: 135 kgf Massa aproximada: 6,40 kg Benefícios: Facilita o acesso a áreas baixas com mais conforto Rodízios giratórios para fácil movimentação Bandeja integrada para manter ferramentas organizadas Alta resistência e estabilidade durante o uso Acompanha ferramentas para montagem Conteúdo da embalagem: 1x Banqueta para mecânico 2x Chaves fixas 1x Chave hexagonal', 451.58, 330.91, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rdxa-mcknn0leguv4e3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939446263%2F22098768933', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
