INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23798664926', 'Truss Nutri Infusion - Shampoo 300ml', 'Truss Nutri Infusion - Limpeza Nutritiva, Fios Fortes e com Brilho Natural Ideal para cabelos secos e opacos. Realiza uma limpeza suave enquanto trata os fios, nutrindo profundamente, devolvendo elasticidade, brilho e resistência. Enriquecido com 7 óleos poderosos, fortalece e blinda os fios contra o ressecamento, garantindo maciez, hidratação e proteção. Conselho de Aplicação Aplique nos cabelos molhados, massageando suavemente o couro cabeludo até formar espuma. Deixe agir por 2 minutos e depois enxágue. Reaplique se necessário.', 199.0, 102.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-7ra3s-mbcukvld91xfe8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322434863%2F23798664926', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
