INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '46911005204', 'Livro Versus Vol. 04 - Capa Comum', 'A guerra entre mundos avança para um novo e brutal estágio no volume 4 de VERSUS. Confrontos surpreendentes e estratégias desesperadas deixam toda a humanidade por um fio — e nada será como antes. A batalha pela sobrevivência da humanidade continua em Versus, a nova obra de ONE, o mesmo criador de One-Punch Man e Mob Psycho 100, ilustrada por Kyoutarou Azuma e com conceito de bose. A humanidade consegue transportar toda a sua base para longe e escapar dos demônios, dos alienígenas e da nova e gigantesca ameaça. Entretanto, não há lugar seguro em meio a este novo mundo. Diante de um novo inimigo, mesmo que os humanos sobrevivam aos temíveis parasitas, não escaparão das velozes motocicletas dos rebeldes de Anarquia.', 40.41, 40.41, NULL, 'Books & Magazines > Books > Comics & Manga', 'https://cf.shopee.com.br/file/sg-11134201-823po-mok2t16gyt5a03', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F46911005204', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19697458516', 'Dúvida cruel - Editora Sextante', 'Não importa se você tem 9 ou 90 anos. Se tem um espírito questionador aguçado, é provável que perguntas cabeludas fiquem martelando na sua cabeça. Afinal, o mundo é uma fonte inesgotável de curiosidade.Nesse livro, Mari e Iberê, criadores do Manual do Mundo – o canal do YouTube que, em 10 anos, conquistou mais de 14 milhões de inscritos –, reuniram 80 dúvidas cruéis escolhidas a partir das sugestões enviadas por seus seguidores.Aqui você encontrará informações científicas de qualidade com o jeito claro, atraente e divertido que virou marca registrada do canal.', 61.48, 61.48, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7rbnc-ln9do17jbyq375', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F19697458516', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18499919158', 'Copo Térmico de Cerveja Verde 700ml', 'Independente da estação do ano, o Copo Térmico de Cerveja da Mor sempre será uma excelente companhia para te manter aquecido nos dias de frio e te refrescar nos dias de calor. O mais escolhido pelos amantes de chá, café, chocolate quente, cerveja, caipira, suco, refrigerante e água. Com capacidade máxima para 700ml, a bebida quente fica conservada por 45 minutos sem a tampa e 3h se estiver com a tampa fechada; a bebida gelada permanece na mesma temperatura durante 4h se estiver sem tampa e 6h se estiver tampada; e a bebida com gelo permanece intacta em até 15h sem a tampa e 26h com a tampa fechada. O copo ainda vem com um acessório exclusivo: um abridor de garrafas acoplado na base, perfeito para quem quer estar sempre preparado para uma saideira com os amigos. São 2 produtos versáteis em um só! Disponíveis nas cores Preto, Verde e em Inox.', 59.0, 54.9, NULL, 'Home & Living > Dinnerware > Cups, Mugs & Glasses', 'https://cf.shopee.com.br/file/sg-11134201-820nd-mnlr2h8e25tte5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1583442620%2F18499919158', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
