INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58210127254', 'Água Sanitária Desinfetante de Uso Geral Ypê Frasco', 'A Água Sanitária Ypê é a solução ideal para a limpeza completa da sua casa, desde a faxina pesada até a desinfecção de alimentos. Elimina 99,9% dos germes e bactérias, proporcionando segurança e bem-estar para toda a família. * Alveja e remove manchas de tecidos brancos. * Desinfeta superfícies e elimina odores. * Bactericida e fungicida, ideal para banheiros e cozinhas. * Combate o crescimento de larvas do mosquito Aedes Aegypti.', 4.49, 4.49, NULL, 'Home & Living > Home Care Supplies > Cleaning Agents', 'https://cf.shopee.com.br/file/sg-11134201-8258f-mqnem30sxc77ba', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676552986%2F58210127254', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
