INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22094086456', 'Fertilizante Forth Cote Plus 5M 150g 15-09-12 - Forth Jardim', 'Descrição: Para quem está iniciando a jornada de cuidar de plantas, apresentamos o Forth Cote Plus 15-9-12, conhecido carinhosamente como Osmocote. Este adubo é a escolha perfeita para quem deseja uma solução versátil e completa para nutrir mudas, flores, frutos e tudo mais que seu jardim ou plantação possa oferecer. O Osmocote é um adubo completo, encapsulado e com uma durabilidade estendida de 5 meses no solo. Imagine o Osmocote como um superalimento para suas plantas, garantindo uma nutrição equilibrada em todas as fases do crescimento. Sua versatilidade permite que você o utilize em diversas situações, sem medo de errar. Seja para promover o desenvolvimento saudável de mudas, incentivar a floração exuberante das flores ou impulsionar a produção de frutos saborosos, o Forth Cote Plus 15-9-12 é a escolha completa. Se você quer simplificar sua experiência de adubação e ter a certeza de fornecer todos os nutrientes necessários para suas plantas, o Osmocote é o seu aliado ideal. Com sua liberação gradual de nutrientes, ele oferece uma nutrição constante ao longo de 5 meses, tornando o cuidado com as plantas mais prático e eficaz. Então, se você está começando a cuidar de plantas e deseja um adubo versátil, completo e de longa duração, não procure mais! ___________________________________________________________________ A MANADA ANIMAL é um marketplace de produtos veterinários. É a escolha certa para tutores que prezam pela qualidade dos produtos que seu animal necessita. Tudo com o suporte de uma equipe de veterinários e gestores com mais de 10 anos de experiência no mercado. Fique tranquilo, todos os nossos produtos são originais, adquiridos através de distribuidores credenciados! Ah, e todas as vendas acompanham nota fiscal! MANADA ANIMAL, Tranquilidade pra você, cuidado para ele!', 39.98, 31.67, NULL, 'Home & Living > Gardening > Fertilizer', 'https://cf.shopee.com.br/file/sg-11134201-7raux-mal9o5gy1j7a24', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F450664666%2F22094086456', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22494193294', 'Capacete LS2 FF358 Tank', 'Capacete LS2 FF358 Tank *Fique ligado nas especificações do Capacete LS2 FF358: - Casco em resina termoplástica HPTT (High Pressure Thermoplastic Technology) - abs de alta resistência, moldado por injeção sob pressão, projetado para oferecer excelente absorção de impacto e garantir máxima durabilidade com o mínimo de peso - Sistema de ventilação - entradas de ar superior e no queixo, aliada com as saídas traseiras para um fluxo contínuo e eficiente, promovendo resfriamento interno, controle de umidade e maior conforto térmico em qualquer condição de clima - Design aerodinâmico - moldado para reduzir a resistência do ar, permitindo que o fluxo de vento seja canalizado de maneira fluida ao redor do casco, o que reduz a turbulência, o arrasto e o esforço do pescoço durante a pilotagem - Sistema de troca de viseira LS2 Quick Release System - permite que a viseira seja removida ou instalada de forma rápida, sem a necessidade de ferramentas, o que é ideal para quem alterna entre diferentes tipos de viseira - Espumas internas cortadas a laser - permite que as espumas se moldem perfeitamente aos contornos específicos da cabeça do piloto, promovendo um ajuste anatômico extremamente confortável e seguro - Forração de alta qualidade - tecido tecnológico e respirável, com acabamento macio ao toque, totalmente removível e lavável, facilitando a limpeza e aumentando a durabilidade do capacete - Narigueira - projetada para direcionar o fluxo de ar exalado para fora da viseira, ajudando a reduzir o embaçamento durante a pilotagem, especialmente em dias frios ou com alta umidade - Sistema de fechamento - com fecho micrométrico e fivela em aço inox, com alta resistência à corrosão e travamento preciso, permitindo fácil acionamento mesmo com luvas - Peso seco aproximado (Tam. 58): 1.335 gramas *Acompanha somente a viseira transparente', 1299.9, 1299.9, NULL, 'Spare Parts and Accessories for Vehicles > Accessories for Motorcycles > Helmets', 'https://cf.shopee.com.br/file/sg-11134201-8261p-mlz4nsntn7r926', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F451914474%2F22494193294', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
