INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '51906644960', 'Serra Copo Aço Rápido Bimetal 76mm MTX', 'A serra copo MTX de 76 mm foi projetada para cortes em metal, produzida em aço rápido bimetal para maior resistência ao desgaste. Ideal para aplicações que exigem perfurações circulares em chapas e tubulações metálicas, oferece desempenho robusto em furos de diâmetro médio. Produto vendido em unidade única (1 pc), indicado para uso em furadeiras compatíveis com serras copo padrão e troca rápida de acessórios. Acabamento e dentes bimetálicos aumentam a vida útil da ferramenta quando utilizada corretamente. Características: Modelo: 724769 Referência: 724769 Marca: MTX Tipo: Serra copo para metal Material: Aço rápido bimetal Diâmetro: 76 mm Quantidade: 1 peça Código de barras (EAN): 7899612785183 Benefícios: Corte eficaz em metais graças ao corpo bimetálico. Maior durabilidade em comparação a serras comuns. Permite furos limpos e precisos de 76 mm. Produto unitário fácil de armazenar e repor. Ideal para trabalhos industriais e manutenção. Conteúdo da embalagem: 1 serra copo para metal 76 mm (1 peça)', 64.75, 49.71, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-8260c-mlc4wy49j7yn3d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939446263%2F51906644960', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
