INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22395925481', 'Limpador para Pisos Porcelanato Concentrado 1L Noviça Bettanin', 'O Noviça Pisos para Porcelanato é um produto concentrado, mas pode ser usado puro ou diluído. É ideal para limpeza pesada e manutenção semanal de superfícies rústicas, como pisos de pedras naturais. Pode render até 30 litros e deve ser manuseado com luvas.', 39.9, 34.9, NULL, 'Home & Living > Home Care Supplies > Cleaning Agents', 'https://cf.shopee.com.br/file/sg-11134201-7rfgd-m94ymlzi93m92d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F816806234%2F22395925481', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22298545319', 'Bio Extratus Specialiste Matizante Cinza - Mascara 90g', 'Bio Extratus Specialiste Matizante Cinza - Mascara 90g Para cabelos loiros ou com luzes, possui alta concentração de pigmento cinza que corrige o tom alaranjado dos fios, conferindo brilho platinado, desde a primeira aplicação. Fórmula com alto poder de tratamento que combina a ação antioxidante, reconstrutora e hidratante dos ativos naturais, promovendo um tratamento completo dos fios. Conselho de aplicação Após lavar o cabelo, aplique a máscara massageando mecha a mecha. Deixe agir por 3 minutos. Enxague bem até sair toda a cor cinza da mascara. Pode ser misturada a uma máscara branca Bio Extratus, caso deseje reduzir o efeito matizador. Enxágue bem, até sair toda a cor cinza do produto.', 69.25, 42.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-7rast-ma47sdl8dne300', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322434863%2F22298545319', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23094027501', 'Haskell Murumuru - Máscara de Tratamento Capilar 900g', 'Haskell Murumuru - Máscara de Tratamento Capilar 900g Indicado para cabelos muito secos, proporciona nutrição intensa aos fios. Sua ação altamente emoliente condiciona e devolve nutrientes essenciais para cabelos saudáveis, com brilho e livres do ressecamento. Desenvolvida para nutrir intensamente os cabelos secos e sem vida. Essa linha age profundamente na fibra capilar, preenchendo as fissuras e alinhando as cutículas. O ativo Manteiga de Murumuru, aliado a uma formulação concentrada, recupera os cabelos desidratados e sem nutrientes, e devolve o brilho, a elasticidade e a vitalidade dos fios. Direção olfativa: oriental, frutal, amadeirado, ambarado. Etapa do cronograma: nutrição. Conselho de Aplicação Após lavar os cabelos, aplique a máscara mecha por mecha, do comprimento às pontas. Massageie e deixe agir de 3 a 5 minutos. Se preferir, faça o uso de touca térmica. Enxague em seguida, retirando todo o resíduo de creme dos cabelos. Potencialize os resultados utilizando toda a linha Murumuru.', 253.5, 139.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-7ravo-ma2uo4799bpt5c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322434863%2F23094027501', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23098525385', 'Giorno Bagno Flor de Laranjeira & Vetiver- Sabonete Natural 180g', 'Giorno Bagno Flor de Laranjeira & Vetiver- Sabonete Natural 180g Sabonetes com perfumes delicados e formulação suave, proporcionam uma agradável maciez e hidratação da pele. Um sabonete 100% vegetal com alto poder emoliente, inspirado nos sabonetes italianos e cuidadosamente embrulhado à mão. Possui muita cremosidade, proporcionando hidratação extra e de longa duração. As notas olfativas desta versão são: Saída: Complexo Herbal, Laranja Fresca, Bergamota, Limão, Petitgrain, Basilicão. Corpo: Ylang-Ylang, Ciclâmen Frances, Jasmim Imperial, Rosas Damascena, Lírio do Vale, Pimenta Rosa, Acorde Especiado. Fundo: Patchouli, Musk, Cedro Florida, Complexo Amadeirado, Sândalo, Vetiver, Musgo de Carvalho. Conselho de Aplicação Espalhe o sabonete sobre o corpo úmido, massageando a pele suavemente. Enxague como de costume.', 58.75, 33.9, NULL, 'Beauty > Bath & Body Care > Body Wash & Soap', 'https://cf.shopee.com.br/file/sg-11134201-7rat6-ma43nvejvgskab', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322434863%2F23098525385', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
