INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19450004435', 'Borracha Porta Corsa 1994 a 2002 Hatch Sedan Vedação Premium', 'Borracha de Porta – Chevrolet Corsa Hatch / Sedan 1994 a 2002 – Vedação Premium A Borracha de Porta para Chevrolet Corsa Hatch e Sedan é fabricada em material premium de alta resistência, garantindo vedação eficiente, encaixe perfeito e longa durabilidade. Ideal para substituir a borracha original ressecada ou danificada, evita infiltrações de água, entrada de poeira e ruídos externos, proporcionando mais conforto no interior do veículo. Produto novo, desenvolvido no padrão tipo original, com instalação simples. Compatibilidade: Corsa Hatch 1994 Até 2002 Corsa Sedan 1994 Até 2002 Corsa Wagon 1994 Até 2002 Pickup Corsa 1994 Até 2002 Corsa Classic 2003 Até 2012 (Aplicação nas portas do veículo.) Características: Vedação Premium Excelente proteção contra água e poeira Reduz ruídos externos Material resistente e durável Encaixe perfeito Padrão tipo original Produto novo Conteúdo da Embalagem: 1 Borracha de Porta Chevrolet Corsa 1994–2002 Tempo de Garantia: GARANTIA 3 MESES Observações: PARA EVITAR PROBLEMAS NA INSTALAÇÃO DO PRODUTO ELA DEVE SER FEITA POR UM PROFISSIONAL', 85.38, 76.85, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Others', 'https://cf.shopee.com.br/file/8be8c6db50b66754c6f6b3fb33f5cb73', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F691145803%2F19450004435', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
